### OPTION 1: AWS SECRETS MANAGER (Best for AWS-hosted apps)

**Code Implementation**:
```javascript
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

let cachedSecrets = null;

async function getSecrets() {
  if (cachedSecrets) {
    return cachedSecrets;
  }

  try {
    const response = await secretsManager.getSecretValue({
      SecretId: process.env.SECRET_NAME || 'myapp/prod/secrets'
    }).promise();

    if ('SecretString' in response) {
      cachedSecrets = JSON.parse(response.SecretString);
      return cachedSecrets;
    }
  } catch (error) {
    console.error('Failed to fetch secrets:', error);
    throw error;
  }
}

// Usage in app.js
const express = require('express');
const app = express();

(async () => {
  const secrets = await getSecrets();

  const JWT_SECRET = secrets.JWT_SECRET;
  const DATABASE_URL = secrets.DATABASE_URL;
  const STRIPE_SECRET_KEY = secrets.STRIPE_SECRET_KEY;

  // Initialize app with secrets
  app.listen(3000, () => {
    console.log('Server started with secrets from AWS Secrets Manager');
  });
})();
```

### OPTION 2: HASHICORP VAULT (Enterprise-grade)

**Code Implementation**:
```javascript
const NodeVault = require('node-vault');

const vault = new NodeVault({
  endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
  token: process.env.VAULT_TOKEN
});

async function getSecrets() {
  try {
    const response = await vault.read(`secret/data/myapp/prod`);
    return response.data.data; // Vault v2 has nested data structure
  } catch (error) {
    console.error('Failed to fetch from Vault:', error);
    throw error;
  }
}

// Usage
(async () => {
  const secrets = await getSecrets();
  const JWT_SECRET = secrets.jwt_secret;
  // ...
})();
```

### OPTION 3: GOOGLE SECRET MANAGER (Best for GCP)

**Code Implementation**:
```javascript
const {SecretManagerServiceClient} = require('@google-cloud/secret-manager');

const client = new SecretManagerServiceClient();

async function getSecrets() {
  const projectId = process.env.GCP_PROJECT_ID;
  const secretName = `projects/${projectId}/secrets/myapp-secrets/versions/latest`;

  try {
    const [version] = await client.accessSecretVersion({
      name: secretName,
    });

    const secretString = version.payload.data.toString('utf8');
    return JSON.parse(secretString);
  } catch (error) {
    console.error('Failed to fetch from GCP Secret Manager:', error);
    throw error;
  }
}
```

### OPTION 4: AZURE KEY VAULT (Best for Azure)

**Code Implementation**:
```javascript
const { SecretClient } = require("@azure/keyvault-secrets");
const { DefaultAzureCredential } = require("@azure/identity");

async function getSecrets() {
  const keyVaultUrl = process.env.KEY_VAULT_URL;
  const credential = new DefaultAzureCredential();
  const client = new SecretClient(keyVaultUrl, credential);

  try {
    const jwtSecret = await client.getSecret("jwt-secret");
    const dbUrl = await client.getSecret("database-url");
    const stripeKey = await client.getSecret("stripe-secret-key");

    return {
      JWT_SECRET: jwtSecret.value,
      DATABASE_URL: dbUrl.value,
      STRIPE_SECRET_KEY: stripeKey.value
    };
  } catch (error) {
    console.error('Failed to fetch from Azure Key Vault:', error);
    throw error;
  }
}
```

