### OPTION 3: GOOGLE SECRET MANAGER (Best for GCP)

**Code Implementation**:
```javascript
const {SecretManagerServiceClient} = require('@google-cloud/secret-manager');

const client = new SecretManagerServiceClient();

async function getSecrets() {
  const projectId = process.env.GCP_PROJECT_ID;
  const secretName = `projects/${projectId}/secrets/myapp-secrets/versions/latest`;

  try {
    const [version] = await client.accessSecretVersion({
      name: secretName,
    });

    const secretString = version.payload.data.toString('utf8');
    return JSON.parse(secretString);
  } catch (error) {
    console.error('Failed to fetch from GCP Secret Manager:', error);
    throw error;
  }
}
