### OPTION 4: AZURE KEY VAULT (Best for Azure)

**Code Implementation**:
```javascript
const { SecretClient } = require("@azure/keyvault-secrets");
const { DefaultAzureCredential } = require("@azure/identity");

async function getSecrets() {
  const keyVaultUrl = process.env.KEY_VAULT_URL;
  const credential = new DefaultAzureCredential();
  const client = new SecretClient(keyVaultUrl, credential);

  try {
    const jwtSecret = await client.getSecret("jwt-secret");
    const dbUrl = await client.getSecret("database-url");
    const stripeKey = await client.getSecret("stripe-secret-key");

    return {
      JWT_SECRET: jwtSecret.value,
      DATABASE_URL: dbUrl.value,
      STRIPE_SECRET_KEY: stripeKey.value
    };
  } catch (error) {
    console.error('Failed to fetch from Azure Key Vault:', error);
    throw error;
  }
}
