## STEP 4: CREATE secrets-config.js

```javascript
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

let cachedSecrets = null;
let secretsCacheTTL = 3600000; // 1 hour

class SecretsManager {
  constructor() {
    this.lastFetched = 0;
  }

  async getSecrets() {
    const now = Date.now();

    // Return cached secrets if still valid
    if (cachedSecrets && (now - this.lastFetched) < secretsCacheTTL) {
      console.log('Returning cached secrets');
      return cachedSecrets;
    }

    try {
      const secretName = process.env.SECRET_NAME || 'myapp/prod/secrets';

      console.log(`Fetching secrets from AWS Secrets Manager: ${secretName}`);

      const response = await secretsManager.getSecretValue({
        SecretId: secretName
      }).promise();

      if ('SecretString' in response) {
        cachedSecrets = JSON.parse(response.SecretString);
        this.lastFetched = now;
        console.log('✓ Secrets fetched successfully');
        return cachedSecrets;
      } else {
        throw new Error('Secret value not found as string');
      }
    } catch (error) {
      console.error('✗ Failed to fetch secrets from AWS Secrets Manager:', error);

      // In development, try .env file
      if (process.env.NODE_ENV !== 'production') {
        console.warn('Falling back to environment variables');
        return {
          JWT_SECRET: process.env.JWT_SECRET,
          DATABASE_URL: process.env.DATABASE_URL,
          STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
          ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
          LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
        };
      }

      throw error;
    }
  }

  // Validate required secrets
  async validateSecrets(secrets) {
    const required = ['JWT_SECRET', 'DATABASE_URL'];
    const missing = required.filter(key => !secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    return true;
  }
}

module.exports = new SecretsManager();
```

