  dotenv.config();
}

const secretsManager = new AWS.SecretsManager({ 
  region: process.env.AWS_REGION || 'us-east-1' 
});

class SecretsProvider {
  constructor() {
    this.cache = {};
    this.ttl = 60 * 60 * 1000; // 1 hour cache
    this.lastLoad = {};
  }

  async getSecret(secretId) {
    // Return cached secret if not expired
    if (this.cache[secretId] && this.isValid(secretId)) {
      return this.cache[secretId];
    }

    try {
      let secretValue;

      if (process.env.NODE_ENV === 'production') {
        // Use Secrets Manager in production
        const result = await secretsManager
          .getSecretValue({ SecretId: secretId })
          .promise();

        secretValue = JSON.parse(result.SecretString);
      } else {
        // Fall back to environment variables in dev
        secretValue = {
          DATABASE_URL: process.env.DATABASE_URL,
          JWT_SECRET: process.env.JWT_SECRET,
          AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
          AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
          API_KEY: process.env.API_KEY,
        };
      }

      this.cache[secretId] = secretValue;
      this.lastLoad[secretId] = Date.now();
      return secretValue;
    } catch (err) {
      console.error(`Error loading secret ${secretId}:`, err);
      throw err;
    }
  }

  isValid(secretId) {
    return Date.now() - this.lastLoad[secretId] < this.ttl;
  }

  clearCache(secretId) {
    delete this.cache[secretId];
    delete this.lastLoad[secretId];
  }

  clearAllCache() {
    this.cache = {};
    this.lastLoad = {};
  }
}

