## 🔍 Common Vulnerabilities & Fixes

### Vulnerability 1: No Authentication
**Problem**: Anyone can access sensitive data
```javascript
// ❌ Wrong
app.get('/users', (req, res) => {
  res.json(users);
});

// ✅ Right
app.get('/users', authenticateToken, (req, res) => {
  res.json(users);
});
```

### Vulnerability 2: No Input Validation
**Problem**: Injection attacks
```javascript
// ❌ Wrong
app.post('/search', (req, res) => {
  const results = db.query(`SELECT * FROM items WHERE name='${req.body.name}'`);
  res.json(results);
});

// ✅ Right
app.post('/search', [
  body('name').trim().isLength({ min: 1, max: 100 }).escape(),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) return res.status(400).json({ errors });
  const results = db.query('SELECT * FROM items WHERE name = ?', [req.body.name]);
  res.json(results);
});
```

### Vulnerability 3: Missing Security Headers
**Problem**: XSS, clickjacking, MIME-sniffing
```javascript
// ❌ Wrong
app.use(express.json());

// ✅ Right
const helmet = require('helmet');
app.use(helmet());
```

### Vulnerability 4: No Rate Limiting
**Problem**: Brute force attacks
```javascript
// ❌ Wrong
app.post('/login', (req, res) => { ... });

// ✅ Right
const rateLimit = require('express-rate-limit');
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

app.post('/login', loginLimiter, (req, res) => { ... });
```

### Vulnerability 5: Hardcoded Secrets
**Problem**: Secrets exposed in code
```javascript
// ❌ Wrong
const SECRET = 'my-secret-key';
const DB_PASSWORD = 'admin123';

// ✅ Right
require('dotenv').config();
const SECRET = process.env.JWT_SECRET;
const DB_PASSWORD = process.env.DB_PASSWORD;

if (!SECRET) throw new Error('JWT_SECRET required');
```

### Vulnerability 6: Unlimited Request Size
**Problem**: DoS attack
```javascript
// ❌ Wrong
app.use(express.json());

// ✅ Right
app.use(express.json({ limit: '1mb' }));
```

### Vulnerability 7: No Error Handling
**Problem**: Stack traces exposed
```javascript
// ❌ Wrong
app.get('/api/data', (req, res) => {
  const data = JSON.parse(req.body);
  res.json(data);
});

// ✅ Right
app.get('/api/data', (req, res, next) => {
  try {
    const data = JSON.parse(req.body);
    res.json(data);
  } catch (err) {
    next(err);
  }
});

app.use((err, req, res, next) => {
  logger.error('Error', err);
  res.status(500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal error' 
      : err.message,
  });
});
```

### Vulnerability 8: No CORS Configuration
**Problem**: Cross-origin attacks
```javascript
// ❌ Wrong
// CORS not configured or too permissive

// ✅ Right
const cors = require('cors');
app.use(cors({
  origin: ['https://trusted-domain.com'],
  methods: ['GET', 'POST'],
  credentials: true,
}));
```

### Vulnerability 9: HTTP Only
**Problem**: Data transmitted in plaintext
```javascript
// ❌ Wrong
app.listen(3000);

// ✅ Right
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      return res.redirect(`https://${req.header('host')}${req.url}`);
    }
    next();
  });
}
```

### Vulnerability 10: No Logging
**Problem**: Cannot detect attacks
```javascript
// ❌ Wrong
console.log('Server started');

// ✅ Right
const winston = require('winston');
const logger = winston.createLogger({
  transports: [
    new winston.transports.File({ filename: 'combined.log' }),
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
  ],
});

app.use((req, res, next) => {
  res.on('finish', () => {
    if (res.statusCode >= 400) {
      logger.warn('Error response', {
        method: req.method,
        path: req.path,
        status: res.statusCode,
      });
    }
  });
  next();
});
```

