// Secure version of app.js with security best practices
// Install dependencies: npm install express helmet express-rate-limit express-validator jsonwebtoken winston cors dotenv

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');
require('dotenv').config();

// ============================================
// VALIDATION & SECURITY SETUP
// ============================================

// Validate required environment variables
const requiredEnvVars = ['JWT_SECRET', 'NODE_ENV'];
requiredEnvVars.forEach(envVar => {
  if (!process.env[envVar]) {
    console.error(`Missing required environment variable: ${envVar}`);
    process.exit(1);
  }
});

// ============================================
// LOGGING SETUP
// ============================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'user-api' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================
// EXPRESS APP SETUP
// ============================================

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Security Headers with Helmet
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  },
}));
app.use(helmet.hsts({ 
  maxAge: 31536000, 
  includeSubDomains: true,
  preload: true 
}));

// 2. CORS Configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};
app.use(cors(corsOptions));

// 3. Body parser with size limits (prevent large payload attacks)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Rate Limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => {
    // Don't rate limit health checks
    return req.path === '/health';
  },
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: false,
  message: 'Too many requests to this endpoint, please try again later.',
});

app.use(generalLimiter);
app.use('/users', strictLimiter);

// 5. Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
    });
  });

  next();
});

// ============================================
// AUTHENTICATION MIDDLEWARE
// ============================================

const authMiddleware = (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader) {
      logger.warn(`Unauthorized access attempt to ${req.path} from ${req.ip}`);
      return res.status(401).json({ 
        error: 'Unauthorized',
        message: 'No authentication token provided'
      });
    }

    const parts = authHeader.split(' ');
    if (parts.length !== 2 || parts[0] !== 'Bearer') {
      return res.status(401).json({ 
        error: 'Unauthorized',
        message: 'Invalid token format'
      });
    }

    const token = parts[1];

    try {
      const decoded = jwt.verify(token, process.env.JWT_SECRET);
      req.user = decoded;
      next();
    } catch (jwtError) {
      if (jwtError.name === 'TokenExpiredError') {
        logger.warn(`Expired token from ${req.ip}`);
        return res.status(401).json({ 
          error: 'Unauthorized',
          message: 'Token has expired'
        });
      }

      logger.warn(`Invalid token from ${req.ip}`);
      return res.status(403).json({ 
        error: 'Forbidden',
        message: 'Invalid token'
      });
    }
  } catch (error) {
    logger.error(`Auth middleware error: ${error.message}`);
    return res.status(500).json({ 
      error: 'Internal server error'
    });
  }
};

// ============================================
// ROUTES
// ============================================

// Health check (no auth required, but rate limited)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV
  });
});

// Protected users endpoint with validation
app.get('/users',
  authMiddleware,
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be >= 0')
    .toInt(),
  (req, res, next) => {
    try {
      // Validate query parameters
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation failed',
          details: errors.array()
        });
      }

      const limit = Math.min(req.query.limit || 10, 100);
      const offset = Math.max(req.query.offset || 0, 0);

      // Mock user data (in production, this would come from a database)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      ];

      // Sanitize response based on user role
      const sanitizeUser = (user) => {
        if (req.user?.role === 'admin') {
          // Admins see all fields
          return user;
        }
        // Regular users only see name and id
        return {
          id: user.id,
          name: user.name,
        };
      };

      const paginatedUsers = users
        .slice(offset, offset + limit)
        .map(sanitizeUser);

      res.json({
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: users.length,
        },
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV === 'development';

  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  const status = err.status || err.statusCode || 500;
  const response = {
    error: {
      message: isDevelopment ? err.message : 'Internal server error',
    },
  };

  if (isDevelopment) {
    response.error.stack = err.stack;
    response.error.details = err;
  }

  res.status(status).json(response);
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;
EOF

