// Secure version of the application with security best practices implemented
// This version addresses all vulnerabilities identified in the security review

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

const app = express();

// ============================================================================
// 1. CONFIGURATION MANAGEMENT
// ============================================================================
const config = {
  port: process.env.PORT || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',
  jwtSecret: process.env.JWT_SECRET || 'dev-secret-change-in-production',
  allowedOrigins: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
};

// Validate required configs in production
if (config.nodeEnv === 'production') {
  if (config.jwtSecret === 'dev-secret-change-in-production') {
    throw new Error('JWT_SECRET environment variable must be set in production');
  }
}

// ============================================================================
// 2. SECURITY HEADERS
// ============================================================================
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
}));

// ============================================================================
// 3. HTTPS ENFORCEMENT
// ============================================================================
app.use((req, res, next) => {
  if (config.nodeEnv === 'production' && req.header('x-forwarded-proto') !== 'https') {
    return res.redirect(301, `https://${req.header('host')}${req.url}`);
  }
  next();
});

// ============================================================================
// 4. CORS CONFIGURATION
// ============================================================================
const corsOptions = {
  origin: config.allowedOrigins,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  optionsSuccessStatus: 200,
  maxAge: 86400, // Pre-flight cache for 24 hours
};

app.use(cors(corsOptions));

// ============================================================================
// 5. BODY PARSER
// ============================================================================
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// ============================================================================
// 6. LOGGING
// ============================================================================
// Create logs directory if it doesn't exist
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir, { recursive: true });
}

// Access logging
const accessLogStream = fs.createWriteStream(
  path.join(logsDir, 'access.log'),
  { flags: 'a' }
);

app.use(morgan(':remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] :response-time ms', {
  stream: accessLogStream
}));

// Security event logger
const logSecurityEvent = (eventType, details) => {
  const logEntry = JSON.stringify({
    timestamp: new Date().toISOString(),
    eventType,
    ...details,
  });
  console.log(logEntry);
  // In production, send to centralized logging service (ELK, Splunk, DataDog, etc.)
};

// ============================================================================
// 7. RATE LIMITING
// ============================================================================
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => {
    // Don't count health checks in rate limiting
    return req.path === '/health';
  },
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // limit each IP to 5 login attempts per 15 minutes
  message: 'Too many login attempts, please try again later.',
  skipSuccessfulRequests: true, // Don't count successful requests
});

// ============================================================================
// 8. AUTHENTICATION MIDDLEWARE
// ============================================================================
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    logSecurityEvent('AUTH_MISSING_TOKEN', {
      ip: req.ip,
      path: req.path,
      method: req.method,
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, config.jwtSecret, (err, user) => {
    if (err) {
      logSecurityEvent('AUTH_INVALID_TOKEN', {
        ip: req.ip,
        path: req.path,
        method: req.method,
        error: err.message,
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ============================================================================
// 9. AUTHORIZATION MIDDLEWARE
// ============================================================================
const authorizeRole = (requiredRoles = []) => {
  return (req, res, next) => {
    const userRole = req.user?.role;
    const isAuthorized = requiredRoles.length === 0 || 
                        requiredRoles.includes(userRole) || 
                        userRole === 'admin';

    if (!isAuthorized) {
      logSecurityEvent('AUTHZ_INSUFFICIENT_PERMISSIONS', {
        ip: req.ip,
        userId: req.user?.id,
        path: req.path,
        method: req.method,
        requiredRoles,
        userRole,
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

