  if (username === 'admin' && password === 'password') {
    const token = jwt.sign(
      { id: 1, username, role: 'admin' },
      config.jwtSecret,
      { expiresIn: '1h' }
    );

    logSecurityEvent('LOGIN_SUCCESS', {
      ip: req.ip,
      username,
    });

    return res.json({ token, expiresIn: 3600 });
  }

  logSecurityEvent('LOGIN_FAILED', {
    ip: req.ip,
    username,
  });

  res.status(401).json({ error: 'Invalid credentials' });
});

// ============================================================================
// 11. PROTECTED ENDPOINTS (Authentication required)
// ============================================================================

// Get users - with input validation and authorization
app.get('/users', 
  limiter,
  authenticateToken,
  authorizeRole(['user', 'admin']),
  [
    query('id').optional().isInt().toInt(),
    query('limit').optional().isInt().toInt().custom(val => val <= 100),
    query('sort').optional().isIn(['id', 'name']), // Whitelist only safe sort fields
    query('offset').optional().isInt().toInt().custom(val => val >= 0),
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logSecurityEvent('USERS_VALIDATION_ERROR', {
        ip: req.ip,
        userId: req.user?.id,
        errors: errors.array(),
      });
      return res.status(400).json({ errors: errors.array() });
    }

    const { id, limit = 10, sort = 'id', offset = 0 } = req.query;

    logSecurityEvent('USERS_DATA_ACCESS', {
      ip: req.ip,
      userId: req.user?.id,
      userRole: req.user?.role,
      queryParams: { id, limit, sort, offset },
    });

    // Fetch user data (hardcoded for demonstration)
    const allUsers = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
      { id: 3, name: 'Charlie' },
    ];

    // Filter by ID if provided
    let users = id ? allUsers.filter(u => u.id === id) : allUsers;

    // Apply pagination
    users = users.slice(offset, offset + limit);

    // Only expose email if user is admin
    if (req.user.role !== 'admin') {
      users = users.map(({ email, ...rest }) => rest); // Remove email for non-admin
    }

    // Sort results
    users.sort((a, b) => {
      if (sort === 'id') return a.id - b.id;
      if (sort === 'name') return a.name.localeCompare(b.name);
      return 0;
    });

    res.json({
      data: users,
      pagination: {
        limit,
        offset,
        total: allUsers.length,
      },
    });
  }
);

// Get specific user
app.get('/users/:userId',
  limiter,
  authenticateToken,
  authorizeRole(['user', 'admin']),
  (req, res) => {
    const { userId } = req.params;

    // Validate userId is a number
    if (!/^\d+$/.test(userId)) {
      logSecurityEvent('USERS_INVALID_ID', {
        ip: req.ip,
        userId: req.user?.id,
        providedId: userId,
      });
      return res.status(400).json({ error: 'Invalid user ID format' });
    }

    logSecurityEvent('USERS_DETAIL_ACCESS', {
      ip: req.ip,
      userId: req.user?.id,
      targetUserId: userId,
      userRole: req.user?.role,
    });

    // Check authorization - users can only see their own data unless admin
    if (req.user.role !== 'admin' && req.user.id !== parseInt(userId)) {
      logSecurityEvent('AUTHZ_USER_DETAIL_DENIED', {
        ip: req.ip,
        userId: req.user?.id,
        targetUserId: userId,
      });
      return res.status(403).json({ error: 'Cannot access other user\'s data' });
    }

    // Fetch user data (hardcoded for demonstration)
    const user = { id: parseInt(userId), name: 'Alice', email: 'alice@example.com' };

    res.json(user);
  }
);

// ============================================================================
// 12. ERROR HANDLING
// ============================================================================

// 404 handler - must be after all routes
app.use((req, res) => {
  logSecurityEvent('ROUTE_NOT_FOUND', {
    ip: req.ip,
    path: req.path,
    method: req.method,
  });
  res.status(404).json({ error: 'Endpoint not found' });
});

// Global error handling middleware - must be last
app.use((err, req, res, next) => {
  // Log the error securely
  logSecurityEvent('APPLICATION_ERROR', {
    ip: req.ip,
    path: req.path,
    method: req.method,
    error: err.message,
    stack: config.nodeEnv === 'development' ? err.stack : undefined,
  });

  // Don't expose error details to client in production
  const statusCode = err.statusCode || 500;
  const message = config.nodeEnv === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(statusCode).json({
    error: message,
    status: statusCode,
    ...(config.nodeEnv === 'development' && { stack: err.stack }),
  });
});

// ============================================================================
// 13. SERVER STARTUP
// ============================================================================
app.listen(config.port, () => {
  console.log(`Server running on port ${config.port} (${config.nodeEnv} environment)`);
  logSecurityEvent('SERVER_STARTED', {
    port: config.port,
    nodeEnv: config.nodeEnv,
  });
});

module.exports = app;

