## 🔒 PRODUCTION-READY SECRETS LOADING

```javascript
// config/secrets.js
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.cached = {};
    this.cacheExpiry = 300000; // 5 minutes
  }

  async load(secretName) {
    // Return cached if valid
    if (this.cached[secretName] && 
        Date.now() - this.cached[secretName].loadedAt < this.cacheExpiry) {
      return this.cached[secretName].value;
    }

    const client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    try {
      const response = await client.getSecretValue({
        SecretId: secretName
      }).promise();

      const secretValue = JSON.parse(response.SecretString);

      // Cache it
      this.cached[secretName] = {
        value: secretValue,
        loadedAt: Date.now()
      };

      return secretValue;
    } catch (error) {
      console.error(`Failed to load secret ${secretName}:`, error);
      throw error;
    }
  }

  async loadAll(secretNames) {
    const secrets = {};

    for (const name of secretNames) {
      secrets[name] = await this.load(name);
    }

    return secrets;
  }
}

module.exports = new SecretsManager();
```

**Usage:**
