const secretsManager = require('./config/secrets');

async function startApp() {
  try {
    const dbSecret = await secretsManager.load('prod/database');
    const apiSecret = await secretsManager.load('prod/api');

    process.env.DATABASE_URL = dbSecret.url;
    process.env.API_KEY = apiSecret.key;

    startServer();
  } catch (error) {
    console.error('Failed to initialize secrets:', error);
    process.exit(1);
  }
}

startApp();
```

