Create `.git/hooks/pre-commit`:

```bash
#!/bin/bash
# Prevent secrets from being committed

patterns=(
    "sk_live_"
    "sk_test_"
    "AKIA"
    "sk-ant-"
    "DATABASE_URL"
    "AWS_SECRET"
    "STRIPE_SECRET"
)

for pattern in "${patterns[@]}"; do
    if git diff --cached | grep -q "$pattern"; then
        echo "❌ BLOCKED: Potential secret detected in commit: $pattern"
        exit 1
    fi
done

exit 0
```

