### **Strategy 1: AWS Secrets Manager (Cloud-Native)**
**Best for:** AWS deployments, enterprise applications

```javascript
// ✅ RECOMMENDED: AWS Secrets Manager
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    const now = Date.now();
    const cached = this.cache.get(secretName);

    // Return cached secret if fresh
    if (cached && (now - cached.timestamp) < this.cacheTTL) {
      return cached.value;
    }

    try {
      const data = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: now
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }

  async validateSecrets(requiredSecrets) {
    const missing = [];
    for (const secret of requiredSecrets) {
      try {
        await this.getSecret(secret);
      } catch (error) {
        missing.push(secret);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }
}

module.exports = SecretsManager;
```

