### **Strategy 2: HashiCorp Vault (Multi-Cloud, Enterprise)**
**Best for:** Multi-cloud, zero-trust architecture, advanced requirements

```javascript
// ✅ RECOMMENDED: HashiCorp Vault
const vault = require('node-vault');

class VaultSecretsManager {
  constructor() {
    this.client = vault({
      endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
      token: process.env.VAULT_TOKEN,
      apiVersion: 'v1',
    });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes (shorter for Vault)
  }

  async getSecret(path) {
    const now = Date.now();
    const cached = this.cache.get(path);

    if (cached && (now - cached.timestamp) < this.cacheTTL) {
      return cached.value;
    }

    try {
      const response = await this.client.read(`secret/data/${path}`);
      const secret = response.data.data;

      this.cache.set(path, {
        value: secret,
        timestamp: now
      });

      return secret;
    } catch (error) {
      console.error(`Vault secret retrieval failed for ${path}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${path}`);
    }
  }

  async rotateSecret(path, newSecret) {
    try {
      await this.client.write(`secret/data/${path}`, {
        data: newSecret
      });

      // Invalidate cache
      this.cache.delete(path);

      console.log(`Secret rotated: ${path}`);
    } catch (error) {
      console.error(`Secret rotation failed for ${path}:`, error.message);
      throw error;
    }
  }

  // Dynamic database credentials
  async getDatabaseCredentials() {
    try {
      const response = await this.client.read('database/static-creds/app-user');
      return {
        username: response.data.username,
        password: response.data.password,
        ttl: response.lease_duration
      };
    } catch (error) {
      console.error('Failed to retrieve DB credentials:', error.message);
      throw error;
    }
  }
}

module.exports = VaultSecretsManager;
```

