// ✅ RECOMMENDED: Kubernetes-aware secrets
const fs = require('fs');
const path = require('path');

class KubernetesSecretsManager {
  constructor(secretsPath = '/var/run/secrets/app') {
    this.secretsPath = secretsPath;
    this.secrets = {};
    this.loadSecrets();
  }

  loadSecrets() {
    if (!fs.existsSync(this.secretsPath)) {
      console.warn(`Secrets path not found: ${this.secretsPath}`);
      return;
    }

    const files = fs.readdirSync(this.secretsPath);
    for (const file of files) {
      const filePath = path.join(this.secretsPath, file);
      const value = fs.readFileSync(filePath, 'utf8').trim();
      this.secrets[file] = value;
    }

    console.log(`Loaded ${Object.keys(this.secrets).length} secrets`);
  }

  getSecret(key) {
    if (!this.secrets[key]) {
      throw new Error(`Secret not found: ${key}`);
    }
    return this.secrets[key];
  }

  validateSecrets(requiredSecrets) {
    const missing = requiredSecrets.filter(s => !this.secrets[s]);
    if (missing.length > 0) {
      throw new Error(`Missing secrets: ${missing.join(', ')}`);
    }
  }
}

module.exports = KubernetesSecretsManager;
