### **OPTION 1: Using AWS Secrets Manager (Recommended for Production)**

```javascript
// config/secrets.js
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

class SecretsConfig {
  constructor() {
    this.secrets = null;
    this.lastFetch = null;
    this.cacheTTL = 3600000; // 1 hour
  }

  async load() {
    // Use cached secrets if fresh
    if (this.secrets && Date.now() - this.lastFetch < this.cacheTTL) {
      return this.secrets;
    }

    try {
      const response = await secretsManager.getSecretValue({
        SecretId: process.env.SECRET_NAME || 'myapp/secrets'
      }).promise();

      this.secrets = JSON.parse(response.SecretString);
      this.lastFetch = Date.now();

      this.validate();
      return this.secrets;
    } catch (error) {
      console.error('Failed to load secrets from AWS Secrets Manager', error);
      throw new Error('Failed to initialize secrets');
    }
  }

  validate() {
    const required = [
      'ACCESS_TOKEN_SECRET',
      'REFRESH_TOKEN_SECRET',
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN'
    ];

    const missing = required.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    // Validate secret format
    if (!this.secrets.ACCESS_TOKEN_SECRET.length >= 32) {
      throw new Error('ACCESS_TOKEN_SECRET must be at least 32 characters');
    }

    if (!this.secrets.DATABASE_URL.startsWith('postgres://') && 
        !this.secrets.DATABASE_URL.startsWith('postgresql://')) {
      throw new Error('Invalid DATABASE_URL format');
    }

    if (!this.secrets.AWS_ACCESS_KEY_ID.startsWith('AKIA')) {
      throw new Error('Invalid AWS_ACCESS_KEY_ID format');
    }
  }

  get(key) {
    if (!this.secrets) {
      throw new Error('Secrets not loaded. Call load() first');
    }
    return this.secrets[key];
  }
}

module.exports = new SecretsConfig();
