### **2. Secret Rotation Strategy**

```javascript
// config/secret-rotator.js
const cron = require('node-cron');
const logger = require('./logger');

class SecretRotator {
  constructor(secretsManager) {
    this.secretsManager = secretsManager;
  }

  // Rotate secrets every 30 days
  scheduleRotation() {
    cron.schedule('0 0 * * *', async () => {
      const today = new Date();
      const rotationDay = process.env.SECRET_ROTATION_DAY || 1;

      if (today.getDate() === rotationDay) {
        await this.rotateAllSecrets();
      }
    });
  }

  async rotateAllSecrets() {
    const secrets = ['ACCESS_TOKEN_SECRET', 'REFRESH_TOKEN_SECRET'];

    for (const secret of secrets) {
      try {
        const newValue = this.generateSecureSecret();
        await this.secretsManager.updateSecret(secret, newValue);

        logger.info(`Secret rotated: ${secret}`);
      } catch (error) {
        logger.error(`Failed to rotate ${secret}:`, error);
      }
    }
  }

  generateSecureSecret(length = 64) {
    const crypto = require('crypto');
    return crypto.randomBytes(length).toString('hex');
  }
}

module.exports = SecretRotator;
```

