 * retrieves them from AWS Secrets Manager at runtime.
 */

const express = require('express');
const helmet = require('helmet');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const app = express();
let secrets = null;
let secretsInitialized = false;

// Initialize and cache secrets
async function initializeSecrets() {
  if (secretsInitialized) {
    return secrets;
  }

  const client = new SecretsManagerClient({ 
    region: process.env.AWS_REGION || 'us-east-1' 
  });

  try {
    const secretName = `${process.env.NODE_ENV || 'development'}/app-secrets`;
    console.log(`[INFO] Loading secrets from: ${secretName}`);

    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await client.send(command);

    // Parse the secret JSON
    secrets = JSON.parse(response.SecretString);
    secretsInitialized = true;

    console.log('[INFO] Secrets loaded successfully');
    console.log('[INFO] Available secret keys:', Object.keys(secrets).join(', '));

    return secrets;
  } catch (error) {
    console.error('[ERROR] Failed to load secrets from AWS Secrets Manager:', error.message);
    console.error('[ERROR] This could be due to:');
    console.error('  - Invalid AWS credentials');
    console.error('  - IAM role lacks SecretsManager:GetSecretValue permission');
    console.error('  - Secret does not exist');
    console.error('  - Wrong AWS_REGION');
    process.exit(1);
  }
}

// Middleware to ensure secrets are loaded
const ensureSecretsLoaded = (req, res, next) => {
  if (!secretsInitialized) {
    return res.status(503).json({ 
      error: 'Service unavailable - secrets not initialized' 
    });
  }
  next();
};

// Security middleware
app.use(helmet());
app.use(express.json({ limit: '10kb' }));

// Health check (doesn't require secrets)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    secretsReady: secretsInitialized
  });
});

// Protected endpoint requiring secrets
app.get('/api/v1/users', ensureSecretsLoaded, (req, res) => {
  // Example: Using DATABASE_URL secret
  const dbUrl = secrets.DATABASE_URL;

  // NEVER log the actual secret value
  console.log('[INFO] Accessing users endpoint');
  console.log('[INFO] Using database host:', extractHostFromUrl(dbUrl));

  // Return data (in real app, would connect to DB using dbUrl)
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Helper to safely extract host from connection string without exposing password
function extractHostFromUrl(url) {
  try {
    const urlObj = new URL(url);
    return urlObj.hostname;
  } catch (e) {
    return '[invalid-url]';
  }
}

// Error handler
app.use((err, req, res, next) => {
  console.error('[ERROR]', err.message);

  // Never expose error details containing secrets
  const isDevelopment = process.env.NODE_ENV === 'development';
  res.status(500).json({
    error: isDevelopment ? err.message : 'Internal server error'
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('[INFO] SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('[INFO] Server closed');
    process.exit(0);
  });
});

// Start server
const PORT = process.env.PORT || 3000;
let server;

async function start() {
  try {
    // Load secrets before starting server
    await initializeSecrets();

    server = app.listen(PORT, () => {
      console.log(`[INFO] Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
    });
  } catch (error) {
    console.error('[FATAL] Failed to start server:', error);
    process.exit(1);
  }
}

start();

module.exports = app;
