// config/secrets.js
const AWS = require('aws-sdk');
const path = require('path');

class SecretsManager {
  constructor() {
    this.secretsCache = null;
    this.cacheTTL = 3600000; // 1 hour
    this.lastFetched = null;

    // Only use .env as fallback in development
    if (process.env.NODE_ENV === 'development') {
      require('dotenv').config({
        path: path.resolve(__dirname, '../.env.local')
      });
      console.warn('⚠️ WARNING: Using .env file in development only!');
    }
  }

  async getSecrets() {
    // Check cache validity
    if (this.secretsCache && Date.now() - this.lastFetched < this.cacheTTL) {
      return this.secretsCache;
    }

    if (process.env.NODE_ENV === 'production') {
      return this.getFromAWSSecretsManager();
    } else if (process.env.NODE_ENV === 'staging') {
      return this.getFromVault();
    } else {
      return this.getFromLocalEnv();
    }
  }

  async getFromAWSSecretsManager() {
    const client = new AWS.SecretsManager({ region: process.env.AWS_REGION });

    try {
      const data = await client.getSecretValue({
        SecretId: process.env.SECRET_ID || 'prod/app-secrets'
      }).promise();

      this.secretsCache = JSON.parse(data.SecretString);
      this.lastFetched = Date.now();
      return this.secretsCache;
    } catch (error) {
      console.error('Failed to retrieve secrets from AWS:', error);
      throw new Error('Unable to load secrets');
    }
  }

  async getFromVault() {
    const vault = require('node-vault')({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN
    });

    try {
      const result = await vault.read(process.env.VAULT_PATH || 'secret/data/app');
      this.secretsCache = result.data.data;
      this.lastFetched = Date.now();
      return this.secretsCache;
    } catch (error) {
      console.error('Failed to retrieve secrets from Vault:', error);
      throw new Error('Unable to load secrets');
    }
  }

  getFromLocalEnv() {
    if (!process.env.DATABASE_URL) {
      throw new Error('DATABASE_URL not configured in environment');
    }

    return {
      DATABASE_URL: process.env.DATABASE_URL,
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
      LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
      JWT_SECRET: process.env.JWT_SECRET,
    };
  }

  // Get individual secret with validation
  async getSecret(secretKey, defaultValue = null) {
    const secrets = await this.getSecrets();

    if (!secrets[secretKey] && defaultValue === null) {
      throw new Error(`Secret '${secretKey}' not found`);
    }

    return secrets[secretKey] || defaultValue;
  }
}

module.exports = new SecretsManager();
```

