## 🔒 Secure app.js Template

See `app-secure.js` for a fully refactored version with all security recommendations implemented.

/**
 * Secure Express Application
 * This version implements security best practices and mitigates vulnerabilities
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');
const xss = require('xss');
const winston = require('winston');

const app = express();

// ========== ENVIRONMENT VARIABLES ==========
// Verify required environment variables
const requiredEnvVars = ['JWT_SECRET', 'NODE_ENV'];
requiredEnvVars.forEach(varName => {
  if (!process.env[varName]) {
    console.error(`Missing required environment variable: ${varName}`);
    process.exit(1);
  }
});

// ========== LOGGING SETUP ==========
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ========== SECURITY MIDDLEWARE ==========

// 1. Security Headers
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  },
}));

// 2. Additional Security Headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});

// 3. CORS Configuration
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};

app.use(cors(corsOptions));

// 4. Request Size Limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter limit for auth attempts
  skipSuccessfulRequests: true,
});

app.use(limiter);

// 6. Request Logging Middleware
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
      userId: req.user?.id || 'anonymous',
    });
  });

  next();
});

// ========== AUTHENTICATION MIDDLEWARE ==========
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({
      event: 'missing_token',
      path: req.path,
      ip: req.ip,
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {
    if (err) {
      logger.warn({
        event: 'invalid_token',
        error: err.message,
        path: req.path,
        ip: req.ip,
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = decoded;
    next();
  });
};

// ========== VALIDATION MIDDLEWARE ==========
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn({
      event: 'validation_error',
      errors: errors.array(),
      path: req.path,
      ip: req.ip,
    });
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array(),
    });
  }
  next();
};

// ========== SANITIZATION UTILITY ==========
const sanitizeOutput = (data) => {
  if (typeof data === 'string') {
    return xss(data);
  }
  if (Array.isArray(data)) {
    return data.map(sanitizeOutput);
  }
  if (typeof data === 'object' && data !== null) {
    return Object.keys(data).reduce((acc, key) => {
      acc[key] = sanitizeOutput(data[key]);
      return acc;
    }, {});
  }
  return data;
};

// ========== MOCK DATA (In production, this would come from a database) ==========
const users = [
  { id: 1, name: 'Alice', role: 'admin' },
  { id: 2, name: 'Bob', role: 'user' },
];

// ========== ROUTES ==========

// Health Check Endpoint
app.get('/health', (req, res) => {
  try {
    const health = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV,
    };
    res.status(200).json(health);
  } catch (error) {
    logger.error({
      event: 'health_check_error',
      error: error.message,
    });
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Users Endpoint - Protected with Authentication & Validation
app.get('/users',
  authenticateToken,
  [query('limit').optional().isInt({ min: 1, max: 100 })],
  [query('offset').optional().isInt({ min: 0 })],
  handleValidationErrors,
  (req, res) => {
    try {
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const offset = Math.max(parseInt(req.query.offset) || 0, 0);

      logger.info({
        event: 'users_list_accessed',
        userId: req.user.id,
        limit,
        offset,
      });

      // Return sanitized user data without PII
      const sanitizedUsers = users
        .slice(offset, offset + limit)
        .map(user => sanitizeOutput({ id: user.id, name: user.name }));

      res.status(200).json({
        data: sanitizedUsers,
        total: users.length,
        limit,
        offset,
      });
    } catch (error) {
      logger.error({
        event: 'users_endpoint_error',
        error: error.message,
        userId: req.user?.id,
      });
      res.status(500).json({
        error: process.env.NODE_ENV === 'production'
          ? 'An error occurred'
          : error.message,
      });
    }
  }
);

// Login Endpoint (for testing - NOT for production without additional security)
app.post('/login', authLimiter, express.json(), (req, res) => {
  try {
    // This is a simplified example. In production, use proper authentication.
    const { username } = req.body;

    if (!username || typeof username !== 'string' || username.length > 100) {
      logger.warn({
        event: 'invalid_login_attempt',
        ip: req.ip,
      });
      return res.status(400).json({ error: 'Invalid username' });
    }

    // In production: verify credentials against database
    const user = { id: 1, username };
    const token = jwt.sign(user, process.env.JWT_SECRET, { expiresIn: '1h' });

    logger.info({
      event: 'successful_login',
      userId: user.id,
      ip: req.ip,
    });

    res.json({ token });
  } catch (error) {
    logger.error({
      event: 'login_error',
      error: error.message,
    });
    res.status(500).json({
      error: process.env.NODE_ENV === 'production'
        ? 'An error occurred'
        : error.message,
    });
  }
});

// ========== ERROR HANDLING ==========

// 404 Handler
app.use((req, res) => {
  logger.warn({
    event: '404_not_found',
    path: req.path,
    method: req.method,
    ip: req.ip,
  });
  res.status(404).json({ error: 'Not Found' });
});

// Global Error Handler
app.use((err, req, res, next) => {
  logger.error({
    event: 'unhandled_error',
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Return generic error to client
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'An error occurred'
      : err.message,
  });
});

// ========== SERVER STARTUP ==========
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  logger.info(`Server running on ${HOST}:${PORT} in ${process.env.NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;

