// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    this.cache = {};
    this.ttl = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    const now = Date.now();

    // Check cache
    if (this.cache[secretName] && now - this.cache[secretName].timestamp < this.ttl) {
      return this.cache[secretName].value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secretValue = response.SecretString 
        ? JSON.parse(response.SecretString) 
        : response.SecretBinary;

      // Cache the secret
      this.cache[secretName] = {
        value: secretValue,
        timestamp: now
      };

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
  }

  async getSecretValue(secretName, key) {
    const secret = await this.getSecret(secretName);
    return key ? secret[key] : secret;
  }
}

module.exports = new SecretsManager();

