/**
 * Secrets Management Module
 * Handles retrieval of secrets from AWS Secrets Manager
 * 
 * SECURITY: This module is for PRODUCTION use with AWS Secrets Manager
 * For development, use .env.example with dummy values
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor(options = {}) {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });

    // In-memory cache with TTL
    this.cache = {};
    this.ttl = options.cacheTTL || 3600000; // 1 hour default

    // Track cache hits/misses for monitoring
    this.stats = {
      hits: 0,
      misses: 0,
      errors: 0,
    };
  }

  /**
   * Get complete secret object
   * @param {string} secretName - Name or ARN of the secret
   * @returns {Promise<Object>} - Parsed secret value
   */
  async getSecret(secretName) {
    const now = Date.now();

    // Check cache validity
    if (this.cache[secretName]) {
      const { value, timestamp } = this.cache[secretName];
      if (now - timestamp < this.ttl) {
        this.stats.hits++;
        return value;
      }
    }

    // Cache miss - fetch from Secrets Manager
    this.stats.misses++;

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      // Handle different secret types
      let secretValue;
      if (response.SecretString) {
        try {
          secretValue = JSON.parse(response.SecretString);
        } catch (e) {
          // If not JSON, return as string
          secretValue = response.SecretString;
        }
      } else if (response.SecretBinary) {
        secretValue = Buffer.from(response.SecretBinary).toString('utf8');
      }

      // Cache the secret
      this.cache[secretName] = {
        value: secretValue,
        timestamp: now,
      };

      return secretValue;
    } catch (error) {
      this.stats.errors++;

      // Log error without exposing secret details
      console.error(`SecretManager: Failed to retrieve secret: ${secretName}`, {
        errorCode: error.code,
        errorMessage: error.message.substring(0, 100),
      });

      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Get specific value from secret object
   * @param {string} secretName - Name of the secret
   * @param {string} key - Key within the secret object
   * @returns {Promise<any>} - Secret value
   */
  async getSecretValue(secretName, key) {
    const secret = await this.getSecret(secretName);

    if (typeof secret !== 'object' || secret === null) {
      throw new Error(`Secret ${secretName} is not an object`);
    }

    if (!(key in secret)) {
      throw new Error(`Key '${key}' not found in secret '${secretName}'`);
    }

    return secret[key];
  }

  /**
   * Clear cache for a specific secret or all secrets
   * @param {string} secretName - Optional secret name to clear
   */
  clearCache(secretName) {
    if (secretName) {
      delete this.cache[secretName];
    } else {
      this.cache = {};
    }
  }

  /**
   * Get cache statistics
   * @returns {Object} - Cache hit/miss statistics
   */
  getStats() {
    return {
      ...this.stats,
      hitRate: this.stats.hits / (this.stats.hits + this.stats.misses) || 0,
      cachedSecrets: Object.keys(this.cache).length,
    };
  }

  /**
   * Validate secret existence
   * @param {string} secretName - Secret to validate
   * @returns {Promise<boolean>}
   */
  async validateSecret(secretName) {
    try {
      await this.getSecret(secretName);
      return true;
    } catch (error) {
      return false;
    }
  }
}

module.exports = new SecretsManager();
