// Role-based authorization middleware
const authorize = (requiredRole) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'User not authenticated' });
    }

    if (req.user.role !== requiredRole && req.user.role !== 'admin') {
      return res.status(403).json({
        error: 'Insufficient permissions',
        code: 'INSUFFICIENT_ROLE',
      });
    }

    next();
  };
};

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

const validatePagination = [
  query('page')
    .optional()
    .isInt({ min: 1 })
    .toInt()
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be between 1 and 100'),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array(),
      });
    }
    next();
  },
];

// ============================================================================
// ROUTES
// ============================================================================

// Health check - No auth required, but cached
app.get('/health', (req, res) => {
  res.set('Cache-Control', 'public, max-age=60');
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

// Get users - Requires authentication and admin role
app.get('/users', 
  authLimiter,
  authenticateToken, 
  authorize('admin'),
  validatePagination,
  (req, res) => {
    const page = req.query.page || 1;
    const limit = req.query.limit || 10;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    // Pagination
    const startIndex = (page - 1) * limit;
    const paginatedUsers = users.slice(startIndex, startIndex + limit);

    res.set('Cache-Control', 'private, no-cache, no-store, must-revalidate');
    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
      },
    });
  }
);

// Mock authentication endpoint (for demonstration)
app.post('/auth/login', authLimiter, express.json(), (req, res) => {
  // In production: validate against database with bcrypt
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({
      error: 'Username and password are required',
    });
  }

  // Mock user (in production, query database)
  if (username === 'admin' && password === 'password') {
    const token = jwt.sign(
      { id: 1, username: 'admin', role: 'admin' },
      process.env.JWT_SECRET || 'your-secret-key',
      { expiresIn: '1h' }
    );

    res.set('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
    return res.json({ token });
  }

  // Generic error message (don't reveal if user exists)
  return res.status(401).json({
    error: 'Invalid credentials',
  });
});

// ============================================================================
// ERROR HANDLING MIDDLEWARE - Must be last
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
  });
});

// Global error handler
app.use((err, req, res, next) => {
  const isProduction = process.env.NODE_ENV === 'production';

  // Log error for debugging (server-side only)
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: isProduction ? undefined : err.stack,
    path: req.path,
    method: req.method,
    userId: req.user?.id || 'anonymous',
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Don't expose stack traces to clients in production
  const response = {
    error: isProduction ? 'Internal Server Error' : err.message,
    ...(isProduction ? {} : { stack: err.stack }),
  };

  res.status(statusCode).json(response);
});

// ============================================================================
// SERVER START
// ============================================================================

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

