## Common Vulnerability Fixes

### SQL Injection Prevention
```javascript
// VULNERABLE ❌
db.query(`SELECT * FROM users WHERE id = ${req.params.id}`);

// SECURE ✓
db.query('SELECT * FROM users WHERE id = ?', [req.params.id]);
```

### NoSQL Injection Prevention
```javascript
// VULNERABLE ❌
db.users.find({ username: req.body.username });

// SECURE ✓
db.users.findOne({ username: { $eq: req.body.username } });
```

### XSS Prevention
```javascript
// VULNERABLE ❌
res.send(`<div>${req.query.search}</div>`);

// SECURE ✓
const escaped = require('html-entities').encode(req.query.search);
res.send(`<div>${escaped}</div>`);
```

### CSRF Prevention
```javascript
const csrf = require('csurf');
const cookieParser = require('cookie-parser');

app.use(cookieParser());
app.use(csrf({ cookie: false }));

app.post('/form', (req, res) => {
  // Form handles CSRF token automatically
});
```

### Insecure Deserialization Prevention
```javascript
// VULNERABLE ❌
eval(req.body.data);
const obj = JSON.parse(req.body.data);

// SECURE ✓
const obj = JSON.parse(req.body.data);
// Always validate the parsed object
```

### Path Traversal Prevention
```javascript
const path = require('path');

// VULNERABLE ❌
app.get('/files/:filename', (req, res) => {
  res.download(`./uploads/${req.params.filename}`);
});

// SECURE ✓
app.get('/files/:filename', (req, res) => {
  const safeFilename = path.basename(req.params.filename);
  const fullPath = path.join(__dirname, 'uploads', safeFilename);

  // Ensure the resolved path is within uploads directory
  if (!fullPath.startsWith(path.join(__dirname, 'uploads'))) {
    return res.status(403).json({ error: 'Access denied' });
  }

  res.download(fullPath);
});
```

