- No encryption for data in transit
- No HTTPS/TLS enforcement
- Sensitive data (timestamps) unnecessarily exposed in health endpoint

Risk:
- Privacy violation
- Email harvesting for spam/phishing
- Data interception if not using HTTPS
- Information disclosure

Recommendation: Encrypt sensitive data and enforce HTTPS

✅ SECURE CODE EXAMPLE:
```javascript
const express = require('express');
const helmet = require('helmet');
const crypto = require('crypto');
const app = express();

// Force HTTPS in production
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(`https://${req.header('host')}${req.url}`);
  }
  next();
});

// Encryption utilities
function encryptEmail(email) {
  const cipher = crypto.createCipher(
    'aes-256-cbc',
    process.env.ENCRYPTION_KEY
  );
  let encrypted = cipher.update(email, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  return encrypted;
}

function maskEmail(email) {
  const [localPart, domain] = email.split('@');
  const masked = localPart.substring(0, 2) + '*'.repeat(localPart.length - 2);
  return `${masked}@${domain}`;
}

// Protected and masked response
app.get('/users', authenticateToken, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Mask emails in response
  const maskedUsers = users.map(user => ({
    id: user.id,
    name: user.name,
    email: maskEmail(user.email),
  }));

  res.json(maskedUsers);
});

// Minimal health endpoint
