      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        role: 'user',
        department: 'Sales'
      },
    ];

    // Filter sensitive data based on user role
    if (req.user.role !== 'admin') {
      // Non-admin users don't see email addresses or department
      users = users.map(({ email, department, ...user }) => user);
    }

    // Pagination
    const paginatedUsers = users.slice(offset, offset + limit);

