);

/**
 * Get specific user endpoint
 * Protected endpoint - users can only see their own data unless admin
 */
app.get('/api/users/:id',
  authenticateToken,
  (req, res) => {
    const userId = parseInt(req.params.id, 10);

    if (isNaN(userId)) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

