---

## Vulnerability Details & Fixes

### 1. MISSING AUTHENTICATION (CRITICAL)

**Problem:**
```javascript
// VULNERABLE - Anyone can access user data
app.get('/users', (req, res) => {
  res.json(userData);
});
```

**Solution:**
```javascript
// SECURE - Requires valid JWT token
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

app.get('/users', authenticateToken, (req, res) => {
  res.json(userData);
});
```

**Key Points:**
- Use JWT (JSON Web Tokens) or OAuth2
- Tokens should expire (set expiresIn)
- Store SECRET_KEY securely in environment variables
- Never trust client-provided tokens without verification

---

### 2. MISSING AUTHORIZATION (CRITICAL)

**Problem:**
```javascript
// All authenticated users see all data
app.get('/users/:id', authenticateToken, (req, res) => {
  res.json(getUserData(req.params.id));
});
```

**Solution:**
```javascript
// Check if user has permission
app.get('/users/:id', authenticateToken, (req, res) => {
  const requestedId = parseInt(req.params.id);

  // Users can only see their own data, admins see all
  if (req.user.id !== requestedId && req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  res.json(getUserData(requestedId));
});
```

**Key Points:**
- Implement Role-Based Access Control (RBAC)
- Always verify user ID against authenticated user
- Use middleware to check permissions consistently

---

### 3. SENSITIVE DATA EXPOSURE (HIGH)

**Problem:**
```javascript
// VULNERABLE - Exposes PII to all users
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' }, // Email exposed!
    { id: 2, name: 'Bob', email: 'bob@example.com' }
  ]);
});
```

**Solution:**
```javascript
// SECURE - Filter data based on user role
app.get('/users', authenticateToken, (req, res) => {
  let users = getUserList();

  // Non-admins don't see sensitive fields
  if (req.user.role !== 'admin') {
    users = users.map(({ email, phone, ssn, ...user }) => user);
  }

  res.json(users);
});
```

**Key Points:**
- Never expose PII without authorization
- Filter data at the API level, not just the UI
- Implement proper access controls for sensitive data
- Consider data minimization principles

---

### 4. MISSING SECURITY HEADERS (HIGH)

**Problem:**
```javascript
// VULNERABLE - No security headers
const app = express();
app.listen(3000);
```

**Solution:**
```javascript
const helmet = require('helmet');
const cors = require('cors');

// Add security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Configure CORS properly
app.use(cors({
  origin: ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST']
}));
```

**Security Headers Explained:**

| Header | Purpose |
|--------|---------|
| `Content-Security-Policy` | Prevents XSS by controlling resource loading |
| `X-Frame-Options` | Prevents clickjacking |
| `X-Content-Type-Options` | Prevents MIME sniffing |
| `Strict-Transport-Security` | Forces HTTPS |
| `X-XSS-Protection` | Additional XSS protection (legacy) |

---

### 5. MISSING INPUT VALIDATION (HIGH)

**Problem:**
```javascript
// VULNERABLE - No validation
app.get('/users/:id', (req, res) => {
  const id = req.params.id; // Could be anything!
  res.json(getUserById(id));
});
```

**Solution:**
```javascript
const { param, query, validationResult } = require('express-validator');

app.get('/users/:id',
  param('id').isInt().toInt(),
  query('include').optional().isIn(['profile', 'settings']),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    res.json(getUserById(req.params.id));
  }
);
```

**Validation Best Practices:**
- Validate all inputs (params, query, body)
- Use whitelisting, not blacklisting
- Sanitize outputs
- Set limits on input size and length

---

### 6. SQL INJECTION / NOSQL INJECTION

**Problem:**
```javascript
// VULNERABLE - Direct query with user input
app.get('/users/:id', (req, res) => {
  const query = `SELECT * FROM users WHERE id = ${req.params.id}`;
  db.query(query, (err, result) => {
    res.json(result);
  });
});

// VULNERABLE - NoSQL injection
app.get('/users/:id', (req, res) => {
  User.findById(req.params.id, (err, user) => {
    res.json(user);
  });
});
```

**Solution:**
```javascript
// SECURE - Use parameterized queries
app.get('/users/:id',
  param('id').isInt().toInt(),
  (req, res) => {
    const id = req.params.id;
    // Use parameterized query
    db.query('SELECT * FROM users WHERE id = ?', [id], (err, result) => {
      if (err) return res.status(500).json({ error: 'Database error' });
      res.json(result);
    });
  }
);

// SECURE - Validate input type
app.get('/users/:id',
  param('id').isInt().toInt(),
  (req, res) => {
    User.findById(parseInt(req.params.id), (err, user) => {
      if (err) return res.status(500).json({ error: 'Error' });
      res.json(user);
    });
  }
);
```

**SQL Injection Prevention:**
- Always use parameterized queries
- Validate input types and formats
- Use ORM frameworks (Sequelize, TypeORM)
- Apply principle of least privilege to DB user

---

### 7. RATE LIMITING (MEDIUM)

**Problem:**
```javascript
// VULNERABLE - No rate limiting
app.post('/login', (req, res) => {
  // Attacker can brute force passwords
});
```

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests'
});

// Strict limiter for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 attempts
  skipSuccessfulRequests: true
});

app.use('/api/', limiter);
app.post('/login', authLimiter, (req, res) => {
  // Brute force attacks now limited
});
```

---

### 8. ERROR HANDLING & INFORMATION DISCLOSURE

**Problem:**
```javascript
// VULNERABLE - Leaks error details
app.use((err, req, res, next) => {
  res.status(500).json({
    error: err.message,
    stack: err.stack // Exposes internals!
  });
});
```

**Solution:**
```javascript
// SECURE - Sanitized error response
app.use((err, req, res, next) => {
  // Log full error server-side
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path
  });

  // Send generic error to client
  res.status(500).json({
    error: 'Internal server error'
    // No stack trace or detailed info
  });
});
```

---

### 9. LOGGING & MONITORING

**Problem:**
```javascript
// VULNERABLE - No security logging
app.get('/users/:id', (req, res) => {
  res.json(getUserById(req.params.id));
});
```

**Solution:**
```javascript
const winston = require('winston');
const morgan = require('morgan');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'audit.log' })
  ]
});

// HTTP request logging
app.use(morgan('combined', { stream: { write: msg => logger.info(msg) } }));

// Security event logging
app.get('/users/:id', (req, res) => {
  logger.info({
    type: 'USER_ACCESS',
    userId: req.user?.id,
    accessedId: req.params.id,
    ip: req.ip,
    timestamp: new Date()
  });

  res.json(getUserById(req.params.id));
});
```

---

### 10. HTTPS/TLS ENFORCEMENT

**Problem:**
```javascript
// VULNERABLE - HTTP only, credentials sent in plaintext
app.listen(3000);
```

**Solution:**
```javascript
// SECURE - Enforce HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(301, `https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// Use helmet for HSTS header
app.use(helmet.hsts({
  maxAge: 31536000,
  includeSubDomains: true,
  preload: true
}));
```

