#!/usr/bin/env node

/**
 * SECURITY AUDIT REPORT GENERATOR
 * Analyzes app.js and generates detailed security report
 */

const fs = require('fs');
const path = require('path');

class SecurityAudit {
  constructor(filePath) {
    this.filePath = filePath;
    this.findings = [];
    this.score = 100;
  }

  readFile() {
    try {
      return fs.readFileSync(this.filePath, 'utf8');
    } catch (err) {
      console.error('Error reading file:', err.message);
      process.exit(1);
    }
  }

  analyzeAuthentication(content) {
    const hasJWT = content.includes('jsonwebtoken') || content.includes('jwt.verify');
    const hasAuthMiddleware = content.includes('authenticateToken') || content.includes('authenticate');

    if (!hasJWT && !hasAuthMiddleware) {
      this.findings.push({
        severity: 'CRITICAL',
        category: 'Authentication',
        issue: 'No authentication implemented',
        description: 'The application does not implement any authentication mechanism',
        recommendation: 'Implement JWT-based authentication or OAuth2',
        cve: 'CWE-287: Improper Authentication',
        score: -30
      });
      this.score -= 30;
    }
  }

  analyzeAuthorization(content) {
    const hasRBAC = content.includes('role') && content.includes('authorize');
    const hasAccessControl = content.includes('req.user.id');

    if (!hasRBAC && !hasAccessControl) {
      this.findings.push({
        severity: 'CRITICAL',
        category: 'Authorization',
        issue: 'No authorization checks',
        description: 'The application lacks access control checks',
        recommendation: 'Implement role-based access control (RBAC)',
        cve: 'CWE-639: Authorization Bypass Through User-Controlled Key',
        score: -25
      });
      this.score -= 25;
    }
  }

  analyzeInputValidation(content) {
    const hasValidation = content.includes('validationResult') || 
                          content.includes('express-validator') ||
                          content.includes('validate');

    if (!hasValidation) {
      this.findings.push({
        severity: 'HIGH',
        category: 'Input Validation',
        issue: 'No input validation',
        description: 'User inputs are not validated or sanitized',
        recommendation: 'Use express-validator or similar for input validation',
        cve: 'CWE-20: Improper Input Validation',
        score: -20
      });
      this.score -= 20;
    }
  }

  analyzeSecurityHeaders(content) {
    const hasHelmet = content.includes('helmet');
    const hasCORS = content.includes('cors');

    let headerIssues = [];

    if (!hasHelmet) {
      headerIssues.push('Missing helmet (security headers)');
    }
    if (!hasCORS) {
      headerIssues.push('Missing CORS configuration');
    }

    if (headerIssues.length > 0) {
      this.findings.push({
        severity: 'HIGH',
        category: 'Security Headers',
        issue: 'Missing security headers',
        description: headerIssues.join(', '),
        recommendation: 'Use helmet middleware and configure CORS properly',
        cve: 'CWE-693: Protection Mechanism Failure',
        score: -15
      });
      this.score -= 15;
    }
  }

  analyzeDataExposure(content) {
    if (content.includes('email') && content.includes('res.json')) {
      this.findings.push({
        severity: 'CRITICAL',
        category: 'Sensitive Data Exposure',
        issue: 'PII exposed in responses',
        description: 'Email addresses and other PII are exposed without authorization checks',
        recommendation: 'Filter sensitive data based on user role',
        cve: 'CWE-200: Exposure of Sensitive Information',
        score: -20
      });
      this.score -= 20;
    }
  }

  analyzeRateLimiting(content) {
    const hasRateLimit = content.includes('rateLimit') || content.includes('rate-limit');

    if (!hasRateLimit) {
      this.findings.push({
        severity: 'HIGH',
        category: 'Rate Limiting',
        issue: 'No rate limiting',
        description: 'Endpoints are not protected from brute force or DoS attacks',
        recommendation: 'Implement express-rate-limit middleware',
        cve: 'CWE-770: Allocation of Resources Without Limits',
        score: -15
      });
      this.score -= 15;
    }
  }

  analyzeLogging(content) {
    const hasLogging = content.includes('winston') || 
                       content.includes('morgan') || 
                       content.includes('logger');

    if (!hasLogging) {
      this.findings.push({
        severity: 'MEDIUM',
        category: 'Logging & Monitoring',
        issue: 'No logging/monitoring',
        description: 'Security events are not logged, making intrusions undetectable',
        recommendation: 'Implement winston or similar logging framework',
        cve: 'CWE-778: Insufficient Logging',
        score: -10
      });
      this.score -= 10;
    }
  }

  analyzeErrorHandling(content) {
    const hasErrorHandler = content.includes('app.use((err,') || 
                            content.includes('catch') ||
                            content.includes('try {');

    if (!hasErrorHandler) {
      this.findings.push({
        severity: 'MEDIUM',
        category: 'Error Handling',
        issue: 'No centralized error handling',
        description: 'Error messages may leak sensitive information',
        recommendation: 'Implement global error handler middleware',
        cve: 'CWE-209: Information Exposure Through an Error Message',
        score: -10
      });
      this.score -= 10;
    }
  }

  analyzeHTTPS(content) {
    const hasHTTPS = content.includes('https') || 
                     content.includes('x-forwarded-proto') ||
                     content.includes('hsts');

    if (!hasHTTPS) {
      this.findings.push({
        severity: 'HIGH',
        category: 'Transport Security',
        issue: 'No HTTPS enforcement',
        description: 'Application does not enforce HTTPS, credentials can be intercepted',
        recommendation: 'Enforce HTTPS in production and set HSTS headers',
        cve: 'CWE-295: Improper Certificate Validation',
        score: -15
      });
      this.score -= 15;
    }
  }

  run() {
    console.log('🔒 Security Audit Report\n');
    console.log('=' .repeat(80));

    const content = this.readFile();

    this.analyzeAuthentication(content);
    this.analyzeAuthorization(content);
    this.analyzeInputValidation(content);
    this.analyzeSecurityHeaders(content);
    this.analyzeDataExposure(content);
    this.analyzeRateLimiting(content);
    this.analyzeLogging(content);
    this.analyzeErrorHandling(content);
    this.analyzeHTTPS(content);

    // Sort findings by severity
    const severityOrder = { CRITICAL: 0, HIGH: 1, MEDIUM: 2, LOW: 3 };
    this.findings.sort((a, b) => severityOrder[a.severity] - severityOrder[b.severity]);

    // Print findings
    this.findings.forEach((finding, index) => {
      const icon = this.getSeverityIcon(finding.severity);
      console.log(`\n${index + 1}. ${icon} ${finding.severity}: ${finding.issue}`);
      console.log(`   Category: ${finding.category}`);
      console.log(`   Description: ${finding.description}`);
      console.log(`   Recommendation: ${finding.recommendation}`);
      console.log(`   CWE: ${finding.cve}`);
    });

    // Print summary
    console.log('\n' + '='.repeat(80));
    console.log(`\n📊 Security Score: ${Math.max(0, this.score)}/100`);
    console.log(`\n💡 Issues Found: ${this.findings.length}`);

    const critical = this.findings.filter(f => f.severity === 'CRITICAL').length;
    const high = this.findings.filter(f => f.severity === 'HIGH').length;
    const medium = this.findings.filter(f => f.severity === 'MEDIUM').length;
    const low = this.findings.filter(f => f.severity === 'LOW').length;

    console.log(`   🔴 Critical: ${critical}`);
    console.log(`   🟠 High: ${high}`);
    console.log(`   🟡 Medium: ${medium}`);
    console.log(`   🟢 Low: ${low}`);

    // Risk assessment
    console.log(`\n⚠️  Risk Assessment:`);
    if (this.score < 30) {
      console.log('   Status: CRITICAL - DO NOT DEPLOY TO PRODUCTION');
    } else if (this.score < 50) {
      console.log('   Status: HIGH RISK - Significant vulnerabilities present');
    } else if (this.score < 70) {
      console.log('   Status: MEDIUM RISK - Important fixes needed');
    } else if (this.score < 85) {
      console.log('   Status: LOW RISK - Minor improvements recommended');
    } else {
      console.log('   Status: GOOD - Keep maintaining security');
    }

    console.log('\n' + '='.repeat(80));
    console.log('\nFor detailed recommendations, see SECURITY_IMPLEMENTATION_GUIDE.md\n');
  }

  getSeverityIcon(severity) {
    const icons = {
      CRITICAL: '🔴',
      HIGH: '🟠',
      MEDIUM: '🟡',
      LOW: '🟢'
    };
    return icons[severity] || '❓';
  }
}

// Run audit if executed directly
if (require.main === module) {
  const filePath = process.argv[2] || './app.js';
  const audit = new SecurityAudit(filePath);
  audit.run();
}

module.exports = SecurityAudit;

