// Production-ready Express application with comprehensive security measures
// Implements all OWASP Top 10 mitigations

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, body, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');
require('dotenv').config();

const app = express();

// ============================================================
// 1. SECURITY HEADERS (Helmet middleware)
// Mitigates: XSS, Clickjacking, MIME sniffing, etc.
// ============================================================
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
    connectSrc: ["'self'"],
    frameSrc: ["'none'"],
    objectSrc: ["'none'"],
  },
}));

// ============================================================
// 2. CORS CONFIGURATION (Controlled cross-origin requests)
// Mitigates: Broken Access Control (A01:2021)
// ============================================================
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',') 
    : ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  exposedHeaders: ['X-Total-Count'],
  maxAge: 3600
};
app.use(cors(corsOptions));

// ============================================================
// 3. BODY PARSER WITH SIZE LIMITS
// Mitigates: Denial of Service attacks
// ============================================================
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================================
// 4. LOGGING AND MONITORING
// Mitigates: A09:2021 – Logging and Monitoring Failures
// ============================================================
const accessLogStream = fs.createWriteStream(
  path.join(__dirname, 'logs', 'access.log'),
  { flags: 'a' }
);

// Create logs directory if it doesn't exist
if (!fs.existsSync(path.join(__dirname, 'logs'))) {
  fs.mkdirSync(path.join(__dirname, 'logs'));
}

app.use(morgan('combined', { stream: accessLogStream }));

// Security event logger
const securityLogger = (req, res, next) => {
  res.on('finish', () => {
    if (res.statusCode >= 400) {
      const logEntry = `[SECURITY EVENT] ${new Date().toISOString()} | ${req.method} ${req.path} | Status: ${res.statusCode} | IP: ${req.ip} | User-Agent: ${req.get('user-agent')}`;
      console.error(logEntry);
      fs.appendFileSync(path.join(__dirname, 'logs', 'security.log'), logEntry + '\n');
    }
  });
  next();
};
app.use(securityLogger);

// ============================================================
// 5. RATE LIMITING
// Mitigates: A04:2021 – Insecure Design (DoS attacks)
// ============================================================
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => {
    // Don't rate limit health checks
    return req.path === '/health';
  }
});

const strictLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 5,
  skipSuccessfulRequests: true // Only count failed requests
});

app.use(globalLimiter);

// ============================================================
// 6. REQUEST ID MIDDLEWARE (For tracing)
// ============================================================
const crypto = require('crypto');
