### 2. **Missing Authentication & Authorization (OWASP A01:2021 - Broken Access Control)**

**Issue**: `/users` endpoint returns sensitive PII with no authentication

**Current Code**:
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Risk**:
- Anyone can access user data without authentication
- Email addresses exposed (privacy violation, GDPR/CCPA risk)
- No rate limiting (DoS vulnerability)
- No audit logging

**Recommendations**:

```javascript
const express = require('express');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
require('dotenv').config();

const app = express();

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later'
});

app.use(limiter);

// Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      console.error('Token verification failed:', err.message);
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
}

// Audit logging middleware
const auditLog = (action, details, status) => {
  console.log(JSON.stringify({
    timestamp: new Date().toISOString(),
    action,
    details,
    status,
    userId: details.userId || 'anonymous'
  }));
};

// Health check (public, no sensitive data)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected endpoint with proper response filtering
app.get('/users', authenticateToken, (req, res) => {
  // Check authorization: only allow admins or users viewing their own data
  if (!req.user.isAdmin && req.user.role !== 'admin') {
    auditLog('unauthorized_access', { userId: req.user.id }, 'denied');
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  auditLog('users_accessed', { userId: req.user.id }, 'success');

  // Filter sensitive data in response
  const sanitizedUsers = users.map(user => ({
    id: user.id,
    name: user.name,
    // Email only if same user or admin
    ...(req.user.isAdmin || req.user.id === user.id ? { email: user.email } : {})
  }));

  res.json(sanitizedUsers);
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Server running on port ${process.env.PORT || 3000}`);
});

module.exports = app;
```

