### 3. **Missing Input Validation (OWASP A03:2021 - Injection)**

**Issue**: No input validation, making the app vulnerable to injection attacks

**Current Vulnerabilities**:
- If query parameters were used without validation
- If POST/PUT endpoints were added, they'd be vulnerable
- No schema validation

**Recommendations**:

```javascript
const express = require('express');
const { body, query, validationResult } = require('express-validator');
const mongoSanitize = require('mongo-sanitize');
const xss = require('xss-clean');
const helmet = require('helmet');

const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(xss()); // Prevent XSS attacks
app.use(express.json({ limit: '10kb' })); // Limit payload size

// Input validation for search endpoint (example)
app.get('/users/search', [
  query('name')
    .trim()
    .optional()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be 1-100 characters'),
  query('email')
    .optional()
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email format')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Now process validated input
  const { name, email } = req.query;
  // ... search logic
});

// POST endpoint with strict validation
app.post('/users', [
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 100 }).withMessage('Name must be 2-100 characters')
    .matches(/^[a-zA-Z\s'-]+$/).withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .isEmail().withMessage('Valid email required')
    .normalizeEmail(),
  body('age')
    .optional()
    .isInt({ min: 0, max: 150 }).withMessage('Age must be 0-150')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Process validated data
  res.status(201).json({ success: true });
});

module.exports = app;
```

---

### 4. **Broken Object Level Authorization (OWASP A01:2021)**

**Issue**: If user ID endpoints were added, they'd lack proper authorization checks

**Example vulnerability**:
```javascript
// VULNERABLE - no authorization check
app.get('/users/:id', (req, res) => {
  const userId = req.params.id; // No validation
  // Returns any user's data to anyone
});
```

**Secure implementation**:
```javascript
app.get('/users/:id', authenticateToken, [
  param('id').isInt().toInt()
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const requestedId = req.params.id;

  // Authorization check: only allow users to see their own data or admins
  if (req.user.id !== requestedId && !req.user.isAdmin) {
    return res.status(403).json({ error: 'Unauthorized' });
  }

  const user = users.find(u => u.id === requestedId);
  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  res.json(user);
});
```

---

### 5. **Missing Security Headers (OWASP A05:2021 - Security Misconfiguration)**

**Issue**: No security headers configured

**Recommendation**:

```javascript
const helmet = require('helmet');

const app = express();

// Apply comprehensive security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "cross-origin" },
  dnsPrefetchControl: true,
  frameguard: { action: 'deny' },
  hidePoweredBy: true,
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  ieNoOpen: true,
  noSniff: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  xssFilter: true,
}));

// Additional CORS configuration
const cors = require('cors');
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  credentials: true,
  optionsSuccessStatus: 200
}));
```

---

### 6. **Unhandled Exceptions & Error Disclosure (OWASP A06:2021)**

**Issue**: No error handling; stack traces expose internal details

**Recommendation**:

```javascript
// Global error handler (at end of routes)
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't expose internal error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  const statusCode = err.statusCode || 500;
  const message = isDevelopment ? err.message : 'Internal Server Error';
  const error = isDevelopment ? err : {};

  res.status(statusCode).json({
    error: message,
    ...(isDevelopment && { stack: err.stack, details: error })
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

---

### 7. **No HTTPS Enforcement (OWASP A02:2021)**

**Recommendation**:

```javascript
const https = require('https');
const fs = require('fs');

const app = express();

// Redirect HTTP to HTTPS
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && req.header('x-forwarded-proto') !== 'https') {
    return res.redirect(`https://${req.header('host')}${req.url}`);
  }
  next();
});

// In production, use load balancer SSL or:
if (process.env.NODE_ENV === 'production') {
  const options = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH)
  };
  https.createServer(options, app).listen(443);
} else {
  app.listen(3000);
}
```

