/**
 * Secure Express Application
 * Implements OWASP Top 10 security controls
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { query, param, validationResult } = require('express-validator');
const mongoSanitize = require('mongo-sanitize');
require('dotenv').config();

const app = express();

// ============================================================================
// 1. SECURITY HEADERS & MIDDLEWARE
// ============================================================================

// Apply security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  dnsPrefetchControl: true,
  frameguard: { action: 'deny' },
  hidePoweredBy: true,
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  ieNoOpen: true,
  noSniff: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  xssFilter: true,
}));

// CORS configuration
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Body parser with size limit (prevent DoS)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Prevent NoSQL injection
app.use(mongoSanitize());

// ============================================================================
// 2. RATE LIMITING
// ============================================================================

// General rate limiter
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health checks
    return req.path === '/health';
  }
});

// Stricter limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Limit login attempts
  message: 'Too many login attempts, please try again later'
});

app.use(generalLimiter);

// ============================================================================
// 3. AUTHENTICATION & AUTHORIZATION
// ============================================================================

/**
 * Verify JWT token
 */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    auditLog('auth_failed_no_token', { ip: req.ip }, 'failed');
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      auditLog('auth_failed_invalid_token', { ip: req.ip }, 'failed');
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

/**
 * Check if user has admin role
 */
function requireAdmin(req, res, next) {
  if (!req.user.isAdmin && req.user.role !== 'admin') {
    auditLog('unauthorized_access', { userId: req.user.id, path: req.path }, 'denied');
    return res.status(403).json({ error: 'Admin privileges required' });
  }
  next();
}

// ============================================================================
// 4. LOGGING & AUDIT TRAIL
// ============================================================================

/**
 * Structured audit logging
 * In production, send to centralized logging (e.g., ELK, Splunk)
 */
const auditLog = (action, details = {}, status = 'info') => {
  const logEntry = {
    timestamp: new Date().toISOString(),
    action,
    status,
    environment: process.env.NODE_ENV || 'development',
    ...details
  };

  // Log to console (in production, use proper logging service)
  if (status === 'failed' || status === 'denied') {
    console.error('[AUDIT]', JSON.stringify(logEntry));
  } else {
    console.log('[AUDIT]', JSON.stringify(logEntry));
  }
};

// ============================================================================
// 5. REQUEST LOGGING MIDDLEWARE
// ============================================================================

app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    auditLog('http_request', {
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent')
    });
  });

  next();
});

// ============================================================================
// 6. ROUTES
// ============================================================================

/**
 * Health check endpoint (no auth required)
 * Exposes no sensitive information
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

/**
 * Login endpoint (for getting JWT token)
 * In production, verify against actual user database
 */
app.post('/auth/login', authLimiter, (req, res) => {
  // TODO: Implement proper authentication
  // - Verify username/password against database
  // - Use bcrypt for password verification
  // - Implement MFA if needed

  const mockUser = {
    id: 1,
    username: 'admin',
    isAdmin: true,
    role: 'admin'
  };

  const token = jwt.sign(mockUser, process.env.JWT_SECRET, {
    expiresIn: '1h',
    issuer: 'app',
    audience: 'api'
  });

  auditLog('login_success', { userId: mockUser.id }, 'success');
  res.json({ token });
});

/**
 * Protected endpoint: Get all users
 * Requires authentication and admin privileges
 * Filters sensitive data based on permissions
 */
app.get('/users', authenticateToken, requireAdmin, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
    { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
  ];

  auditLog('users_accessed', {
    userId: req.user.id,
    count: users.length
  }, 'success');

  res.json(users);
});

/**
 * Protected endpoint: Get user by ID
 * Requires authentication and proper authorization
 */
app.get('/users/:id', authenticateToken, [
  param('id')
    .isInt({ min: 1 })
    .toInt()
    .withMessage('Invalid user ID')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const requestedId = req.params.id;

  // Authorization: users can only see their own data, admins see all
  if (req.user.id !== requestedId && !req.user.isAdmin) {
    auditLog('unauthorized_access', {
      userId: req.user.id,
      requestedId,
      path: '/users/:id'
    }, 'denied');
    return res.status(403).json({ error: 'Unauthorized' });
  }

  // Mock database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === requestedId);
  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  auditLog('user_accessed', {
    userId: req.user.id,
    accessedUserId: requestedId
  }, 'success');

  res.json(user);
});

/**
 * Search users with input validation
 */
app.get('/users/search/query', authenticateToken, [
  query('name')
    .trim()
    .optional()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be 1-100 characters'),
  query('email')
    .trim()
    .optional()
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email format'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be 1-100')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { name, email, limit = 10 } = req.query;

  auditLog('users_searched', {
    userId: req.user.id,
    filters: { name, email },
    limit
  }, 'success');

  // Mock search logic
  const results = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
  ].slice(0, limit);

  res.json(results);
});

// ============================================================================
// 7. ERROR HANDLING
// ============================================================================

/**
 * 404 handler
 */
app.use((req, res) => {
  auditLog('not_found', {
    method: req.method,
    path: req.path
  }, 'failed');
  res.status(404).json({ error: 'Not Found' });
});

/**
 * Global error handler (must be last)
 * Prevents stack trace exposure in production
 */
app.use((err, req, res, next) => {
  console.error('Error:', err);

  const isDevelopment = process.env.NODE_ENV === 'development';
  const statusCode = err.statusCode || err.status || 500;
  const message = isDevelopment ? err.message : 'Internal Server Error';

  auditLog('error', {
    error: message,
    statusCode,
    path: req.path,
    method: req.method
  }, 'failed');

  res.status(statusCode).json({
    error: message,
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================================================
// 8. ENVIRONMENT VALIDATION
// ============================================================================

const requiredEnvVars = ['JWT_SECRET', 'NODE_ENV'];
const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);

if (missingEnvVars.length > 0) {
  console.error(
    'Missing required environment variables:',
    missingEnvVars.join(', ')
  );
  process.exit(1);
}

// ============================================================================
// 9. SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  auditLog('server_started', { port: PORT }, 'info');
});

// ============================================================================
// 10. GRACEFUL SHUTDOWN
// ============================================================================

process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  auditLog('server_shutdown', { signal: 'SIGTERM' }, 'info');
  process.exit(0);
});

module.exports = app;

