```javascript
/**
 * Secure secrets configuration
 * Validates and loads secrets from environment with proper error handling
 */

require('dotenv').config();

// List of required secrets
const REQUIRED_SECRETS = {
  NODE_ENV: { default: 'development' },
  PORT: { default: 3000, type: 'number' },
  DATABASE_URL: { required: true, sensitive: true },
  AWS_ACCESS_KEY_ID: { required: true, sensitive: true },
  AWS_SECRET_ACCESS_KEY: { required: true, sensitive: true },
  JWT_SECRET: { required: true, sensitive: true, minLength: 32 },
  STRIPE_SECRET_KEY: { required: true, sensitive: true },
  LOGFIRE_TOKEN: { required: true, sensitive: true },
};

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.validate();
  }

  validate() {
    const missing = [];
    const invalid = [];

    for (const [key, config] of Object.entries(REQUIRED_SECRETS)) {
      const value = process.env[key];

      // Check if required secret is missing
      if (config.required && !value) {
        missing.push(key);
        continue;
      }

      // Use default if not required and missing
      if (!value && config.default !== undefined) {
        this.secrets[key] = config.default;
        continue;
      }

      // Type validation
      if (config.type === 'number') {
        const num = parseInt(value, 10);
        if (isNaN(num)) {
          invalid.push(`${key} must be a number`);
        }
        this.secrets[key] = num;
        continue;
      }

      // Length validation (e.g., JWT_SECRET should be strong)
      if (config.minLength && value.length < config.minLength) {
        invalid.push(`${key} must be at least ${config.minLength} characters`);
        continue;
      }

      this.secrets[key] = value;
    }

    // Report errors
    if (missing.length > 0) {
      const error = `Missing required secrets: ${missing.join(', ')}\n` +
        `Copy .env.example to .env and configure values`;
      console.error('❌', error);
      process.exit(1);
    }

    if (invalid.length > 0) {
      console.error('❌ Invalid secrets:\n', invalid.join('\n'));
      process.exit(1);
    }

    console.log(`✅ Secrets validated (${Object.keys(this.secrets).length} loaded)`);
  }

  get(key) {
    if (!this.secrets.hasOwnProperty(key)) {
      throw new Error(`Secret '${key}' not found`);
    }
    return this.secrets[key];
  }

  // Prevent accidentally logging secrets
  getLoggable() {
    const loggable = {};
    for (const [key, config] of Object.entries(REQUIRED_SECRETS)) {
      if (!config.sensitive) {
        loggable[key] = this.secrets[key];
      } else {
        loggable[key] = '***REDACTED***';
      }
    }
    return loggable;
  }

  // For debugging - never log real values
  inspect() {
    return this.getLoggable();
  }
}

const secretsManager = new SecretsManager();

module.exports = secretsManager;
```

