async function getSecret(secretName) {
  const now = Date.now();

  // Return cached value if still valid
  if (secretsCache[secretName] && now < cacheExpiry) {
    console.log(`[SECURITY] Using cached secret: ${secretName}`);
    return secretsCache[secretName];
