    "start": "node app_SECURE.js",
    "dev": "NODE_ENV=development nodemon app_SECURE.js",
    "test": "jest --coverage",
    "security:audit": "npm audit",
    "security:scan": "snyk test",
    "security:check": "npm audit && snyk test"
  }
}
