// ✅ Secure - Parameterized query
const query = 'SELECT * FROM users WHERE id = $1';
db.query(query, [req.params.id]);
```

### Example with PostgreSQL:

```javascript
const pg = require('pg');
const client = new pg.Client({
  user: process.env.DB_USER,
