// ============================================================================
const createLimiter = (windowMs, max, message) => 
  rateLimit({
    windowMs,
    max,
    message,
    standardHeaders: true, // Return rate limit info in RateLimit-* headers
    legacyHeaders: false,
    keyGenerator: (req) => {
