## Quick Fixes for Current App

### Fix #1: Add Authentication (Most Critical)
```javascript
// Current (VULNERABLE):
app.get('/users', (req, res) => {
  res.json(users);
});

// Fixed:
const { authenticate, authorize } = require('./middleware/auth');

app.get('/users', authenticate, authorize('admin'), (req, res) => {
  res.json(users);
});
```

### Fix #2: Add Input Validation
```javascript
// Current (VULNERABLE):
app.get('/search', (req, res) => {
  const term = req.query.term; // No validation!
});

// Fixed:
const { query, validationResult } = require('express-validator');

app.get('/search',
  query('term')
    .trim()
    .isLength({ min: 1, max: 100 })
    .matches(/^[a-zA-Z0-9\s-]*$/)
    .withMessage('Invalid search term'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use req.query.term
  }
);
```

### Fix #3: Add Security Headers
```javascript
const helmet = require('helmet');
app.use(helmet()); // Adds CSP, X-Frame-Options, etc.
```

### Fix #4: Add Rate Limiting
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});

app.use(limiter);
```

### Fix #5: Hide Sensitive Data
```javascript
// Current (EXPOSES PII):
res.json(users); // Includes emails!

// Fixed:
const safeUsers = users.map(u => ({
  id: u.id,
  name: u.name
  // No email, password hash, etc.
}));
res.json(safeUsers);
```

