# Security Quick Fixes for app.js

## One-Minute Overview

Your app has **10 critical security issues**. Here's the fastest way to fix them:

## Immediate Actions (Do These First!)

### 1. Install Security Packages
```bash
npm install helmet cors express-rate-limit express-validator jsonwebtoken
```

### 2. Add Security Headers (5 minutes)
```javascript
const helmet = require('helmet');
app.use(helmet()); // Add at top, right after app = express()
```

### 3. Protect the /users Endpoint (10 minutes)
```javascript
const jwt = require('jsonwebtoken');

// Add authentication middleware
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });
  try {
    req.user = jwt.verify(token, 'your-secret-key');
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid token' });
  }
};

// Change /users route
app.get('/users', authenticate, (req, res) => {
  res.json([
    { id: 1, name: 'Alice' }, // REMOVE email!
    { id: 2, name: 'Bob' }     // REMOVE email!
  ]);
});
```

### 4. Add Rate Limiting (5 minutes)
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

app.use(limiter); // Add after helmet
```

### 5. Add Input Validation (10 minutes)
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users',
  authenticate,
  query('limit').optional().isInt({ min: 1, max: 100 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // ... rest of code
  }
);
```

### 6. Add Error Handling (5 minutes)
```javascript
// Add at the END of file, after all routes
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ 
    error: 'Internal Server Error' 
    // Don't expose err.message in production!
  });
});
```

## Total Time: ~35 minutes to get 80% of security working!

---

## Updated app.js (Minimal Version)

```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');

const app = express();

// Security middleware
app.use(helmet());
app.use(cors({ origin: 'http://localhost:3000' }));
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));
app.use(express.json());

// Authentication
const authenticate = (req, res, next) => {
  try {
    const token = req.headers.authorization?.split(' ')[1];
    if (!token) return res.status(401).json({ error: 'No token' });
    req.user = jwt.verify(token, process.env.JWT_SECRET || 'secret');
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid token' });
  }
};

// Public endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// Protected endpoint with validation
app.get('/users',
  authenticate,
  query('limit').optional().isInt({ min: 1, max: 100 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    res.json([
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' }
    ]);
  }
);

// Error handler
app.use((err, req, res, next) => {
  res.status(500).json({ error: 'Server error' });
});

app.listen(3000, () => console.log('Server on 3000'));
module.exports = app;
```

---

## Testing Your Changes

```bash
# Try without token (should fail)
curl http://localhost:3000/api/users

# Try with token (should work)
TOKEN=$(curl -s http://localhost:3000/auth | jq .token)
curl -H "Authorization: Bearer $TOKEN" http://localhost:3000/api/users

# Check security headers
curl -i http://localhost:3000/health | grep -i "x-content"
```

---

## Next Steps After Quick Fixes

1. **Create .env file**
   ```
   JWT_SECRET=your-random-secret-here-min-32-chars
   ALLOWED_ORIGINS=http://localhost:3000,https://yourdomain.com
   ```

2. **Add validation properly** (use middleware/validation.js provided)

3. **Add logging** (use middleware/auth.js provided)

4. **Run npm audit**
   ```bash
   npm audit
   npm audit fix
   ```

5. **Test everything**
   ```bash
   npm test
   ```

---

## Validation Checklist

- [ ] Authentication required for /users
- [ ] No emails in response
- [ ] Rate limiting active (test with many requests)
- [ ] Error handler doesn't expose stack traces
- [ ] Security headers present (check with curl -i)
- [ ] Input validation works (try invalid params)
- [ ] npm audit shows 0 vulnerabilities

---

## Common Mistakes to Avoid

❌ **DON'T**: Store JWT_SECRET in code
```javascript
const SECRET = 'hardcoded'; // WRONG!
```

✅ **DO**: Use environment variables
```javascript
const SECRET = process.env.JWT_SECRET; // CORRECT
```

---

❌ **DON'T**: Return sensitive data
```javascript
res.json(user); // Includes password hash!
```

✅ **DO**: Return only needed fields
```javascript
res.json({ id: user.id, name: user.name });
```

---

❌ **DON'T**: Trust user input
```javascript
db.query(`SELECT * FROM users WHERE id = ${req.query.id}`);
```

✅ **DO**: Validate and sanitize
```javascript
query('id').isInt().toInt();
db.query('SELECT * FROM users WHERE id = $1', [req.query.id]);
```

---

## Questions?

Refer to the full security review files:
- `SECURITY_BEST_PRACTICES.md` - Detailed explanations
- `app-secure-example.js` - Full implementation
- `SECURITY_REVIEW.txt` - Complete analysis
EOF
cat QUICK_FIXES.md

