      }

      // Cache the secret
      this.cache.set(secretName, secret);
      this.cacheExpiry.set(secretName, now + this.CACHE_TTL);

      return secret;
    } catch (error) {
      console.error(`[Secrets] Failed to fetch ${secretName}:`, error.message);
      throw new Error(`Could not retrieve secret: ${secretName}`);
    }
  }

  invalidateCache(secretName) {
    this.cache.delete(secretName);
    this.cacheExpiry.delete(secretName);
  }

  invalidateAllCache() {
    this.cache.clear();
    this.cacheExpiry.clear();
  }
}

