/**
 * SECURE VERSION OF app.js
 * Production-ready implementation with security best practices
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, param, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');
require('dotenv').config();

// ============================================================================
// CONFIGURATION & SETUP
// ============================================================================

const app = express();
const PORT = process.env.PORT || 3000;
const JWT_SECRET = process.env.JWT_SECRET;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Validate required environment variables
if (!JWT_SECRET && NODE_ENV === 'production') {
  throw new Error('JWT_SECRET environment variable is required');
}

// ============================================================================
// LOGGING SETUP (Recommendation #10)
// ============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error' 
    }),
    new winston.transports.File({ 
      filename: 'logs/combined.log' 
    })
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.combine(
      winston.format.colorize(),
      winston.format.simple()
    )
  }));
}

// ============================================================================
// MIDDLEWARE - SECURITY HEADERS (Recommendation #4)
// ============================================================================

// Use helmet for comprehensive security headers
app.use(helmet());

// Additional security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

// ============================================================================
// MIDDLEWARE - HTTPS ENFORCEMENT (Recommendation #11)
// ============================================================================

app.use((req, res, next) => {
  if (NODE_ENV === 'production' && req.header('x-forwarded-proto') !== 'https') {
    return res.redirect(301, `https://${req.header('host')}${req.url}`);
  }
  next();
});

// ============================================================================
// MIDDLEWARE - CORS (Recommendation #7)
// ============================================================================

const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600, // 1 hour
};

app.use(cors(corsOptions));

// ============================================================================
// MIDDLEWARE - BODY PARSING
// ============================================================================

app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================================================
// MIDDLEWARE - REQUEST LOGGING (Recommendation #10)
// ============================================================================

app.use((req, res, next) => {
  logger.info({
    type: 'REQUEST',
    method: req.method,
    path: req.path,
    ip: req.ip || req.connection.remoteAddress,
    userAgent: req.get('user-agent'),
  });
  next();
});

// ============================================================================
// MIDDLEWARE - RATE LIMITING (Recommendation #5)
// ============================================================================

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => NODE_ENV !== 'production', // Skip rate limiting in development
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Stricter limit for authentication
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, please try again later.',
});

app.use(generalLimiter); // Apply to all routes

// ============================================================================
// AUTHENTICATION MIDDLEWARE (Recommendation #1)
// ============================================================================

const verifyToken = (req, res, next) => {
  try {
    const authHeader = req.headers['authorization'];

    if (!authHeader) {
      logger.warn({
        type: 'AUTH_FAILED',
        reason: 'No token provided',
        ip: req.ip,
      });
      return res.status(401).json({ 
        error: 'Unauthorized: No token provided' 
      });
    }

    const parts = authHeader.split(' ');
    if (parts.length !== 2 || parts[0] !== 'Bearer') {
      logger.warn({
        type: 'AUTH_FAILED',
        reason: 'Invalid token format',
        ip: req.ip,
      });
      return res.status(401).json({ 
        error: 'Unauthorized: Invalid token format' 
      });
    }

    const token = parts[1];
    const decoded = jwt.verify(token, JWT_SECRET);

    req.user = decoded;
    logger.debug({
      type: 'AUTH_SUCCESS',
      userId: decoded.id,
    });
    next();
  } catch (err) {
    logger.warn({
      type: 'AUTH_FAILED',
      reason: err.message,
      ip: req.ip,
    });
    return res.status(401).json({ 
      error: 'Unauthorized: Invalid or expired token' 
    });
  }
};

// ============================================================================
// DATA SANITIZATION (Recommendation #6)
// ============================================================================

const sanitizeUser = (user) => {
  // Only expose safe fields
  return {
    id: user.id,
    name: user.name,
    // Do NOT expose: email, password, phone, SSN, etc.
  };
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health Check Endpoint
 * No authentication required
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: NODE_ENV 
    });
  } catch (err) {
    logger.error({
      type: 'ERROR',
      route: '/health',
      error: err.message,
    });
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Users Endpoint
 * Requires authentication (Recommendation #1)
 * Returns sanitized data (Recommendation #6)
 */
app.get('/users', 
  verifyToken, // Require authentication
  async (req, res) => {
    try {
      // In production, fetch from database with parameterized queries
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

