      logger.info({
        type: 'GET_USERS',
        userId: req.user.id,
        count: sanitizedUsers.length,
      });

      res.json(sanitizedUsers);
    } catch (err) {
      logger.error({
        type: 'ERROR',
        route: '/users',
        error: err.message,
        stack: err.stack,
      });
      res.status(500).json({ 
        error: NODE_ENV === 'production' 
          ? 'Internal server error' 
          : err.message 
      });
    }
  }
);

/**
 * Get User by ID
 * Requires authentication
 * Input validation (Recommendation #2)
 * SQL injection prevention (Recommendation #3)
 */
app.get('/users/:id',
  verifyToken,
  param('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer'),
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn({
          type: 'VALIDATION_ERROR',
          route: '/users/:id',
          errors: errors.array(),
        });
        return res.status(400).json({ errors: errors.array() });
      }

      const userId = parseInt(req.params.id, 10);

      // In production:
      // const user = await User.findById(userId); // Using ORM
      // OR
      // const user = await db.query('SELECT * FROM users WHERE id = ?', [userId]); // Parameterized query

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      res.json(sanitizeUser(user));
    } catch (err) {
      logger.error({
        type: 'ERROR',
        route: '/users/:id',
        error: err.message,
      });
      res.status(500).json({ 
        error: NODE_ENV === 'production' 
          ? 'Internal server error' 
          : err.message 
      });
    }
  }
);

/**
 * Mock Login Endpoint
 * Input validation (Recommendation #2)
 * Rate limiting (Recommendation #5)
 * Logging (Recommendation #10)
 */
app.post('/login',
  strictLimiter, // Strict rate limiting
  query('username')
    .trim()
    .isLength({ min: 3, max: 50 })
    .withMessage('Username must be 3-50 characters'),
  query('password')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters'),
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn({
          type: 'LOGIN_FAILED',
          reason: 'Validation error',
          username: req.query.username,
          ip: req.ip,
          errors: errors.array(),
        });
        return res.status(400).json({ errors: errors.array() });
      }

      const { username, password } = req.query;

      // In production: verify credentials against database
      // const user = await User.findOne({ username });
      // const isValid = await bcrypt.compare(password, user.passwordHash);

      // Mock verification
      const isValid = username === 'admin' && password === 'password123';

      if (!isValid) {
        logger.warn({
          type: 'LOGIN_FAILED',
          reason: 'Invalid credentials',
          username,
          ip: req.ip,
        });
        return res.status(401).json({ error: 'Invalid credentials' });
      }

      const token = jwt.sign(
        { id: 1, username },
        JWT_SECRET,
        { expiresIn: '1h' }
      );

      logger.info({
        type: 'LOGIN_SUCCESS',
        username,
        ip: req.ip,
      });

      res.json({ token });
    } catch (err) {
      logger.error({
        type: 'ERROR',
        route: '/login',
        error: err.message,
      });
      res.status(500).json({ 
        error: NODE_ENV === 'production' 
          ? 'Internal server error' 
          : err.message 
      });
    }
  }
);

// ============================================================================
// ERROR HANDLING (Recommendation #9)
// ============================================================================

// Handle 404 errors
app.use((req, res) => {
  logger.warn({
    type: '404_NOT_FOUND',
    method: req.method,
    path: req.path,
    ip: req.ip,
  });
  res.status(404).json({ error: 'Not found' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  logger.error({
    type: 'UNHANDLED_ERROR',
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  const statusCode = err.statusCode || 500;
  const message = NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(statusCode).json({
    error: message,
    ...(NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  logger.info({
    type: 'SERVER_START',
    port: PORT,
    environment: NODE_ENV,
