// config/secrets.js
const aws = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new aws.SecretsManager({ 
      region: process.env.AWS_REGION 
    });
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const response = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      const secret = 'SecretString' in response 
        ? JSON.parse(response.SecretString)
        : Buffer.from(response.SecretBinary, 'base64').toString('ascii');

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }

  async initialize() {
    try {
      this.database = await this.getSecret('prod/database');
      this.stripe = await this.getSecret('prod/stripe');
      this.anthropic = await this.getSecret('prod/anthropic');
      console.log('✓ Secrets loaded successfully');
    } catch (error) {
      console.error('✗ Failed to initialize secrets:', error);
      process.exit(1);
    }
  }
}

module.exports = new SecretsManager();
```

