   * Get secret with caching
   * @param {string} secretName - Name of the secret in AWS Secrets Manager
   * @returns {Promise<Object>} Parsed secret
   */
  async getSecret(secretName) {
    // Check cache first
    if (this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        console.log(`✓ Using cached secret: ${secretName}`);
        return cached.value;
      } else {
        this.cache.delete(secretName);
      }
    }

    try {
      console.log(`⟳ Fetching secret from AWS Secrets Manager: ${secretName}`);

      const response = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      let secret;
      if ('SecretString' in response) {
        secret = JSON.parse(response.SecretString);
      } else {
        // Handle binary secrets
        secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      this.auditLog('SECRET_RETRIEVED', secretName, true);
      return secret;

    } catch (error) {
      this.auditLog('SECRET_RETRIEVAL_FAILED', secretName, false, error.message);
      console.error(`✗ Failed to retrieve secret ${secretName}:`, error.message);

      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      } else if (error.code === 'AccessDeniedException') {
        throw new Error(`Access denied to secret: ${secretName}`);
      } else {
        throw new Error(`Secret retrieval failed: ${secretName}`);
      }
    }
  }

  /**
   * Get multiple secrets
   * @param {string[]} secretNames - Array of secret names
   * @returns {Promise<Object>} Object with all secrets
