      this.getSecret(name).catch(err => {
        console.error(`Error fetching ${name}:`, err.message);
        return null;
      })
    );

    const results = await Promise.all(promises);

    const secrets = {};
    secretNames.forEach((name, index) => {
      if (results[index]) {
        secrets[name] = results[index];
      }
    });

    return secrets;
  }

