  logger.warn({
    timestamp: new Date().toISOString(),
    eventType,
    ...details
  });
};

app.use((req, res, next) => {
  res.on('finish', () => {
    if (res.statusCode >= 400) {
      logSecurityEvent('HTTP_ERROR', {
        method: req.method,
        path: req.path,
        status: res.statusCode,
