// Secure version of app.js with all security best practices implemented

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
require('dotenv').config();

const app = express();
const port = process.env.PORT || 3000;
const nodeEnv = process.env.NODE_ENV || 'development';

// ============================================================
// 1. SECURITY HEADERS - Helmet
// ============================================================
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true,
  },
}));

// ============================================================
// 2. CORS CONFIGURATION - Restrictive
// ============================================================
const corsOptions = {
  origin: (origin, callback) => {
    const allowedOrigins = (process.env.ALLOWED_ORIGINS || '').split(',').filter(Boolean);

    // Allow requests with no origin (like mobile apps or Postman)
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600, // 1 hour
};

app.use(cors(corsOptions));

// ============================================================
// 3. BODY PARSER & LOGGING
// ============================================================
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: true }));
app.use(morgan('combined')); // HTTP request logging

// ============================================================
// 4. RATE LIMITING
// ============================================================
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => {
    // Don't rate limit health checks if needed
    return false;
  },
});

const strictLimiter = rateLimit({
  windowMs: 1 * 60 * 1000, // 1 minute
  max: 5,
  message: 'Too many login attempts, please try again later.',
});

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 50,
  message: 'Too many API requests from this IP, please try again later.',
});

app.use(globalLimiter);

// ============================================================
// 5. AUTHENTICATION MIDDLEWARE
// ============================================================
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET || 'your-secret-key', (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ============================================================
// 6. AUTHORIZATION MIDDLEWARE
// ============================================================
const authorize = (requiredRoles = []) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'User not authenticated' });
    }

    if (requiredRoles.length > 0 && !requiredRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// ============================================================
// 7. INPUT VALIDATION MIDDLEWARE
// ============================================================
const validateUserQueryParams = [
  query('filter')
    .optional()
    .isString()
    .trim()
    .isLength({ max: 50 })
    .withMessage('Filter must be a string with max 50 characters')
    .escape(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be >= 0')
    .toInt(),
];

// ============================================================
// 8. ERROR HANDLING MIDDLEWARE
// ============================================================
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(e => ({ field: e.param, message: e.msg }))
    });
  }
  next();
};

// ============================================================
// 9. SECURE ENDPOINTS
// ============================================================

// Health check endpoint - No auth required, but rate limited
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    env: nodeEnv,
  });
});

// Public endpoint - Accessible but rate limited
app.get('/public/info', apiLimiter, (req, res) => {
  res.json({
    message: 'This is public information',
    version: '1.0.0',
  });
});

// Protected endpoint - Requires authentication
app.get(
  '/users',
  apiLimiter,
  authenticateToken,
  authorize(['admin', 'user']),
  validateUserQueryParams,
  handleValidationErrors,
  (req, res) => {
    // Mock user data
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
    ];

    // Apply filters (input is already validated and escaped)
    if (req.query.filter) {
      const filter = req.query.filter.toLowerCase();
      users = users.filter(u =>
        u.name.toLowerCase().includes(filter) ||
        u.email.toLowerCase().includes(filter)
      );
    }

    // Apply pagination
    const offset = req.query.offset || 0;
    const limit = req.query.limit || 10;
    const paginatedUsers = users.slice(offset, offset + limit);

    // Filter sensitive data based on user role
    if (req.user.role !== 'admin') {
      // Non-admin users only get public fields
      const publicUsers = paginatedUsers.map(({ id, name }) => ({ id, name }));
      return res.json({
        data: publicUsers,
        total: users.length,
        limit,
        offset,
      });
    }

    // Admin users get all fields
    res.json({
      data: paginatedUsers,
      total: users.length,
      limit,
      offset,
    });
  }
);

// Admin-only endpoint
app.get(
  '/admin/users/:id',
  apiLimiter,
  authenticateToken,
  authorize(['admin']),
  (req, res) => {
    const userId = parseInt(req.params.id, 10);

    if (isNaN(userId)) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    // Simulate database lookup
    const user = { id: userId, name: 'User', email: 'user@example.com' };

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  }
);

// Login endpoint - Rate limited strictly
app.post('/auth/login', strictLimiter, express.json(), (req, res) => {
  // This is a simplified example. In production, verify against a database
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password required' });
  }

  // Simulate user authentication (use bcrypt in production!)
  if (username === 'admin' && password === 'password123') {
    const token = jwt.sign(
      { id: 1, username: 'admin', role: 'admin' },
      process.env.ACCESS_TOKEN_SECRET || 'your-secret-key',
      { expiresIn: '1h' }
    );

    return res.json({
      token,
      expiresIn: '1h',
      user: { id: 1, username: 'admin', role: 'admin' },
    });
  }

  res.status(401).json({ error: 'Invalid credentials' });
});

// ============================================================
// 10. 404 HANDLER
// ============================================================
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Endpoint ${req.method} ${req.path} does not exist`,
  });
});

// ============================================================
// 11. GLOBAL ERROR HANDLER
// ============================================================
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't leak stack traces in production
  const isDevelopment = nodeEnv === 'development';

  const status = err.status || err.statusCode || 500;
  const response = {
    error: err.message || 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack }),
  };

  res.status(status).json(response);
});

// ============================================================
// 12. SERVER STARTUP
// ============================================================
