### Best Practice Implementation

```javascript
// config/secrets-config.js
require('dotenv').config({ path: process.env.NODE_ENV === 'production' ? null : '.env' });

const secretSources = {
  production: ['AWS_SECRETS_MANAGER', 'ENVIRONMENT'],
  staging: ['VAULT', 'ENVIRONMENT'],
  development: ['DOTENV', 'ENVIRONMENT']
};

const requiredSecrets = [
  'DATABASE_URL',
  'JWT_SECRET',
  'STRIPE_SECRET_KEY',
  'ANTHROPIC_API_KEY',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY'
];

/**
 * Validate that all required secrets are present
 */
function validateSecrets() {
  const missing = requiredSecrets.filter(secret => !process.env[secret]);

  if (missing.length > 0) {
    console.error('❌ Missing required secrets:', missing);
    console.error('Startup aborted for security reasons');
    process.exit(1);
  }

  console.log('✓ All required secrets configured');
}

/**
 * Sanitize secrets from logs
 */
function createSanitizer() {
  const secretValues = requiredSecrets.map(key => process.env[key]).filter(Boolean);

  return function sanitize(message) {
    let sanitized = String(message);
    secretValues.forEach(secret => {
      if (secret && secret.length > 4) {
        const pattern = new RegExp(secret, 'g');
        const masked = '*'.repeat(Math.max(3, secret.length - 4)) + secret.slice(-4);
        sanitized = sanitized.replace(pattern, masked);
      }
    });
    return sanitized;
  };
}

module.exports = {
  validateSecrets,
  createSanitizer,
  requiredSecrets
};
```

