**Step 4: Add pre-commit hook script:**
```bash
#!/bin/bash
# .git/hooks/pre-commit

echo "🔐 Checking for secrets in staged files..."

# Check for common secret patterns
SECRETS=0

if git diff --cached | grep -qE '\.(env|properties|yml|yaml):.*=.*' | grep -v '^#'; then
  echo "❌ BLOCKED: Potential secrets detected in .env file"
  SECRETS=1
