// config/secret-rotation.js
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

/**
 * Rotate secrets automatically
 * Should be called by Lambda/scheduled task weekly
 */
async function rotateSecrets() {
  const secrets = [
    'prod/database-password',
    'prod/api-keys',
    'prod/encryption-key'
  ];

  for (const secretName of secrets) {
    try {
      await secretsManager.rotateSecret({
        SecretId: secretName,
        RotationLambdaARN: process.env.ROTATION_LAMBDA_ARN,
        RotationRules: {
          AutomaticallyAfterDays: 7 // Rotate every 7 days
        }
      }).promise();

      console.log(`✅ Rotation enabled for: ${secretName}`);
    } catch (error) {
      console.error(`Error rotating ${secretName}:`, error);
      // Alert monitoring system
      await notifySecurityTeam({
        event: 'secret_rotation_failed',
        secretName,
        error: error.message
      });
    }
  }
}

module.exports = { rotateSecrets };
```

