const auditLogger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ 
      filename: 'audit/secret-access.log',
      maxsize: 5242880, // 5MB
      maxFiles: 30
    }),
  ],
});

async function logSecretAccess(secretName, userId, action, success, error = null) {
  auditLogger.info({
    timestamp: new Date().toISOString(),
    secretName,
    userId,
    action, // 'read', 'create', 'update', 'delete'
    success,
    error: error?.message || null,
    requestId: require('uuid').v4(),
  });
}

// Wrap secret retrieval
async function getSecretWithLogging(secretName, userId) {
  try {
    const secret = await getSecret(secretName);
    await logSecretAccess(secretName, userId, 'read', true);
    return secret;
  } catch (error) {
    await logSecretAccess(secretName, userId, 'read', false, error);
    throw error;
  }
}

module.exports = { logSecretAccess, getSecretWithLogging };
