// SECURED VERSION OF app.js
// Implements OWASP Top 10 security best practices

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { param, query, body, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
require('dotenv').config();

const app = express();

// ============================================
// SECURITY MIDDLEWARE - Priority 1
// ============================================

// 1. Helmet: Set comprehensive security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true,
  },
}));

// 2. CORS: Restrict cross-origin requests
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  credentials: true,
  maxAge: 3600,
  optionsSuccessStatus: 200,
  allowedHeaders: ['Content-Type', 'Authorization'],
};
app.use(cors(corsOptions));

// 3. Rate limiting: Prevent DoS and brute force
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => process.env.NODE_ENV === 'development',
});
app.use(generalLimiter);

// Stricter limiter for auth endpoints
const authLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 5,
  message: 'Too many login attempts, please try again later.',
  skipSuccessfulRequests: true,
});

// 4. Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============================================
// AUTHENTICATION MIDDLEWARE
// ============================================

/**
 * Validates JWT token from Authorization header
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object
 * @param {Function} next - Express next middleware function
 */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({
      error: 'Access token required',
      code: 'MISSING_TOKEN',
    });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET || 'dev-secret', (err, user) => {
    if (err) {
      // Log failed authentication attempt (could be brute force)
      console.warn(`Failed token verification from IP: ${req.ip}, Error: ${err.message}`);
      return res.status(403).json({
        error: 'Invalid or expired token',
        code: 'INVALID_TOKEN',
      });
    }

    req.user = user;
    next();
  });
}

/**
 * Verifies user has admin role
 */
function authorizeAdmin(req, res, next) {
  if (req.user.role !== 'admin') {
    return res.status(403).json({
      error: 'Admin access required',
      code: 'INSUFFICIENT_PERMISSIONS',
    });
  }
  next();
}

// ============================================
// PUBLIC ROUTES
// ============================================

/**
 * Health check endpoint - public, no auth required
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: '1.0.0',
    environment: process.env.NODE_ENV || 'development',
  });
});

// ============================================
// PROTECTED ROUTES
// ============================================

/**
 * Get all users (admin only)
 * Returns user data without sensitive information
 * PROTECTIONS:
 * - JWT authentication required
 * - Admin authorization required
 * - Input validation on query parameters
 * - Rate limited
 */
app.get('/api/v1/users',
  authenticateToken,
  authorizeAdmin,
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .toInt()
    .withMessage('Offset must be a non-negative integer'),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array(),
      });
    }

    // Apply limits to prevent large data transfers
    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    // Return only necessary fields - never expose passwords, tokens, etc.
    const users = [
      { id: 1, name: 'Alice', role: 'user' },
      { id: 2, name: 'Bob', role: 'user' },
    ];

    res.json({
      data: users.slice(offset, offset + limit),
      limit,
      offset,
      total: users.length,
    });
  }
);

/**
 * Get user by ID (users can only see their own data, admins see all)
 * PROTECTIONS:
 * - JWT authentication required
 * - Parameter validation
 * - Authorization check (own data or admin)
 */
app.get('/api/v1/users/:id',
  authenticateToken,
  param('id')
    .isInt({ min: 1 })
    .toInt()
    .withMessage('ID must be a positive integer'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array(),
      });
    }

    const userId = req.params.id;

    // Authorization: Users can only see their own data
    if (req.user.role !== 'admin' && req.user.id !== userId) {
      return res.status(403).json({
        error: 'You can only access your own user data',
        code: 'UNAUTHORIZED',
      });
    }

    // In a real app, fetch from database
    if (userId === 1) {
      return res.json({
        id: 1,
        name: 'Alice',
        role: 'user',
      });
    }

    res.status(404).json({
      error: 'User not found',
      code: 'NOT_FOUND',
    });
  }
);

/**
 * Create a new user (admin only)
 * PROTECTIONS:
 * - JWT authentication required
 * - Admin authorization required
 * - Input validation on all fields
 * - Rate limited (to prevent spam)
 * - Sanitized inputs
 */
app.post('/api/v1/users',
  authLimiter,
  authenticateToken,
  authorizeAdmin,
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .escape()
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email address'),
  body('role')
    .isIn(['user', 'admin'])
    .withMessage('Role must be either "user" or "admin"'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array(),
      });
    }

    // Validated and sanitized input
    const { name, email, role } = req.body;

    // In a real app, check for duplicate email before inserting
    // In a real app, hash password if provided
    const newUser = {
      id: 3,
      name,
      email,
      role,
      createdAt: new Date().toISOString(),
    };

    // Don't send sensitive fields back to client
    const { ...safeUser } = newUser;
    delete safeUser.email; // Optional: hide email from response

    res.status(201).json({
      message: 'User created successfully',
      data: safeUser,
    });
  }
);

// ============================================
// ERROR HANDLING - Priority 2
// ============================================

/**
 * Handle 404 errors
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Endpoint not found',
    code: 'NOT_FOUND',
    path: req.path,
    method: req.method,
  });
});

/**
 * Global error handler
 * Should be last middleware
 * PROTECTIONS:
 * - Doesn't expose stack traces in production
 * - Logs errors for debugging
 * - Returns consistent error format
 */
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Determine status code
  const status = err.status || err.statusCode || 500;

  // Don't expose internals in production
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal Server Error'
    : err.message;

  res.status(status).json({
    error: message,
    code: err.code || 'INTERNAL_ERROR',
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

// Validate required environment variables
if (process.env.NODE_ENV === 'production') {
  const requiredEnvVars = ['ACCESS_TOKEN_SECRET', 'NODE_ENV'];
  const missing = requiredEnvVars.filter(v => !process.env[v]);
  if (missing.length > 0) {
    console.error(`Missing required environment variables: ${missing.join(', ')}`);
    process.exit(1);
  }
}

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT} (${process.env.NODE_ENV || 'development'})`);
});

module.exports = app;

