// Automatic rotation handler
class SecretRotationManager {
  async onSecretRotation(event) {
    const { SecretId, ClientRequestToken } = event;

    // 1. Verify rotation isn't already in progress
    const metadata = await this.getSecretMetadata(SecretId);
    if (metadata.RotationEnabled) {
      console.log(`Rotation already in progress for ${SecretId}`);
      return;
    }

    // 2. Get the new secret value
    const newSecret = await secretsManager.getSecretValue({
      SecretId,
      VersionId: ClientRequestToken,
      VersionStage: 'AWSPENDING'
    });

    // 3. Test new secret works
    await this.testSecret(newSecret);

    // 4. Finalize rotation
    await secretsManager.updateSecretVersionStage({
      SecretId,
      VersionStage: 'AWSCURRENT',
      MoveToVersionId: ClientRequestToken,
      RemoveFromVersionId: metadata.VersionIdsToStages
    });
  }
}
