  ]);
});

// Issues:
// - Email harvesting for phishing
// - Privacy violations (GDPR)
// - Unnecessary password hashes exposed
```

✅ SECURE:
```javascript
app.get('/users', authenticate, authorize('admin'), (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', passwordHash: '...' },
    { id: 2, name: 'Bob', email: 'bob@example.com', passwordHash: '...' }
  ];

  // Only include necessary fields based on user role
  const sanitized = users.map(user => ({
    id: user.id,
    name: user.name,
    ...(req.user.role === 'admin' && { email: user.email })
    // passwordHash never exposed
  }));

  res.json(sanitized);
});

// Result: Minimal data disclosure, privacy compliant
```


