app.post('/comments', 
  body('text').trim().escape().isLength({ max: 1000 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    db.save(req.body.text); // Already sanitized
    res.json({ message: 'Comment saved' });
