// Result: HTML entities escaped, XSS prevented
```


11. SQL INJECTION
================================================================================

❌ VULNERABLE:
```javascript
app.get('/search', (req, res) => {
  const query = req.query.q;
  const result = db.query(`SELECT * FROM products WHERE name LIKE '%${query}%'`);
  res.json(result);
});

// Attack: ?q="%' OR '1'='1
// Becomes: SELECT * FROM products WHERE name LIKE '%' OR '1'='1%'
// Result: All products returned
```

✅ SECURE:
```javascript
app.get('/search', (req, res) => {
  const query = req.query.q;

  // Parameterized query - parameter separate from SQL
  const result = db.query(
    'SELECT * FROM products WHERE name LIKE ?',
    [`%${query}%`]
  );
  res.json(result);
});

// Result: Parameters treated as data, not code
```


