**Alternative: Using AWS Secrets Manager wrapper:**

```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager");

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    this.cache = new Map();
  }

  async getSecret(secretName, ttl = 3600000) { // 1 hour TTL
    if (this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < ttl) {
        return cached.value;
      }
    }

    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await this.client.send(command);
    const secretValue = response.SecretString 
      ? JSON.parse(response.SecretString) 
      : response.SecretBinary;

    this.cache.set(secretName, { value: secretValue, timestamp: Date.now() });
    return secretValue;
  }
}

module.exports = SecretsManager;
```

