## Minimal Secure App (50 lines)

```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');

const app = express();

// Security middleware
app.use(helmet());
app.use(cors({ origin: process.env.ALLOWED_ORIGINS?.split(',') }));
app.use(rateLimit({ max: 100, windowMs: 15 * 60 * 1000 }));

// Auth middleware
const auth = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid' });
    req.user = user;
    next();
  });
};

// Routes
app.get('/health', (req, res) => res.json({ status: 'ok' }));
app.get('/users', auth, (req, res) => res.json([{ id: 1, name: 'Alice' }]));
app.post('/login', (req, res) => {
  const token = jwt.sign({ id: 1 }, process.env.JWT_SECRET, { expiresIn: '1h' });
  res.json({ token });
});

// Error handler
app.use((err, req, res, next) => {
  res.status(500).json({ error: 'Internal error' });
});

app.listen(process.env.PORT || 3000);
```

