### Secure Configuration Pattern

```javascript
/**
 * Secure secret loading with validation
 */

require('dotenv').config(); // Only for dev/test
const logger = require('./logger');

// Minimum viable secret validation
const REQUIRED_SECRETS = [
  'JWT_SECRET',
  'DATABASE_URL',
  'NODE_ENV',
];

class SecretManager {
  constructor() {
    this.secrets = {};
    this.isInitialized = false;
  }

  async initialize() {
    const nodeEnv = process.env.NODE_ENV;

    if (nodeEnv === 'production') {
      await this.loadFromVault(); // Use enterprise vault
    } else if (nodeEnv === 'staging') {
      await this.loadFromCloudSecretManager();
    } else {
      this.loadFromEnv(); // Dev only
    }

    this.validate();
    this.isInitialized = true;
  }

  loadFromEnv() {
    logger.warn('Loading secrets from environment (DEV ONLY)');
    REQUIRED_SECRETS.forEach(key => {
      this.secrets[key] = process.env[key];
    });
  }

  async loadFromVault() {
    // Implement vault loading
    logger.info('Loading secrets from HashiCorp Vault');
    // ...
  }

  async loadFromCloudSecretManager() {
    // Implement cloud secrets
    logger.info('Loading secrets from cloud provider');
    // ...
  }

  validate() {
    const missing = REQUIRED_SECRETS.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      const error = new Error(
        `Missing required secrets: ${missing.join(', ')}`
      );
      logger.error('Secret validation failed', { missing });
      throw error;
    }

    // Validate JWT_SECRET strength
    if (this.secrets.JWT_SECRET && this.secrets.JWT_SECRET.length < 32) {
      logger.warn('JWT_SECRET is weak (< 32 characters)');
      if (process.env.NODE_ENV === 'production') {
        throw new Error('JWT_SECRET must be at least 32 characters');
      }
    }
  }

  get(key) {
    if (!this.isInitialized) {
      throw new Error('SecretManager not initialized');
    }
    return this.secrets[key];
  }
}

module.exports = new SecretManager();
```

