/**
 * Secure secret loading with strict validation
 */

const logger = require('./logger');

class SecretsManager {
  constructor() {
    this.secrets = null;
    this.isInitialized = false;
  }

  async initialize() {
    const env = process.env.NODE_ENV;

    try {
      if (env === 'production') {
        this.secrets = await this.loadFromAWSSecretsManager();
      } else if (env === 'staging') {
        this.secrets = await this.loadFromVault();
      } else {
        this.secrets = this.loadFromEnv();
      }

      this.validate();
      this.isInitialized = true;
      logger.info('Secrets loaded successfully');
    } catch (error) {
      logger.error('Failed to load secrets', { error: error.message });
      process.exit(1);
    }
  }

  validate() {
    const required = ['JWT_SECRET', 'DATABASE_URL'];
    const missing = required.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing secrets: ${missing.join(', ')}`);
    }

    // Validate JWT_SECRET strength
    if (this.secrets.JWT_SECRET.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters');
    }
  }

  get(key) {
    if (!this.isInitialized) {
      throw new Error('SecretsManager not initialized');
    }
    return this.secrets[key];
  }

  loadFromEnv() {
    logger.warn('⚠️  Loading secrets from environment (DEV ONLY)');
    return {
      JWT_SECRET: process.env.JWT_SECRET,
      DATABASE_URL: process.env.DATABASE_URL
    };
  }

  async loadFromAWSSecretsManager() {
    logger.info('Loading secrets from AWS Secrets Manager');
    const AWS = require('aws-sdk');
    const client = new AWS.SecretsManager();

    const response = await client.getSecretValue({
      SecretId: `${process.env.SECRET_NAME || 'prod/app/secrets'}`
    }).promise();

    return JSON.parse(response.SecretString);
  }

  async loadFromVault() {
    logger.info('Loading secrets from HashiCorp Vault');
    const vault = require('node-vault')({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN
    });

    const result = await vault.read('secret/data/app/staging');
    return result.data.data;
  }
}

module.exports = new SecretsManager();
```

