```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager({ region: 'us-east-1' });

let cachedSecrets = null;

async function getSecrets() {
  if (cachedSecrets) {
    return cachedSecrets;
  }

  try {
    const secretName = process.env.SECRET_NAME || 'app/secrets';
    const result = await secretsManager.getSecretValue({ SecretId: secretName }).promise();

    let secretData;
    if ('SecretString' in result) {
      secretData = JSON.parse(result.SecretString);
    } else {
      // Handle binary secrets
      secretData = Buffer.from(result.SecretBinary, 'base64').toString('ascii');
    }

    cachedSecrets = secretData;
    return secretData;
  } catch (error) {
    console.error('Failed to retrieve secrets:', error.message);
    process.exit(1);
  }
}

module.exports = { getSecrets };
```

