## **6. SECURE app.js Implementation**

```javascript
// app.js - Secure Version
require('dotenv').config({ path: '.env.local' }); // Dev only
const express = require('express');
const helmet = require('helmet');

const app = express();

// ============ SECRETS INITIALIZATION ============

let config = null;

async function initializeSecrets() {
  try {
    if (process.env.NODE_ENV === 'production') {
      // Use AWS Secrets Manager in production
      const { getSecrets } = require('./config/secrets');
      config = await getSecrets();
    } else {
      // Use .env.local in development only
      config = {
        databaseUrl: process.env.DATABASE_URL,
        jwtSecret: process.env.JWT_SECRET,
        apiKey: process.env.ANTHROPIC_API_KEY,
        stripeKey: process.env.STRIPE_SECRET_KEY,
        port: process.env.PORT || 3000,
      };

      // Validate all secrets exist
      const required = ['databaseUrl', 'jwtSecret', 'apiKey'];
      const missing = required.filter(key => !config[key]);

      if (missing.length > 0) {
        console.error('❌ Missing required secrets:', missing.join(', '));
        console.error('Create .env.local with required variables');
        process.exit(1);
      }
    }

    console.log('✅ Secrets loaded securely');
  } catch (error) {
    console.error('❌ Failed to load secrets:', error.message);
    process.exit(1);
  }
}

// ============ MIDDLEWARE ============

app.use(helmet());

// Never log secrets
app.use((req, res, next) => {
  // Remove sensitive headers from logs
  const originalJson = res.json;
  res.json = function(data) {
    if (typeof data === 'object' && data !== null) {
      const sanitized = { ...data };
      delete sanitized.apiKey;
      delete sanitized.jwtSecret;
      delete sanitized.databaseUrl;
      return originalJson.call(this, sanitized);
    }
    return originalJson.call(this, data);
  };
  next();
});

// ============ ROUTES ============

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ============ ERROR HANDLING ============

app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  // Never expose secrets in errors
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal Server Error'
    : err.message;

  res.status(500).json({ error: message });
});

// ============ SERVER STARTUP ============

async function start() {
  await initializeSecrets();

  const PORT = config.port;
  app.listen(PORT, () => {
    console.log(`🚀 Server running on port ${PORT} (${process.env.NODE_ENV} mode)`);
  });
}

if (require.main === module) {
  start().catch(error => {
    console.error('❌ Failed to start server:', error);
    process.exit(1);
  });
}

module.exports = app;
```

