### **Pre-commit Hook to Prevent Accidental Commits:**

```bash
#!/bin/bash
# .git/hooks/pre-commit

# Check for unencrypted secrets
if git diff --cached | grep -E "(AKIA|sk_live_|sk-ant-|password|secret)" >/dev/null; then
    echo "❌ ERROR: Possible secret detected in staged changes!"
    echo "Review your changes before committing."
    exit 1
fi

# Check for .env files
if git diff --cached --name-only | grep -E "\.env" >/dev/null; then
    echo "❌ ERROR: .env file detected in staged changes!"
    echo "Use .env.example instead."
    exit 1
fi

exit 0
```

