  region: process.env.AWS_REGION || 'us-east-1'
});

let cachedSecrets = null;
const SECRET_CACHE_TTL = 60000; // 1 minute
let lastSecretFetch = 0;

/**
 * Get secrets from AWS Secrets Manager with caching
 */
async function getSecrets() {
  const now = Date.now();

  if (cachedSecrets && (now - lastSecretFetch) < SECRET_CACHE_TTL) {
    return cachedSecrets;
  }

  try {
    const data = await secretsManager
      .getSecretValue({ SecretId: 'prod/app-secrets' })
      .promise();

    cachedSecrets = JSON.parse(data.SecretString);
    lastSecretFetch = now;

    return cachedSecrets;
  } catch (error) {
    console.error('❌ Failed to retrieve secrets:', error.message);

    // Fallback to environment variables if available (dev only)
    if (process.env.NODE_ENV !== 'production') {
      console.warn('⚠️  Using fallback environment variables (development only)');
      return {
        JWT_SECRET: process.env.JWT_SECRET,
        DATABASE_URL: process.env.DATABASE_URL,
      };
    }

    throw new Error('Cannot retrieve application secrets');
  }
}

/**
 * Middleware to attach secrets to request
 */
const secretsMiddleware = async (req, res, next) => {
  try {
    req.secrets = await getSecrets();
    next();
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
};

// Health check (no secrets needed)
