  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected endpoint (requires secrets)
app.get('/users', secretsMiddleware, (req, res) => {
  // Secrets are available at req.secrets
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// Graceful startup
const PORT = process.env.PORT || 3000;

(async () => {
  try {
    // Verify we can access secrets before starting
    if (process.env.NODE_ENV === 'production') {
      console.log('🔐 Verifying access to secrets manager...');
      await getSecrets();
      console.log('✓ Secrets accessible');
    }

    app.listen(PORT, () => {
      console.log(`✓ Server running on port ${PORT}`);
    });
  } catch (error) {
    console.error('❌ Failed to start server:', error.message);
    process.exit(1);
  }
})();

module.exports = app;
```

