// secrets.js
const path = require('path');
require('dotenv').config({ path: '.env.local' }); // Local only, never committed

class SecretsManager {
  constructor(environment = process.env.NODE_ENV || 'development') {
    this.environment = environment;
    this.secrets = {};
    this.loadedAt = null;
  }

  async initialize() {
    if (this.environment === 'production') {
      // Use AWS Secrets Manager
      const { SecretsManagerClient, GetSecretValueCommand } = 
        require("@aws-sdk/client-secrets-manager");

      const client = new SecretsManagerClient({ 
        region: process.env.AWS_REGION 
      });

      const command = new GetSecretValueCommand({ 
        SecretId: `prod/app-secrets` 
      });

      const response = await client.send(command);
      this.secrets = JSON.parse(response.SecretString);
    } else if (this.environment === 'staging') {
      // Use HashiCorp Vault
      const vault = require('node-vault')({
        endpoint: process.env.VAULT_ADDR,
        token: process.env.VAULT_TOKEN,
      });

      const response = await vault.read('secret/data/staging/app');
      this.secrets = response.data.data;
    } else {
      // Development: use .env.local only
      this.secrets = this.validateLocalSecrets();
    }

    this.loadedAt = new Date();
    this.logSecretLoad();
    return this.secrets;
  }

  validateLocalSecrets() {
    const required = [
      'DATABASE_URL',
      'JWT_SECRET',
      'STRIPE_SECRET_KEY',
      'AWS_ACCESS_KEY_ID',
    ];

    const missing = required.filter(key => !process.env[key]);

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets in .env.local: ${missing.join(', ')}`
      );
    }

    return {
      DATABASE_URL: process.env.DATABASE_URL,
      JWT_SECRET: process.env.JWT_SECRET,
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
    };
  }

  logSecretLoad() {
    // Log only secret names, never values
    const secretNames = Object.keys(this.secrets);
    console.log(`[Secrets] Loaded ${secretNames.length} secrets at ${this.loadedAt}`);

    // Audit log (never include values)
    if (process.env.AUDIT_LOG_ENABLED) {
      console.log({
        event: 'secrets_loaded',
        timestamp: this.loadedAt,
        environment: this.environment,
        count: secretNames.length,
      });
    }
  }

  get(key) {
    if (!this.secrets[key]) {
      throw new Error(`Secret '${key}' not found`);
    }
    return this.secrets[key];
  }

  has(key) {
    return key in this.secrets;
  }

  // Never expose all secrets
  getKeys() {
    return Object.keys(this.secrets);
  }
}

module.exports = SecretsManager;
```

