require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { body, validationResult } = require('express-validator');
const winston = require('winston');

// Initialize Express app
const app = express();

// ========== LOGGER SETUP ==========
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    ...(process.env.NODE_ENV !== 'production' 
      ? [new winston.transports.Console({ format: winston.format.simple() })]
      : []),
  ],
});

// ========== SECURITY MIDDLEWARE ==========

// 1. Helmet - Security Headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: { maxAge: 31536000, includeSubDomains: true, preload: true },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
}));

// 2. CORS Configuration
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  credentials: true,
  optionsSuccessStatus: 200,
  maxAge: 86400,
};
app.use(cors(corsOptions));

// 3. Body Parser with size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: true }));

// 4. Rate Limiting - Global
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in headers
  legacyHeaders: false,
  skip: (req) => {
    // Skip rate limiting for health checks in some cases
    return req.path === '/health' && process.env.SKIP_HEALTH_RATE_LIMIT === 'true';
  },
});
app.use(globalLimiter);

// 5. Stricter Rate Limiting for Auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Limit login attempts
  message: 'Too many login attempts, please try again later.',
  skipSuccessfulRequests: true,
  skipFailedRequests: false,
});

// ========== AUTHENTICATION MIDDLEWARE ==========

const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    logger.warn(`Authentication failed: No token provided. IP: ${req.ip}`);
    return res.status(401).json({ 
      error: 'Access denied. No token provided.',
      code: 'NO_TOKEN'
    });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;

    // Add request ID to logger context
    logger.info(`User authenticated: ${decoded.id}`, { userId: decoded.id, ip: req.ip });

    next();
  } catch (error) {
    logger.warn(`Invalid token attempt. IP: ${req.ip}. Error: ${error.message}`);

    if (error.name === 'TokenExpiredError') {
      return res.status(401).json({ 
        error: 'Token expired. Please login again.',
        code: 'TOKEN_EXPIRED'
      });
    }

    res.status(403).json({ 
      error: 'Invalid or malformed token.',
      code: 'INVALID_TOKEN'
    });
  }
};

// ========== VALIDATION SCHEMAS ==========

const loginValidation = [
  body('email').isEmail().normalizeEmail().withMessage('Invalid email format'),
  body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters'),
];

const userFilterValidation = [
  body('id').optional().isInt({ min: 1 }).withMessage('ID must be a positive integer'),
  body('role').optional().isIn(['user', 'admin']).withMessage('Invalid role'),
];

// ========== UTILITY FUNCTIONS ==========

/**
 * Generate JWT token (for demonstration - should be in auth service)
 */
const generateToken = (user) => {
  return jwt.sign(
    { id: user.id, email: user.email, role: user.role },
    process.env.JWT_SECRET,
    { expiresIn: process.env.JWT_EXPIRY || '24h' }
  );
};

/**
 * Safe error response
 */
const sendErrorResponse = (res, statusCode, message, isDev = false, error = null) => {
  const response = { error: message, code: statusCode };
  if (isDev && error) {
    response.details = error.message;
  }
  res.status(statusCode).json(response);
};

// ========== ROUTES ==========

/**
 * Health Check Endpoint
 * Public endpoint - minimal info exposure
 */
app.get('/health', (req, res) => {
  logger.debug('Health check request');
  res.json({ 
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: process.env.APP_VERSION || '1.0.0',
  });
});

