  // TODO: Replace with database lookup and password hash verification
  // NEVER store plaintext passwords!
  const user = {
    id: 1,
    email: email,
    password: 'hashed_password', // Use bcrypt in production
    role: 'user',
  };

  // In production, use bcrypt to verify password
  if (email === 'alice@example.com' && password === 'SecurePassword123!') {
    const token = generateToken(user);
