    return res.json({ token, user: { id: user.id, email: user.email } });
  }

  logger.warn(`Failed login attempt for: ${email}. IP: ${req.ip}`);
  res.status(401).json({ error: 'Invalid credentials', code: 'INVALID_CREDENTIALS' });
});

/**
 * Get Users Endpoint
 * Protected - requires authentication
 * Returns only necessary user data
 */
app.get('/users', authenticateToken, (req, res) => {
  try {
    logger.info(`User ${req.user.id} requested users list`);

    // Only return non-sensitive fields
    const users = [
      { id: 1, name: 'Alice', role: 'admin' },
      { id: 2, name: 'Bob', role: 'user' },
    ];

    res.json(users);
  } catch (error) {
    logger.error(`Error fetching users: ${error.message}`);
    sendErrorResponse(res, 500, 'Internal Server Error', 
      process.env.NODE_ENV === 'development', error);
  }
});

/**
 * Get Specific User Endpoint
 * Protected - users can only see their own details
 */
app.get('/users/:id', authenticateToken, (req, res) => {
  try {
    const userId = parseInt(req.params.id);

    // Validate input
    if (isNaN(userId) || userId < 1) {
      return res.status(400).json({ error: 'Invalid user ID', code: 'INVALID_ID' });
    }

    // Authorization check - users can only view their own data
    if (req.user.id !== userId && req.user.role !== 'admin') {
      logger.warn(`Unauthorized access attempt by user ${req.user.id} to user ${userId}`);
      return res.status(403).json({ error: 'Access denied', code: 'FORBIDDEN' });
    }

    logger.info(`User ${req.user.id} requested user ${userId} details`);

    // Return user data (with email only if owner or admin)
    const user = { id: userId, name: 'Alice', role: 'admin' };
    if (req.user.id === userId || req.user.role === 'admin') {
      user.email = 'alice@example.com';
    }

