   * Get secret from AWS Secrets Manager with caching
   */
  async getFromAWS(secretName) {
    // Check cache
    if (this.cachedSecrets && !this.isCacheExpired()) {
      if (secretName in this.cachedSecrets) {
        console.log(`Using cached secret: ${secretName}`);
        return this.cachedSecrets[secretName];
      }
    }

    try {
      const response = await this.awsSecrets
        .getSecretValue({ SecretId: secretName })
        .promise();

      let secretValue;
      if ('SecretString' in response) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      if (!this.cachedSecrets) {
        this.cachedSecrets = {};
      }
      this.cachedSecrets[secretName] = secretValue;
      this.lastCacheTime = Date.now();

      console.log(`Retrieved secret from AWS: ${secretName}`);
      return secretValue;
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret not found in AWS Secrets Manager: ${secretName}`);
      }
      throw error;
    }
  }

  /**
   * Get secret from environment variables (fallback)
   */
  getFromEnvironment(secretName) {
    const value = process.env[secretName];
    if (!value) {
      throw new Error(`Secret not found in environment: ${secretName}`);
    }
    return value;
  }

