/**
 * SECURED VERSION OF app.js
 * This version implements recommended security best practices
 */

require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const SECRET_KEY = process.env.JWT_SECRET || 'your-super-secret-key-change-in-production';

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Set security headers
app.use(helmet());

// 2. CORS configuration with whitelist
const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
app.use(cors({
  origin: function (origin, callback) {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400 // 24 hours
}));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 attempts
  skipSuccessfulRequests: true,
  message: { error: 'Too many login attempts, please try again later.' }
});

app.use(limiter);

// 4. Body parser with size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. Request logging
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir);
}

const accessLogStream = fs.createWriteStream(
  path.join(logsDir, 'access.log'),
  { flags: 'a' }
);

app.use(morgan('combined', { stream: accessLogStream }));

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Extract Bearer token

  if (!token) {
    logSecurityEvent('AUTH_FAILED', {
      ip: req.ip,
      url: req.url,
      reason: 'No token provided'
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, SECRET_KEY, (err, user) => {
    if (err) {
      logSecurityEvent('AUTH_FAILED', {
        ip: req.ip,
        url: req.url,
        reason: 'Invalid or expired token',
        error: err.message
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }

    // Validate user object
    if (!user.id || typeof user.id !== 'string') {
      logSecurityEvent('AUTH_FAILED', {
        ip: req.ip,
        url: req.url,
        reason: 'Invalid token payload'
      });
      return res.status(403).json({ error: 'Invalid token' });
    }

    req.user = user;
    next();
  });
};

// ============================================================================
// LOGGING FUNCTIONS
// ============================================================================

const logSecurityEvent = (event, details) => {
  const logEntry = {
    timestamp: new Date().toISOString(),
    event,
    ...details
  };

  fs.appendFileSync(
    path.join(logsDir, 'security.log'),
    JSON.stringify(logEntry) + '\n'
  );
};

// ============================================================================
// PUBLIC ROUTES
// ============================================================================

// Health check endpoint (public, but monitored)
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV
    });
  } catch (error) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

// ============================================================================
// PROTECTED ROUTES
// ============================================================================

// Get users endpoint (requires authentication)
app.get('/users', authenticateToken, (req, res) => {
  try {
    // Validate query parameters
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const offset = Math.max(parseInt(req.query.offset) || 0, 0);

    // Check for non-integer values
    if (isNaN(limit) || isNaN(offset)) {
      return res.status(400).json({ error: 'Invalid pagination parameters' });
    }

    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    // Filter response based on user permissions
    const sanitizedUsers = allUsers
      .slice(offset, offset + limit)
      .map(user => {
        const response = {
          id: user.id,
          name: user.name
        };

        // Only admins can see emails and full details
        if (req.user.role === 'admin') {
          response.email = user.email;
        }

        // Never expose internal role field
        return response;
      });

    res.json({
      data: sanitizedUsers,
      pagination: {
        limit,
        offset,
        total: allUsers.length
      }
    });

    logSecurityEvent('USER_LIST_ACCESSED', {
      userId: req.user.id,
      ip: req.ip,
      limit,
      offset
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Login endpoint (for testing/demo purposes)
app.post('/login', authLimiter, (req, res) => {
  try {
    const { username, password } = req.body;

    // Validate input
    if (!username || !password) {
      return res.status(400).json({ error: 'Username and password required' });
    }

    if (typeof username !== 'string' || typeof password !== 'string') {
      return res.status(400).json({ error: 'Invalid input format' });
    }

    // Basic credential check (in production, verify against database with bcrypt)
    // This is just for demonstration
    if (username === 'admin' && password === 'admin123') {
      const token = jwt.sign(
        { id: 'admin-1', username: 'admin', role: 'admin' },
        SECRET_KEY,
        { expiresIn: '1h' }
      );

      logSecurityEvent('LOGIN_SUCCESS', {
        username,
        ip: req.ip,
        role: 'admin'
      });

      return res.json({ token });
    }

    logSecurityEvent('LOGIN_FAILED', {
      username,
      ip: req.ip,
      reason: 'Invalid credentials'
    });

    res.status(401).json({ error: 'Invalid credentials' });
  } catch (error) {
    console.error('Error in /login endpoint:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  logSecurityEvent('ROUTE_NOT_FOUND', {
    ip: req.ip,
    url: req.url,
    method: req.method
  });

  res.status(404).json({
    error: 'Not Found',
    path: req.url
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  // Log the error
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  logSecurityEvent('ERROR', {
    message: err.message,
    url: req.url,
    ip: req.ip
  });

  // Don't expose stack traces in production
  const isProduction = NODE_ENV === 'production';
  const statusCode = err.status || 500;
  const message = isProduction ? 'Internal Server Error' : err.message;

  res.status(statusCode).json({
    error: message,
    ...(isProduction ? {} : { stack: err.stack })
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

app.listen(PORT, () => {
  console.log(`[${NODE_ENV}] Server running on port ${PORT}`);
  console.log(`Time: ${new Date().toISOString()}`);
});

module.exports = app;

