// config/secrets.js
const AWS = require('aws-sdk');
const NodeCache = require('node-cache');

class SecretsManager {
  constructor() {
    this.secretsManager = new AWS.SecretsManager({ 
      region: process.env.AWS_REGION 
    });
    this.cache = new NodeCache({ 
      stdTTL: parseInt(process.env.SECRETS_TTL_SECONDS || '3600') 
    });
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached) {
      return cached;
    }

    try {
      const response = await this.secretsManager.getSecretValue({
        SecretId: secretName
      }).promise();

      const secret = JSON.parse(response.SecretString);
      this.cache.set(secretName, secret);

      return secret;
    } catch (err) {
      throw new Error(`Failed to retrieve secret: ${secretName} - ${err.message}`);
    }
  }

  // Never expose raw secrets to application code
  async getDatabaseConfig() {
    const dbSecret = await this.getSecret('prod/database/app-user');
    return {
      host: process.env.RDS_PROXY_ENDPOINT,
      port: 5432,
      database: process.env.DATABASE_NAME,
      user: dbSecret.username,
      password: dbSecret.password,
      ssl: { rejectUnauthorized: true }
    };
  }

  async getStripeConfig() {
    const stripeSecret = await this.getSecret('prod/stripe/secret-key');
    return {
      apiKey: stripeSecret.key,
      apiVersion: '2020-08-27'
    };
  }

  async getAnthropicConfig() {
    const anthropicSecret = await this.getSecret('prod/anthropic/api-key');
    return {
      apiKey: anthropicSecret.key
    };
  }
}

module.exports = new SecretsManager();
