const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

let cachedSecrets = null;

async function getSecrets() {
  // Return cached secrets (refresh every hour in production)
  if (cachedSecrets && Date.now() - cachedSecrets.timestamp < 3600000) {
    return cachedSecrets.data;
  }

  try {
    const response = await secretsManager.getSecretValue({
      SecretId: process.env.SECRETS_NAME || 'prod/myapp/secrets'
    }).promise();

    let secrets;
    if ('SecretString' in response) {
      secrets = JSON.parse(response.SecretString);
    } else {
      secrets = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    }

    cachedSecrets = {
      data: secrets,
      timestamp: Date.now()
    };

    return secrets;
  } catch (error) {
    console.error('Failed to retrieve secrets from AWS Secrets Manager:', error);

    // Fallback to .env for development only
    if (process.env.NODE_ENV !== 'production') {
