#### **Solution 3: Implement Secret Validation Module**

```javascript
// config/secrets.js
const logger = require('./logger');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.validated = false;
  }

  validate() {
    const required = {
      production: [
        'ACCESS_TOKEN_SECRET',
        'REFRESH_TOKEN_SECRET',
        'DATABASE_URL'
      ],
      staging: [
        'ACCESS_TOKEN_SECRET',
        'DATABASE_URL'
      ],
      development: []
    };

    const env = process.env.NODE_ENV || 'development';
    const requiredSecrets = required[env] || required.development;

    const missing = [];
    const invalid = [];

    for (const secret of requiredSecrets) {
      const value = process.env[secret];

      if (!value) {
        missing.push(secret);
      } else if (value.includes('your-') || value.includes('change-this')) {
        invalid.push(secret);
      }
    }

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets in ${env} environment: ${missing.join(', ')}`
      );
    }

    if (invalid.length > 0) {
      throw new Error(
        `Invalid placeholder values for secrets: ${invalid.join(', ')}`
      );
    }

    this.validated = true;
    logger.info('✓ All required secrets validated');
    return true;
  }

  get(key) {
    if (!this.validated && process.env.NODE_ENV === 'production') {
      throw new Error('Secrets not validated. Call validate() first');
    }

    const value = process.env[key];
    if (!value) {
      logger.warn(`Secret '${key}' not found`);
    }
    return value;
  }
}

module.exports = new SecretsManager();
```

