## Secure Implementation Example

See `app-secure.js` for a complete secure implementation with all recommendations applied.

// Secure Implementation of app.js
// This example demonstrates all security best practices

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const winston = require('winston');
const morgan = require('morgan');

const app = express();

// ============ CONFIGURATION ============
const SECRET_KEY = process.env.JWT_SECRET;
const NODE_ENV = process.env.NODE_ENV || 'development';
const PORT = process.env.PORT || 3000;
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];

// Validate required configuration
if (!SECRET_KEY) {
  throw new Error('JWT_SECRET environment variable is required');
}

// ============ LOGGING SETUP ============
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'secure-app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    ...(NODE_ENV === 'development' ? [
      new winston.transports.Console({
        format: winston.format.simple()
      })
    ] : [])
  ],
});

// ============ MIDDLEWARE: SECURITY HEADERS ============
app.use(helmet());

// Additional custom headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

// ============ MIDDLEWARE: HTTPS REDIRECT ============
if (NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// ============ MIDDLEWARE: CORS ============
const corsOptions = {
  origin: ALLOWED_ORIGINS,
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};

app.use(cors(corsOptions));

// ============ MIDDLEWARE: BODY PARSER ============
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============ MIDDLEWARE: REQUEST LOGGING ============
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim())
  }
}));

// ============ MIDDLEWARE: RATE LIMITING ============
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => NODE_ENV === 'development', // Skip rate limiting in development
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many requests, please try again later.',
  skipSuccessfulRequests: true, // Don't count successful requests
  keyGenerator: (req) => req.user?.id || req.ip, // Use user ID if authenticated
});

app.use(generalLimiter);

// ============ UTILITY FUNCTIONS ============

/**
 * Log security events
 */
const logSecurityEvent = (eventType, details) => {
  logger.warn({
    type: eventType,
    timestamp: new Date().toISOString(),
    ...details
  });
};

/**
 * JWT Authentication Middleware
 */
const authenticateToken = (req, res, next) => {
  try {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

    if (!token) {
      logSecurityEvent('AUTH_FAILED', {
        reason: 'No token provided',
        ip: req.ip,
        path: req.path,
        method: req.method
      });
      return res.status(401).json({ error: 'Access token required' });
    }

    jwt.verify(token, SECRET_KEY, (err, user) => {
      if (err) {
        logSecurityEvent('AUTH_FAILED', {
          reason: err.message,
          ip: req.ip,
          path: req.path,
          method: req.method
        });
        return res.status(403).json({ error: 'Invalid or expired token' });
      }

      req.user = user;
      logger.info(`User authenticated: ${user.id} (${user.role})`);
      next();
    });
  } catch (error) {
    logSecurityEvent('AUTH_ERROR', {
      error: error.message,
      ip: req.ip
    });
    res.status(500).json({ error: 'Authentication error' });
  }
};

/**
 * Authorization Middleware - Check user role
 */
const authorize = (requiredRole) => {
  return (req, res, next) => {
    if (req.user.role !== requiredRole) {
      logSecurityEvent('AUTHORIZATION_FAILED', {
        userId: req.user.id,
        requiredRole,
        userRole: req.user.role,
        path: req.path,
        method: req.method
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

/**
 * Filter sensitive user data based on permissions
 */
const filterUserData = (users, requestingUser) => {
  return users.map(user => {
    const filtered = {
      id: user.id,
      name: user.name
    };

    // Only include email if requester is admin or viewing their own profile
    if (requestingUser.role === 'admin' || requestingUser.id === user.id) {
      filtered.email = user.email;
    }

    return filtered;
  });
};

// ============ ROUTES ============

/**
 * Public health check endpoint
 * Rate limiting applies but no authentication required
 */
app.get('/health', (req, res) => {
  logger.debug('Health check requested');
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

/**
 * Protected users list endpoint
 * Requires authentication and admin role
 */
app.get('/users', 
  authenticateToken,
  authorize('admin'),
  strictLimiter, // Apply stricter rate limit to sensitive endpoints
  (req, res) => {
    try {
      const mockUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const filteredUsers = filterUserData(mockUsers, req.user);
      logger.info(`User list retrieved by admin: ${req.user.id}`);

      res.json(filteredUsers);
    } catch (error) {
      logger.error('Error retrieving users', { error: error.message });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

/**
 * Protected endpoint to get current user data
 * Less sensitive than listing all users
 */
app.get('/users/me',
  authenticateToken,
  (req, res) => {
    try {
      // Return only the authenticated user's data
      res.json({
        id: req.user.id,
        name: req.user.name,
        email: req.user.email,
        role: req.user.role
      });
    } catch (error) {
      logger.error('Error retrieving current user', { error: error.message });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

/**
 * Mock login endpoint for demonstration
 * In production, validate against a database
 */
app.post('/login',
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 5, // Strict limit on login attempts
    message: 'Too many login attempts, please try again later.',
    skipSuccessfulRequests: false
  }),
  (req, res) => {
    try {
      const { username, password } = req.body;

      // Validate input
      if (!username || !password) {
        logSecurityEvent('LOGIN_FAILED', {
          reason: 'Missing credentials',
          ip: req.ip
        });
        return res.status(400).json({ error: 'Username and password required' });
      }

      // In production, verify against database with bcrypt
      // This is just for demonstration
      if (username === 'admin' && password === process.env.ADMIN_PASSWORD) {
        const token = jwt.sign(
          { id: 1, name: 'Admin', email: 'admin@example.com', role: 'admin' },
          SECRET_KEY,
          { expiresIn: '1h' }
        );

        logger.info(`Successful login: ${username}`);
        res.json({ token, expiresIn: '1h' });
      } else {
        logSecurityEvent('LOGIN_FAILED', {
          username,
          ip: req.ip,
          reason: 'Invalid credentials'
        });
        return res.status(401).json({ error: 'Invalid credentials' });
      }
    } catch (error) {
      logger.error('Login error', { error: error.message });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// ============ ERROR HANDLING ============

/**
 * 404 handler
 */
app.use((req, res) => {
  logger.warn('Route not found', {
    path: req.path,
    method: req.method,
    ip: req.ip
  });
  res.status(404).json({ error: 'Not found' });
});

/**
 * Global error handler (must be last middleware)
 */
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    message: err.message,
    stack: NODE_ENV === 'development' ? err.stack : undefined,
    ip: req.ip,
    path: req.path,
    method: req.method
  });

  const isDevelopment = NODE_ENV === 'development';
  const statusCode = err.status || 500;

  res.status(statusCode).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============ SERVER STARTUP ============
const server = app.listen(PORT, () => {
  logger.info(`Secure server running on port ${PORT} in ${NODE_ENV} mode`);
});

// ============ GRACEFUL SHUTDOWN ============
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

