# VULNERABLE CODE PATTERNS - What NOT to Do

## 1. HARDCODED SECRETS

### ❌ VULNERABLE
const SECRET = 'my-secret-key-12345';
const DB_PASSWORD = 'admin123';
const API_KEY = 'sk_live_abcdef123456';

### ✅ SECURE
const SECRET = process.env.JWT_SECRET;
const DB_PASSWORD = process.env.DB_PASSWORD;
const API_KEY = process.env.API_KEY;

if (!SECRET || !DB_PASSWORD) {
  throw new Error('Required environment variables are not set');
}

---

## 2. NO AUTHENTICATION

### ❌ VULNERABLE
app.get('/admin/users', (req, res) => {
  res.json(allUsers);
});

app.delete('/users/:id', (req, res) => {
  deleteUser(req.params.id);
  res.json({ success: true });
});

### ✅ SECURE
const authenticateToken = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

app.get('/admin/users', authenticateToken, authorize('admin'), (req, res) => {
  res.json(allUsers);
});

---

## 3. NO INPUT VALIDATION (SQL INJECTION)

### ❌ VULNERABLE
app.get('/search', (req, res) => {
  const query = `SELECT * FROM users WHERE name = '${req.query.name}'`;
  db.query(query, (err, results) => {
    res.json(results);
  });
});

// Attack: /search?name='; DROP TABLE users; --

### ✅ SECURE
app.get('/search', (req, res) => {
  const name = req.query.name;
  if (!name || typeof name !== 'string' || name.length > 100) {
    return res.status(400).json({ error: 'Invalid name' });
  }

  // Use parameterized queries
  const query = 'SELECT * FROM users WHERE name = $1';
  db.query(query, [name], (err, results) => {
    res.json(results);
  });
});

---

## 4. NO RATE LIMITING (BRUTE FORCE)

### ❌ VULNERABLE
app.post('/login', (req, res) => {
  // No rate limiting - attacker can try infinite passwords
  const user = authenticate(req.body.username, req.body.password);
  if (user) {
    res.json({ token: generateToken(user) });
  } else {
    res.status(401).json({ error: 'Invalid credentials' });
  }
});

### ✅ SECURE
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per 15 minutes
  message: 'Too many login attempts',
  skipSuccessfulRequests: false
});

app.post('/login', loginLimiter, (req, res) => {
  const user = authenticate(req.body.username, req.body.password);
  if (user) {
    res.json({ token: generateToken(user) });
  } else {
    res.status(401).json({ error: 'Invalid credentials' });
  }
});

---

## 5. NO HTTPS (UNENCRYPTED TRANSMISSION)

### ❌ VULNERABLE
// Running only on HTTP
app.listen(3000);

// User credentials, tokens, data all transmitted in plaintext

### ✅ SECURE
// Redirect HTTP to HTTPS
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && 
      req.header('x-forwarded-proto') !== 'https') {
    res.redirect(`https://${req.header('host')}${req.url}`);
  } else {
    next();
  }
});

// Or use HTTPS directly
const https = require('https');
const fs = require('fs');
const options = {
  key: fs.readFileSync('key.pem'),
  cert: fs.readFileSync('cert.pem')
};
https.createServer(options, app).listen(3000);

---

## 6. EXPOSED SENSITIVE DATA IN RESPONSES

### ❌ VULNERABLE
app.get('/users/:id', (req, res) => {
  const user = findUser(req.params.id);
  res.json(user); // Exposes password_hash, email, personal info
});

app.get('/admin/logs', (req, res) => {
  res.json(allLogs); // May contain sensitive data
});

### ✅ SECURE
app.get('/users/:id', authenticateToken, (req, res) => {
  // Check authorization
  if (req.user.id !== parseInt(req.params.id) && req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Not authorized' });
  }

  const user = findUser(req.params.id);
  const { password_hash, ...safeUser } = user;

  res.json(safeUser);
});

---

## 7. MISSING SECURITY HEADERS

### ❌ VULNERABLE
// No security headers configured
app.get('/', (req, res) => {
  res.send('<html>Welcome</html>');
});

// Vulnerable to: Clickjacking, XSS, MIME-sniffing

### ✅ SECURE
const helmet = require('helmet');
app.use(helmet());

// Now includes:
// - X-Content-Type-Options: nosniff
// - X-Frame-Options: DENY
// - X-XSS-Protection: 1; mode=block
// - Strict-Transport-Security
// - Content-Security-Policy

---

## 8. INSECURE DESERIALIZATION

### ❌ VULNERABLE
app.post('/data', (req, res) => {
  const data = JSON.parse(req.body);
  const obj = eval(data); // NEVER use eval
  res.json(obj);
});

// Attacker can execute arbitrary code

### ✅ SECURE
app.post('/data', (req, res) => {
  const data = req.body; // Already parsed by express.json()

  // Validate structure
  if (!data.name || typeof data.name !== 'string') {
    return res.status(400).json({ error: 'Invalid data' });
  }

  res.json(data);
});

---

## 9. IMPROPER ERROR HANDLING (INFORMATION DISCLOSURE)

### ❌ VULNERABLE
app.get('/data', (req, res) => {
  try {
    const data = fetchData();
    res.json(data);
  } catch (err) {
    // Exposes stack trace to client
    res.status(500).json({ error: err.toString(), stack: err.stack });
  }
});

### ✅ SECURE
app.get('/data', (req, res) => {
  try {
    const data = fetchData();
    res.json(data);
  } catch (err) {
    // Log error internally
    logger.error('Error fetching data', { error: err.message, stack: err.stack });

    // Return generic message to client
    const message = process.env.NODE_ENV === 'development' 
      ? err.message 
      : 'An error occurred';
    res.status(500).json({ error: message });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error('Unhandled error', { error: err.message, stack: err.stack });
  res.status(500).json({ 
    error: process.env.NODE_ENV === 'development' ? err.message : 'Internal server error' 
  });
});

---

## 10. NO CORS CONFIGURATION

### ❌ VULNERABLE
// Default CORS behavior - allows all origins
app.use(cors()); // This is actually restrictive by default, but explicit is better

// Or worse:
app.use(cors({ origin: '*' })); // Allows ANY origin

### ✅ SECURE
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['https://yourdomain.com'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};

app.use(cors(corsOptions));

---

## 11. NO LOGGING/MONITORING

### ❌ VULNERABLE
app.post('/login', (req, res) => {
  const user = authenticate(req.body.username, req.body.password);
  // Failed login not logged - security breach undetected
  if (user) {
    res.json({ token: generateToken(user) });
  } else {
    res.status(401).json({ error: 'Invalid' });
  }
});

### ✅ SECURE
app.post('/login', (req, res) => {
  try {
    const user = authenticate(req.body.username, req.body.password);
    if (user) {
      logger.info(`Successful login: ${user.id}`, { ip: req.ip });
      res.json({ token: generateToken(user) });
    } else {
      logger.warn(`Failed login attempt`, { 
        username: req.body.username, 
        ip: req.ip,
        timestamp: new Date()
      });
      res.status(401).json({ error: 'Invalid' });
    }
  } catch (err) {
    logger.error(`Login error`, { error: err.message, ip: req.ip });
    res.status(500).json({ error: 'Internal error' });
  }
});

---

## 12. WEAK PASSWORD STORAGE

### ❌ VULNERABLE
app.post('/register', (req, res) => {
  // Storing plaintext password - NEVER do this
  db.query('INSERT INTO users VALUES ($1, $2)', [req.body.username, req.body.password]);
  res.json({ success: true });
});

// Even worse:
// INSERT INTO users VALUES (?, ?); // With md5() - MD5 is broken

### ✅ SECURE
const bcrypt = require('bcrypt');

app.post('/register', async (req, res) => {
  try {
    const hashedPassword = await bcrypt.hash(req.body.password, 10);
    db.query('INSERT INTO users VALUES ($1, $2)', 
      [req.body.username, hashedPassword]);
    res.json({ success: true });
  } catch (err) {
    logger.error('Registration error', { error: err.message });
    res.status(500).json({ error: 'Registration failed' });
  }
});

// When validating:
const user = await db.query('SELECT * FROM users WHERE username = $1', [username]);
const validPassword = await bcrypt.compare(password, user.password_hash);

---

## 13. INSECURE DESERIALIZATION (COOKIES)

### ❌ VULNERABLE
app.get('/', (req, res) => {
  const userPrefs = JSON.parse(req.cookies.prefs);
  // Attacker can craft malicious cookie
  res.json(userPrefs);
});

### ✅ SECURE
const cookieParser = require('cookie-parser');

app.use(cookieParser(process.env.COOKIE_SECRET));

app.get('/', (req, res) => {
  const userPrefs = req.signedCookies.prefs;
  if (!userPrefs) {
    return res.status(401).json({ error: 'No valid session' });
  }
  res.json(userPrefs);
});

---

## 14. PATH TRAVERSAL

### ❌ VULNERABLE
app.get('/download', (req, res) => {
  const file = req.query.file;
  res.download(`/public/${file}`);
});

// Attack: /download?file=../../etc/passwd

### ✅ SECURE
const path = require('path');

app.get('/download', (req, res) => {
  const file = req.query.file;

  // Validate filename
  if (!file || file.includes('..') || file.includes('/')) {
    return res.status(400).json({ error: 'Invalid filename' });
  }

  // Ensure file is within allowed directory
  const fullPath = path.join(__dirname, 'public', file);
  const allowed = path.resolve(fullPath).startsWith(path.resolve(__dirname, 'public'));

  if (!allowed) {
    return res.status(403).json({ error: 'Access denied' });
  }

  res.download(fullPath);
});

---

## 15. NO CSRF PROTECTION (for state-changing requests)

### ❌ VULNERABLE
app.post('/transfer', (req, res) => {
  // No CSRF token validation
  transfer(req.body.amount, req.body.to);
  res.json({ success: true });
});

// Attacker can trick user into clicking link that performs action

### ✅ SECURE
const csrf = require('csurf');
const session = require('express-session');

app.use(session({ secret: process.env.SESSION_SECRET }));
app.use(csrf());

// Provide token
app.get('/transfer', (req, res) => {
  res.render('transfer', { csrfToken: req.csrfToken() });
});

// Validate token
app.post('/transfer', (req, res) => {
  // CSRF token automatically validated by middleware
  transfer(req.body.amount, req.body.to);
  res.json({ success: true });
});

---

## Summary of Common Mistakes

1. ❌ Hardcoding secrets in code
2. ❌ No authentication on protected endpoints
3. ❌ SQL injection via string concatenation
4. ❌ No rate limiting
5. ❌ Running on HTTP instead of HTTPS
6. ❌ Exposing sensitive data in responses
7. ❌ Missing security headers
8. ❌ Using eval() or similar
9. ❌ Exposing error stack traces to clients
10. ❌ No CORS configuration
11. ❌ Not logging security events
12. ❌ Storing passwords in plaintext
13. ❌ Insecure deserialization
14. ❌ Path traversal vulnerabilities
15. ❌ No CSRF protection

## Pattern Recognition

When reviewing code, look for:
- 🔴 Direct SQL queries with string concatenation
- 🔴 Missing authentication checks on sensitive operations
- 🔴 Secrets in code (API keys, passwords, tokens)
- 🟠 eval(), Function(), or similar constructs
- 🟠 No input validation
- 🟠 Exposed error information
- 🟡 No rate limiting on sensitive endpoints
- 🟡 Missing security headers

