**2. config/secrets-aws.js**
```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
    this.cache = {};
    this.cacheExpiry = 3600000; // 1 hour cache
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.cache[secretName] && Date.now() - this.cache[secretName].loadTime < this.cacheExpiry) {
      return this.cache[secretName].value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secretValue;
      if ('SecretString' in response) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache[secretName] = {
        value: secretValue,
        loadTime: Date.now()
      };

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
  }

  // Batch get multiple secrets
  async getSecrets(secretNames) {
    const results = {};
    const promises = secretNames.map(name => 
      this.getSecret(name)
        .then(value => { results[name] = value; })
        .catch(err => { 
          console.error(`Failed to load ${name}`);
          throw err;
        })
    );

    await Promise.all(promises);
    return results;
  }
}

module.exports = new SecretsManager();
```

