  if (!secrets) {
    try {
      secrets = await secretsManager.getSecrets([
        'prod/jwt-secret',
        'prod/database-url',
        'prod/api-keys'
      ]);
    } catch (error) {
      return res.status(500).json({ error: 'Failed to load configuration' });
    }
  }
