const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

/**
 * AWS Secrets Manager Client
 * 
 * Securely retrieves secrets from AWS Secrets Manager
 * Includes caching to reduce API calls
 * Handles secret rotation
 */

class AWSSecretsManager {
  constructor(options = {}) {
    this.client = new SecretsManagerClient({
      region: options.region || process.env.AWS_REGION || 'us-east-1'
    });

    this.cache = {};
    this.cacheExpiry = options.cacheExpiry || 3600000; // 1 hour default
    this.logger = options.logger || console;
  }

  /**
   * Retrieve a single secret
   * @param {string} secretName - Name/ARN of secret
   * @returns {Promise<object>} Secret value
   */
  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache[secretName];
    if (cached && Date.now() - cached.loadTime < this.cacheExpiry) {
      this.logger.debug(`📦 Cache hit for secret: ${secretName}`);
      return cached.value;
    }

    try {
      this.logger.debug(`🔑 Fetching secret from AWS Secrets Manager: ${secretName}`);

      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secretValue;

      if ('SecretString' in response) {
        // String secret - try to parse as JSON
        try {
          secretValue = JSON.parse(response.SecretString);
        } catch {
          // If not JSON, treat as raw string
          secretValue = response.SecretString;
        }
      } else if ('SecretBinary' in response) {
        // Binary secret
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      } else {
        throw new Error('Secret has no SecretString or SecretBinary value');
      }

      // Cache the secret
      this.cache[secretName] = {
        value: secretValue,
        loadTime: Date.now()
      };

      this.logger.info(`✅ Successfully loaded secret: ${secretName}`);
      return secretValue;

    } catch (error) {
      this.logger.error(`❌ Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error(`Failed to load secret ${secretName}: ${error.message}`);
    }
  }

  /**
   * Retrieve multiple secrets in parallel
   * @param {string[]} secretNames - Array of secret names
   * @returns {Promise<object>} Object with secret names as keys
   */
  async getSecrets(secretNames) {
    const results = {};
    const errors = [];

    const promises = secretNames.map(name =>
      this.getSecret(name)
        .then(value => {
          results[name] = value;
        })
        .catch(err => {
          errors.push({ name, error: err.message });
        })
    );

    await Promise.all(promises);

    if (errors.length > 0) {
      this.logger.error(`⚠️  Failed to load ${errors.length} secrets:`, errors);
      throw new Error(`Failed to load secrets: ${errors.map(e => e.name).join(', ')}`);
    }

    return results;
  }

  /**
   * Clear cache for a secret (useful for rotation)
   * @param {string} secretName - Name of secret to invalidate
   */
  clearCache(secretName) {
    if (secretName) {
      delete this.cache[secretName];
      this.logger.debug(`🗑️  Cache cleared for: ${secretName}`);
    } else {
      this.cache = {};
      this.logger.debug(`🗑️  All cache cleared`);
    }
  }

  /**
   * Check if secret exists and is accessible
   * @param {string} secretName - Name of secret
   * @returns {Promise<boolean>} True if accessible
   */
  async isAccessible(secretName) {
    try {
      await this.getSecret(secretName);
      return true;
    } catch {
      return false;
    }
  }
}

module.exports = AWSSecretsManager;

