// SECURE VERSION: Enhanced application with security best practices
require('dotenv').config();
const express = require('express');
const jwt = require('jsonwebtoken');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, body, validationResult } = require('express-validator');
const winston = require('winston');
const https = require('https');
const fs = require('fs');

const app = express();

// ============================================
// 1. LOGGER CONFIGURATION
// ============================================
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error' 
    }),
    new winston.transports.File({ 
      filename: 'logs/combined.log' 
    }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================
// 2. ENVIRONMENT VALIDATION
// ============================================
const requiredEnvVars = ['JWT_SECRET', 'NODE_ENV'];
requiredEnvVars.forEach((envVar) => {
  if (!process.env[envVar]) {
    throw new Error(`Missing required environment variable: ${envVar}`);
  }
});

// ============================================
// 3. SECURITY MIDDLEWARE
// ============================================

// Helmet - Sets various HTTP headers
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  },
}));

// CORS - Configure allowed origins
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'https://yourdomain.com').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};
app.use(cors(corsOptions));

// Request size limits - Prevent buffer overflow
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting - Prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});
app.use(limiter);

// Stricter rate limiting for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true, // Only count failed attempts
});

// Request logging middleware
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    url: req.url,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });
  next();
});

// ============================================
// 4. AUTHENTICATION MIDDLEWARE
// ============================================
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn(`Unauthorized access attempt from IP: ${req.ip}`);
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn(`Invalid token attempt from IP: ${req.ip}`);
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// ============================================
// 5. DATA SANITIZATION
// ============================================
const sanitizeUser = (user) => ({
  id: user.id,
  name: user.name,
  // Explicitly exclude sensitive fields
  // Never return: password, passwordHash, email, privateData
});

// ============================================
// 6. ROUTES
// ============================================

// Health check (minimal data exposure)
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: '1.0.0'
    });
  } catch (error) {
    logger.error('Error in health check:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Login endpoint to obtain JWT token
app.post('/login', authLimiter, body('username').isLength({ min: 1 }).trim().escape(), body('password').isLength({ min: 1 }), (req, res) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { username, password } = req.body;

    // TODO: Validate against database with bcrypt comparison
    // For demo purposes only:
    if (username === 'admin' && password === 'demo-password') {
      const user = { id: 1, username: 'admin' };
      const token = jwt.sign(user, process.env.JWT_SECRET, { 
        expiresIn: '1h',
        algorithm: 'HS256'
      });
      logger.info(`Successful login for user: ${username}`);
      return res.json({ token });
    }

    logger.warn(`Failed login attempt for user: ${username}`);
    res.status(401).json({ error: 'Invalid credentials' });
  } catch (error) {
    logger.error('Error in login endpoint:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Protected users endpoint with input validation
app.get('/users',
  authenticateToken,
  query('id').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      // Mock user data - in production, fetch from secure database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filters
      let filtered = users;
      if (req.query.id) {
        filtered = users.filter(u => u.id === req.query.id);
      }

      // Sanitize response - remove sensitive data
      const sanitized = filtered.map(sanitizeUser);

      // Apply limit
      const limit = req.query.limit || 50;
      res.json(sanitized.slice(0, limit));
    } catch (error) {
      logger.error('Error fetching users:', error);
      // Never expose internal error details
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// ============================================
// 7. ERROR HANDLING
// ============================================

// 404 handler
app.use((req, res) => {
  logger.warn(`404 Not Found: ${req.method} ${req.url}`);
  res.status(404).json({ error: 'Not found' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  logger.error(`Unhandled error: ${err.message}`, err);
  res.status(500).json({ error: 'Internal server error' });
});

// ============================================
// 8. SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

if (process.env.NODE_ENV === 'production' && process.env.CERT_PATH && process.env.KEY_PATH) {
  // HTTPS in production
  const options = {
    key: fs.readFileSync(process.env.KEY_PATH),
    cert: fs.readFileSync(process.env.CERT_PATH),
  };
  https.createServer(options, app).listen(PORT, () => {
    logger.info(`Secure server running on port ${PORT}`);
  });
} else {
  // HTTP for development
  app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT} (development mode)`);
  });
}

module.exports = app;
