**Implementation:**

```javascript
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

async function getSecret(secretName) {
  try {
    const data = await secretsManager.getSecretValue({ 
      SecretId: secretName 
    }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    } else {
      return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }
  } catch (error) {
    console.error(`Failed to retrieve secret ${secretName}:`, error);
    throw error;
  }
}

// Usage in app.js
const express = require('express');
const app = express();

let dbConfig, apiKeys;

// Load secrets on startup
(async () => {
  try {
    dbConfig = await getSecret('prod/database');
    apiKeys = await getSecret('prod/api-keys');

    app.listen(3000, () => {
      console.log('Server started with secrets loaded from AWS Secrets Manager');
    });
  } catch (error) {
    console.error('Fatal: Could not load secrets', error);
    process.exit(1);
  }
})();

app.get('/users', (req, res) => {
  // Use decrypted dbConfig and apiKeys
  res.json([...]);
});

module.exports = app;
```

