require('dotenv').config({ path: '.env.local' }); // Only for LOCAL development

const express = require('express');
const app = express();

// Determine environment
const NODE_ENV = process.env.NODE_ENV || 'development';
const isProduction = NODE_ENV === 'production';

// Secret loading strategy
let secrets = {};

if (isProduction) {
  // In production: use secrets manager
  if (process.env.USE_AWS_SECRETS === 'true') {
    secrets = require('./config/aws-secrets'); // Async loaded elsewhere
  } else if (process.env.USE_VAULT === 'true') {
    secrets = require('./config/vault-client'); // Async loaded elsewhere
  } else {
    throw new Error('Production requires either AWS Secrets Manager or Vault');
  }
} else {
  // In development: use .env.local (NOT committed to git)
  secrets = {
    DATABASE_URL: process.env.DATABASE_URL,
    AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
    STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
    // Don't default these - require explicit configuration
  };
}

// Validate required secrets are present
const requiredSecrets = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'STRIPE_SECRET_KEY'
];

for (const secret of requiredSecrets) {
  if (!secrets[secret]) {
    throw new Error(`Missing required secret: ${secret}`);
  }
}

app.get('/health', (req, res) => {
