require('dotenv').config();
const express = require('express');
const helmet = require('helmet');

// ============ SECRETS VALIDATION ============

const requiredSecrets = [
  'DATABASE_URL',
  'JWT_SECRET',
  'NODE_ENV'
];

const missingSecrets = requiredSecrets.filter(s => !process.env[s]);

if (missingSecrets.length > 0) {
  console.error('❌ Missing required secrets:', missingSecrets.join(', '));
  process.exit(1);
}

// ============ SENSITIVE LOGGING PREVENTION ============

// Mask sensitive data in logs
const maskSecrets = (obj) => {
  const masked = JSON.parse(JSON.stringify(obj));
  const sensitiveKeys = [
    'password', 'secret', 'token', 'key', 'api_key',
    'access_key', 'secret_key', 'credentials'
  ];

  const mask = (item) => {
    if (typeof item === 'object' && item !== null) {
      for (const key in item) {
        if (sensitiveKeys.some(k => key.toLowerCase().includes(k))) {
          item[key] = '[REDACTED]';
        } else if (typeof item[key] === 'object') {
          mask(item[key]);
        }
      }
    }
  };

  mask(masked);
  return masked;
};

// ============ SECRETS MANAGER ============

class SecureSecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheExpiry = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  validateSecretFormat(name, value) {
    // Validate secret format to catch accidental misconfigurations
    const validations = {
      JWT_SECRET: (v) => v.length >= 32,
      DATABASE_URL: (v) => v.startsWith('postgres://') || v.startsWith('postgresql://'),
      AWS_ACCESS_KEY_ID: (v) => v.startsWith('AKIA'),
      STRIPE_SECRET_KEY: (v) => v.startsWith('sk_'),
    };

    if (validations[name] && !validations[name](value)) {
      console.error(`⚠️ WARNING: ${name} has unexpected format`);
      return false;
    }
    return true;
  }

  getSecret(name) {
    // Check cache first
    const cached = this.cache.get(name);
    if (cached && this.cacheExpiry.get(name) > Date.now()) {
      return cached;
    }

    const value = process.env[name];

    if (!value) {
      throw new Error(`Secret not found: ${name}`);
    }

    // Validate format
    if (!this.validateSecretFormat(name, value)) {
      console.warn(`Proceeding with ${name} despite format warning`);
    }

    // Cache the value
    this.cache.set(name, value);
    this.cacheExpiry.set(name, Date.now() + this.cacheTTL);

    // Audit access
    console.log(`[AUDIT] Secret accessed: ${name}`);

    return value;
  }

  clearCache() {
    this.cache.clear();
    this.cacheExpiry.clear();
  }
}

const secrets = new SecureSecretsManager();

// ============ APPLICATION ============

const app = express();

