/**
 * SECURE SECRETS MANAGEMENT IMPLEMENTATION
 * 
 * This file demonstrates how to properly load and manage secrets
 * without exposing them to version control or logs
 */

// ============================================================================
// APPROACH 1: AWS Secrets Manager (Recommended for AWS deployments)
// ============================================================================

class AWSSecretsManager {
  constructor() {
    this.AWS = require('aws-sdk');
    this.secretsClient = new this.AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheExpiry = new Map();
    this.CACHE_TTL = 3600000; // 1 hour in milliseconds
  }

  /**
   * Retrieve secret from AWS Secrets Manager with caching
   * @param {string} secretName - The name/ARN of the secret
   * @returns {Promise<Object>} - The secret value
   */
  async getSecret(secretName) {
    const now = Date.now();

    // Check if secret is cached and not expired
    if (this.cache.has(secretName)) {
      const expiry = this.cacheExpiry.get(secretName);
      if (expiry > now) {
        console.log(`[CACHE HIT] Secret retrieved from cache: ${secretName}`);
        return this.cache.get(secretName);
      }
      this.cache.delete(secretName);
      this.cacheExpiry.delete(secretName);
    }

    try {
      console.log(`[FETCHING] Retrieving secret from AWS Secrets Manager: ${secretName}`);

      const data = await this.secretsClient
        .getSecretValue({ SecretId: secretName })
        .promise();

      let secret;

      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else if ('SecretBinary' in data) {
        secret = Buffer.from(data.SecretBinary, 'base64');
      }

      // Cache the secret
      this.cache.set(secretName, secret);
      this.cacheExpiry.set(secretName, now + this.CACHE_TTL);

      console.log(`[SUCCESS] Secret cached for ${this.CACHE_TTL / 1000}s: ${secretName}`);
      return secret;

    } catch (error) {
      console.error(`[ERROR] Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error(`Unable to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Get multiple secrets efficiently
   */
  async getSecrets(...secretNames) {
    const secrets = {};
    const results = await Promise.all(
      secretNames.map(name => 
        this.getSecret(name)
          .then(secret => ({ name, secret, error: null }))
          .catch(error => ({ name, secret: null, error }))
      )
    );

    for (const { name, secret, error } of results) {
      if (error) {
        throw new Error(`Failed to load secret ${name}: ${error.message}`);
      }
      secrets[name] = secret;
    }

    return secrets;
  }
}

// ============================================================================
// APPROACH 2: HashiCorp Vault (Multi-cloud solution)
// ============================================================================

class VaultSecretsManager {
  constructor() {
    this.vault = require('node-vault')({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN,
      namespace: process.env.VAULT_NAMESPACE || 'admin'
    });
  }

  async getSecret(path) {
    try {
      console.log(`[VAULT] Reading secret from path: ${path}`);
      const result = await this.vault.read(path);
      return result.data.data;
    } catch (error) {
      console.error(`[ERROR] Vault error for path ${path}:`, error.message);
      throw new Error(`Unable to retrieve secret from Vault: ${path}`);
    }
  }

  /**
   * Get secret from dynamic database credentials
   */
  async getDatabaseCredentials(role) {
    try {
      const creds = await this.vault.read(`database/creds/${role}`);
      return {
        username: creds.data.username,
        password: creds.data.password,
        ttl: creds.lease_duration
      };
    } catch (error) {
      console.error(`[ERROR] Failed to get DB credentials for role ${role}:`, error.message);
      throw error;
    }
  }
}

// ============================================================================
// APPROACH 3: Environment Variables (For CI/CD) + .env.local (Development)
// ============================================================================

class ConfigManager {
  constructor() {
    const env = process.env.NODE_ENV || 'development';

    // ONLY load .env.local in development, never in production
    if (env === 'development') {
      require('dotenv').config({
        path: '.env.local',
        override: false // Don't override existing env vars
      });
    }

    // Validate required secrets are present
    this.validateRequiredSecrets();
  }

  /**
   * Get a secret with validation
   */
  getSecret(key, defaultValue = null) {
    const value = process.env[key];

    if (!value) {
      if (defaultValue === null) {
        throw new Error(`Required secret not found: ${key}`);
      }
      return defaultValue;
    }

    return value;
  }

  /**
   * Validate that all required secrets are present
   */
  validateRequiredSecrets() {
    const required = [
      'DATABASE_URL',
      'JWT_SECRET',
      'STRIPE_SECRET_KEY',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY'
    ];

    const missing = required.filter(key => !process.env[key]);

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets: ${missing.join(', ')}\n` +
        `For development, add them to .env.local (not committed to git)`
      );
    }
  }

  /**
   * Get all configuration as object (filtered secrets)
   */
  getConfig() {
    return {
      database: {
        url: this.getSecret('DATABASE_URL')
      },
      jwt: {
        secret: this.getSecret('JWT_SECRET'),
        expiresIn: this.getSecret('JWT_EXPIRES_IN', '24h')
      },
      stripe: {
        secretKey: this.getSecret('STRIPE_SECRET_KEY'),
        webhookSecret: this.getSecret('STRIPE_WEBHOOK_SECRET', null)
      },
      aws: {
        accessKeyId: this.getSecret('AWS_ACCESS_KEY_ID'),
        secretAccessKey: this.getSecret('AWS_SECRET_ACCESS_KEY'),
        region: this.getSecret('AWS_REGION', 'us-east-1')
      }
    };
  }
}

// ============================================================================
// SECURE INITIALIZATION FOR APP.JS
// ============================================================================

class SecureAppInitializer {
  constructor() {
    this.env = process.env.NODE_ENV || 'development';
  }

  /**
   * Initialize secrets manager based on environment
   */
  async initializeSecretsManager() {
    if (this.env === 'production') {
      // Production: Use AWS Secrets Manager
      return new AWSSecretsManager();
    } else if (this.env === 'staging') {
      // Staging: Use Vault
      return new VaultSecretsManager();
    } else {
      // Development: Use environment variables
      return new ConfigManager();
    }
  }

  /**
   * Load all required secrets at startup
   */
  async loadSecrets() {
    try {
      console.log(`[INIT] Loading secrets for environment: ${this.env}`);

      const secretsManager = await this.initializeSecretsManager();

      if (this.env === 'production') {
        // Production: Fetch from AWS
        const secrets = await secretsManager.getSecrets(
          'prod/database',
          'prod/jwt',
          'prod/stripe',
          'prod/aws'
        );
        return secrets;
      } else if (this.env === 'staging') {
        // Staging: Fetch from Vault
        const dbCreds = await secretsManager.getDatabaseCredentials('app-role');
        const jwtSecret = await secretsManager.getSecret('secret/data/staging/jwt');
        return { database: dbCreds, jwt: jwtSecret };
      } else {
        // Development: Use config manager
        return secretsManager.getConfig();
      }
    } catch (error) {
      console.error('[CRITICAL] Failed to load secrets at startup:', error.message);
      process.exit(1);
    }
  }
}

// ============================================================================
// USAGE IN APP.JS
// ============================================================================

module.exports = {
  AWSSecretsManager,
  VaultSecretsManager,
  ConfigManager,
  SecureAppInitializer
};

/*
 * Example usage in app.js:
 * 
 * const { SecureAppInitializer } = require('./secrets-manager');
 * 
 * const initializer = new SecureAppInitializer();
 * const secrets = await initializer.loadSecrets();
 * 
 * const express = require('express');
 * const app = express();
 * 
 * // Now use secrets safely without exposing them
 * const db = require('pg').Client({
 *   connectionString: secrets.database.url
 * });
 * 
 * app.get('/api/data', authenticateToken, (req, res) => {
 *   // Secrets are in memory, never logged or exposed
 *   res.json({ /* data */ });
 * });
 * 
 * // DO NOT do this:
 * // console.log(secrets); // ✗ NEVER log secrets
 * // res.json(secrets);    // ✗ NEVER send to client
 * // process.env           // ✗ NEVER expose environment
 */
EOF
