```javascript
const express = require('express');
const AWS = require('aws-sdk');
require('dotenv').config();

const app = express();
const NODE_ENV = process.env.NODE_ENV || 'development';

// Secrets cache with TTL
class SecretManager {
  constructor() {
    this.cache = new Map();
    this.ttl = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    const cached = this.cache.get(secretName);

    // Return cached value if not expired
    if (cached && Date.now() - cached.timestamp < this.ttl) {
      return cached.value;
    }

    // Fetch from secrets manager
    let secret;
    if (NODE_ENV === 'production') {
      secret = await this._fetchFromAWSSecretsManager(secretName);
    } else {
      // Development: from environment variables
      secret = process.env[secretName];
      if (!secret) {
        throw new Error(`Secret ${secretName} not found in environment`);
      }
    }

    // Cache the secret
    this.cache.set(secretName, {
      value: secret,
      timestamp: Date.now()
    });

    return secret;
  }

  async _fetchFromAWSSecretsManager(secretName) {
    const secretsManager = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    try {
      const data = await secretsManager.getSecretValue({
        SecretId: secretName
      }).promise();

      if ('SecretString' in data) {
        return JSON.parse(data.SecretString);
      }
      return data.SecretBinary;
    } catch (err) {
      console.error(`Failed to retrieve secret ${secretName}:`, err.message);
      throw new Error(`Secret retrieval failed for ${secretName}`);
    }
  }

  // Invalidate cache on demand (for secret rotation)
  invalidate(secretName) {
    this.cache.delete(secretName);
  }

  invalidateAll() {
    this.cache.clear();
  }
}

const secretManager = new SecretManager();

// Example usage
app.get('/secure-endpoint', async (req, res) => {
  try {
    const dbUrl = await secretManager.getSecret('DATABASE_URL');
    const apiKey = await secretManager.getSecret('API_KEY');

    // Use secrets
    res.json({ status: 'ok' });
  } catch (err) {
    res.status(500).json({ error: 'Failed to retrieve secrets' });
  }
});

module.exports = app;
```

