// Secure version of the application with all recommended security measures
require('dotenv').config();
const express = require('express');
const jwt = require('jsonwebtoken');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const winston = require('winston');

const app = express();

// ============================================================================
// CONFIGURATION & ENVIRONMENT VARIABLES
// ============================================================================

const JWT_SECRET = process.env.JWT_SECRET;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Validate required environment variables
if (!JWT_SECRET) {
  throw new Error('JWT_SECRET environment variable is not set');
}

// ============================================================================
// LOGGING SETUP
// ============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-api' },
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' }),
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================================================
// MIDDLEWARE SETUP
// ============================================================================

// 1. Security Headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
  frameguard: {
    action: 'deny',
  },
  referrerPolicy: {
    policy: 'strict-origin-when-cross-origin',
  },
}));

// 2. HTTPS Redirect
app.use((req, res, next) => {
  if (NODE_ENV === 'production' && req.header('x-forwarded-proto') !== 'https') {
    return res.redirect(`https://${req.header('host')}${req.url}`);
  }
  next();
});

// 3. CORS Configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400,
};

app.use(cors(corsOptions));

// 4. JSON Parser with size limit
app.use(express.json({ limit: '10kb' }));

// 5. Rate Limiting
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.path === '/health', // Skip health checks
});

app.use(globalLimiter);

// Stricter limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 30,
  skipSuccessfulRequests: false,
});

// ============================================================================
// AUTHENTICATION & AUTHORIZATION MIDDLEWARE
// ============================================================================

const authenticate = (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      logger.warn('Missing or invalid authorization header', {
        ip: req.ip,
        path: req.path,
      });
      return res.status(401).json({
        error: 'Missing or invalid authorization header',
      });
    }

    const token = authHeader.substring(7);

    try {
      const decoded = jwt.verify(token, JWT_SECRET);
      req.user = decoded;
      logger.info('Authentication successful', {
        userId: decoded.id,
        ip: req.ip,
      });
      next();
    } catch (jwtError) {
      logger.warn('JWT verification failed', {
        reason: jwtError.message,
        ip: req.ip,
      });
      return res.status(403).json({
        error: 'Invalid or expired token',
      });
    }
  } catch (err) {
    logger.error('Authentication middleware error', {
      error: err.message,
    });
    return res.status(500).json({
      error: NODE_ENV === 'production' ? 'Internal server error' : err.message,
    });
  }
};

const authorizeRole = (allowedRoles) => {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      logger.warn('Unauthorized access attempt', {
        userId: req.user?.id,
        requiredRole: allowedRoles,
        userRole: req.user?.role,
        ip: req.ip,
        path: req.path,
      });
      return res.status(403).json({
        error: 'Insufficient permissions',
      });
    }
    next();
  };
};

// ============================================================================
// ROUTES
// ============================================================================

// Health check - no authentication required but rate limited
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
  });
});

// Protected route - requires authentication
app.get('/users',
  authenticate,
  authorizeRole(['admin', 'manager']),
  strictLimiter,
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    // Input validation
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn('Query validation failed', {
        errors: errors.array(),
        userId: req.user.id,
      });
      return res.status(400).json({ errors: errors.array() });
    }

    const page = req.query.page || 1;
    const limit = req.query.limit || 10;

    logger.info('Users endpoint accessed', {
      userId: req.user.id,
      page,
      limit,
    });

    // Return sanitized data
    res.json({
      data: [
        { id: 1, name: 'Alice', role: 'admin' },
        { id: 2, name: 'Bob', role: 'user' },
      ],
      pagination: {
        page,
        limit,
        total: 2,
      },
    });
  }
);

// Login endpoint (example - implement with password hashing in production)
app.post('/login',
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 5,
    skipSuccessfulRequests: true,
    message: 'Too many login attempts',
  }),
  express.json(),
  (req, res) => {
    try {
      const { username, password } = req.body;

      // Validate input
      if (!username || !password) {
        logger.warn('Login attempt with missing credentials', {
          ip: req.ip,
        });
        return res.status(400).json({
          error: 'Username and password are required',
        });
      }

      // TODO: Validate credentials against database
      // TODO: Use bcrypt for password hashing

      // Generate token (example only)
      const token = jwt.sign(
        { id: 1, username, role: 'admin' },
        JWT_SECRET,
        { expiresIn: '1h' }
      );

      logger.info('User logged in successfully', {
        username,
        ip: req.ip,
      });

      res.json({ token });
    } catch (err) {
      logger.error('Login endpoint error', {
        error: err.message,
      });
      res.status(500).json({
        error: NODE_ENV === 'production' ? 'Internal server error' : err.message,
      });
    }
  }
);

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

app.use((req, res) => {
  logger.warn('404 Not Found', {
    path: req.path,
    method: req.method,
    ip: req.ip,
  });
  res.status(404).json({
    error: 'Not found',
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  const statusCode = err.statusCode || 500;
  const isDevelopment = NODE_ENV === 'development';

  res.status(statusCode).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`, {
    environment: NODE_ENV,
    timestamp: new Date().toISOString(),
  });
});

module.exports = app;

