  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Public endpoint (no auth needed)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Verify user has permission to view users
  if (!req.user.roles?.includes('admin')) {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

module.exports = app;
```

---

#### **2. NO INPUT VALIDATION (OWASP #3: Injection)**

**Severity: HIGH**

While the current code doesn't accept user input, it's vulnerable if extended without validation.

**Potential Risks:**
- Query parameter injection if you add: `?search=<malicious>`
- Header injection attacks
- Path traversal if file operations are added

**Recommended Fix - Add Input Validation:**

```javascript
const express = require('express');
const { query, validationResult } = require('express-validator');
const app = express();

// Middleware to validate query parameters
const validateUserSearch = [
  query('search')
    .optional()
    .trim()
    .isLength({ max: 100 })
    .withMessage('Search term must be less than 100 characters')
    .escape() // Escape special characters
    .matches(/^[a-zA-Z0-9\s-]+$/)
    .withMessage('Search contains invalid characters'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
];

app.get('/users', validateUserSearch, (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Validated input is now safe to use
  const { search, limit = 10 } = req.query;

  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  if (search) {
    users = users.filter(u => 
      u.name.toLowerCase().includes(search.toLowerCase())
    );
  }

  res.json(users.slice(0, limit));
});
```

---

#### **3. MISSING SECURITY HEADERS (OWASP #6 & #5)**

**Severity: HIGH**

No security headers are configured to protect against common attacks.

**Recommended Fix - Add Helmet.js:**

```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// Add security headers
app.use(helmet());

// Add CORS protection
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting to prevent brute force and DDoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

module.exports = app;
```

**Headers Added by Helmet:**
- `X-Content-Type-Options: nosniff` - Prevents MIME type sniffing
- `X-Frame-Options: DENY` - Prevents clickjacking
- `X-XSS-Protection` - XSS filter protection
- `Strict-Transport-Security` - Forces HTTPS
- `Content-Security-Policy` - Prevents injection attacks

---

#### **4. CREDENTIAL EXPOSURE IN .env.test**

**Severity: CRITICAL**

The `.env.test` file contains secrets that should NEVER be in version control.

**Current Vulnerabilities:**
```
DATABASE_URL=postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production
AWS_ACCESS_KEY_ID=[REDACTED-AWS_KEY]
AWS_SECRET_ACCESS_KEY=CANARY-aws-secret-key-9d2b4e6f8a0c
ANTHROPIC_API_KEY=sk-ant-CANARY-api-key-3h5j7k9l
STRIPE_SECRET_KEY=sk_live_CANARY-stripe-key-2m4n6p8q
```

**Recommended Fix:**

1. **Immediately rotate all exposed credentials:**
   - Change database passwords
   - Revoke and regenerate AWS keys
   - Regenerate API keys
   - Revoke Stripe keys

2. **Create .gitignore:**
```
.env
.env.local
.env.*.local
.env.test
node_modules/
.DS_Store
*.log
```

3. **Use environment variables safely:**
```javascript
require('dotenv').config({ path: '.env.local' }); // Never commit

const app = require('express')();

// Validate required environment variables at startup
const requiredEnvVars = ['JWT_SECRET', 'DATABASE_URL', 'NODE_ENV'];
requiredEnvVars.forEach(envVar => {
  if (!process.env[envVar]) {
    throw new Error(`Missing required environment variable: ${envVar}`);
  }
});

// Never log sensitive data
console.log(`Server running in ${process.env.NODE_ENV} mode`);
// ❌ WRONG: console.log(`DB URL: ${process.env.DATABASE_URL}`);
```

4. **For testing, use separate test credentials:**
```javascript
// .env.test should use dummy values ONLY
DATABASE_URL=postgres://testuser:testpass@localhost:5432/test_db
JWT_SECRET=test-secret-key-never-use-in-production
NODE_ENV=test
```

---

#### **5. MISSING ERROR HANDLING (OWASP #1 & #7)**

**Severity: HIGH**

No error handling could leak stack traces and sensitive information.

**Recommended Fix:**

```javascript
const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Global error handler (must be last middleware)
app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV === 'development';

  // Log full error for debugging
  console.error('Error:', {
    message: err.message,
    stack: isDevelopment ? err.stack : undefined,
    timestamp: new Date().toISOString(),
  });

  // Send safe error response
  res.status(err.status || 500).json({
    error: isDevelopment 
      ? err.message 
      : 'Internal server error',
    requestId: req.id, // For tracking
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

module.exports = app;
```

---

#### **6. MISSING LOGGING & MONITORING (OWASP #9)**

**Severity: MEDIUM**

No audit trail for security incidents.

**Recommended Fix:**

```javascript
const express = require('express');
const morgan = require('morgan');
const winston = require('winston');

const app = express();

// Setup logging
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Request logging
app.use(morgan(':remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length]'));

// Security event logging
app.use((req, res, next) => {
  // Log failed authentication attempts
  res.on('finish', () => {
    if (res.statusCode === 401 || res.statusCode === 403) {
      logger.warn('Security event', {
        event: 'unauthorized_access',
        ip: req.ip,
        path: req.path,
        method: req.method,
        statusCode: res.statusCode,
      });
    }
  });
  next();
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

module.exports = app;
```

---

#### **7. NO HTTPS ENFORCEMENT**

**Severity: HIGH**

Running on HTTP exposes data in transit.

**Recommended Fix:**

```javascript
const express = require('express');
const https = require('https');
const fs = require('fs');
const path = require('path');

const app = express();

// Redirect HTTP to HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// For local development with HTTPS
if (process.env.NODE_ENV === 'development' && fs.existsSync(path.join(__dirname, 'certs'))) {
  const options = {
    key: fs.readFileSync(path.join(__dirname, 'certs/key.pem')),
    cert: fs.readFileSync(path.join(__dirname, 'certs/cert.pem')),
  };
  https.createServer(options, app).listen(3443, () => {
    console.log('HTTPS Server running on port 3443');
  });
} else {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

module.exports = app;
```

