# Code Examples: Vulnerabilities & Fixes

## 1. SQL Injection

### ❌ VULNERABLE CODE
```javascript
// DO NOT DO THIS
app.get('/users/:id', (req, res) => {
  const userId = req.params.id;
  // Dangerous - directly concatenating user input
  const query = `SELECT * FROM users WHERE id = ${userId}`;
  database.query(query, (err, results) => {
    res.json(results);
  });
});

// Attack: GET /users/1 OR 1=1  (returns all users)
// Attack: GET /users/1; DROP TABLE users;--
```

### ✅ SECURE CODE
```javascript
app.get('/users/:id', (req, res) => {
  const userId = req.params.id;
  // Safe - use parameterized queries
  const query = 'SELECT * FROM users WHERE id = ?';
  database.query(query, [userId], (err, results) => {
    if (err) {
      res.status(500).json({ error: 'Database error' });
      return;
    }
    res.json(results);
  });
});
```

---

## 2. Cross-Site Scripting (XSS)

### ❌ VULNERABLE CODE
```javascript
app.get('/search', (req, res) => {
  const searchTerm = req.query.q;
  // Dangerous - directly rendering user input
  res.send(`<h1>Search results for: ${searchTerm}</h1>`);
});

// Attack: GET /search?q=<script>alert('XSS')</script>
```

### ✅ SECURE CODE
```javascript
const escapeHtml = require('escape-html');

app.get('/search', (req, res) => {
  const searchTerm = req.query.q;
  // Safe - escape HTML characters
  res.send(`<h1>Search results for: ${escapeHtml(searchTerm)}</h1>`);
});

// Or use template engine with auto-escaping (EJS, Handlebars)
// Or use Content Security Policy headers
```

---

## 3. NoSQL Injection

### ❌ VULNERABLE CODE
```javascript
app.post('/login', (req, res) => {
  const username = req.body.username;
  const password = req.body.password;

  // Dangerous - using object directly
  db.collection('users').findOne({
    username: username,
    password: password
  }, (err, user) => {
    res.json(user);
  });
});

// Attack payload:
// {"username": {"$ne": null}, "password": {"$ne": null}}
// Returns first user without checking password!
```

### ✅ SECURE CODE
```javascript
const { body, validationResult } = require('express-validator');
const crypto = require('crypto');

app.post('/login',
  body('username').trim().isLength({ min: 3, max: 50 }),
  body('password').isLength({ min: 8 }),
  async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { username, password } = req.body;

    // Hash password and compare
    const hashedPassword = crypto
      .createHash('sha256')
      .update(password)
      .digest('hex');

    const user = await db.collection('users').findOne({
      username: String(username),
      password: hashedPassword
    });

    if (!user) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    res.json({ token: generateToken(user) });
  }
);
```

---

## 4. Authentication Bypass

### ❌ VULNERABLE CODE
```javascript
// Client-side authentication (INSECURE!)
app.get('/admin', (req, res) => {
  // Checking if header exists instead of validating
  if (req.headers['x-admin']) {
    res.json({ data: 'secret admin data' });
    return;
  }
  res.status(403).json({ error: 'Forbidden' });
});

// Attack: curl -H "x-admin: true" http://localhost/admin
```

### ✅ SECURE CODE
```javascript
const jwt = require('jsonwebtoken');

function adminOnly(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Missing token' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);

    if (decoded.role !== 'admin') {
      return res.status(403).json({ error: 'Forbidden' });
    }

    req.user = decoded;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

app.get('/admin', adminOnly, (req, res) => {
  res.json({ data: 'secret admin data' });
});
```

---

## 5. Sensitive Data Exposure

### ❌ VULNERABLE CODE
```javascript
// User data endpoint
app.get('/api/users/:id', (req, res) => {
  const user = getUserFromDB(req.params.id);
  // Exposing everything including password hash!
  res.json(user);
});

// Returns: {
//   "id": 1,
//   "email": "user@example.com",
//   "password": "$2b$10$...", // NEVER expose!
//   "ssn": "123-45-6789",     // NEVER expose!
//   "creditCard": "4111-1111-1111-1111"  // NEVER expose!
// }
```

### ✅ SECURE CODE
```javascript
app.get('/api/users/:id', verifyToken, (req, res) => {
  const requestedUserId = req.params.id;
  const currentUserId = req.user.id;

  // Users can only view their own profile (unless admin)
  if (requestedUserId != currentUserId && req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const user = getUserFromDB(requestedUserId);

  // Only expose safe fields
  const safeUser = {
    id: user.id,
    email: user.email,
    name: user.name,
    createdAt: user.createdAt,
    // Don't include: password, ssn, creditCard, etc.
  };

  res.json(safeUser);
});
```

---

## 6. Broken Access Control

### ❌ VULNERABLE CODE
```javascript
app.delete('/users/:id', (req, res) => {
  const userId = req.params.id;
  // No authorization check! Anyone can delete anyone
  deleteUserFromDB(userId);
  res.json({ success: true });
});

// Any user can attack: DELETE /users/1 (delete another user)
```

### ✅ SECURE CODE
```javascript
app.delete('/users/:id', verifyToken, (req, res) => {
  const targetUserId = req.params.id;
  const currentUserId = req.user.id;

  // Users can only delete their own account
  if (targetUserId != currentUserId && req.user.role !== 'admin') {
    logSecurityEvent('warn', 'Unauthorized delete attempt', {
      attemptedUserId: targetUserId,
      userId: currentUserId
    });
    return res.status(403).json({ error: 'Forbidden' });
  }

  deleteUserFromDB(targetUserId);
  res.json({ success: true });
});
```

---

## 7. Insecure Deserialization

### ❌ VULNERABLE CODE
```javascript
const pickle = require('python-pickle'); // or similar

app.post('/data', (req, res) => {
  const serializedData = req.body.data;
  // Dangerous - deserializing untrusted data
  const data = pickle.loads(serializedData);
  res.json(data);
});

// Attacker can execute arbitrary code during deserialization
```

### ✅ SECURE CODE
```javascript
app.post('/data', (req, res) => {
  // Only accept JSON
  if (!req.is('application/json')) {
    return res.status(400).json({ error: 'Invalid content type' });
  }

  // Validate JSON schema
  const schema = {
    type: 'object',
    properties: {
      name: { type: 'string', maxLength: 100 },
      age: { type: 'integer', minimum: 0, maximum: 150 }
    },
    required: ['name'],
    additionalProperties: false
  };

  const ajv = require('ajv')();
  const validate = ajv.compile(schema);

  if (!validate(req.body)) {
    return res.status(400).json({ errors: validate.errors });
  }

  res.json(req.body);
});
```

---

## 8. Insecure HTTP Method

### ❌ VULNERABLE CODE
```javascript
app.get('/delete-user', (req, res) => {
  const userId = req.query.id;
  deleteUserFromDB(userId);
  res.json({ success: true });
});

// Dangerous! Can be triggered by:
// - URL in email <img src="http://api.com/delete-user?id=123">
// - Prefetching
// - Accidental clicks
```

### ✅ SECURE CODE
```javascript
// Use POST for state-changing operations
app.post('/users/:id/delete', verifyToken, (req, res) => {
  const userId = req.params.id;

  // Add CSRF protection
  if (req.body.csrf_token !== req.session.csrf_token) {
    return res.status(403).json({ error: 'CSRF token invalid' });
  }

  // Verify authorization
  if (userId != req.user.id && req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  deleteUserFromDB(userId);
  res.json({ success: true });
});
```

---

## 9. Security Misconfiguration

### ❌ VULNERABLE CODE
```javascript
app.use(express.json());
app.use(express.static('public'));

app.get('/api/users', (req, res) => {
  res.json(getAllUsers());
});

// No security headers, no CORS config, debug mode on, etc.
```

### ✅ SECURE CODE
```javascript
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

// Security headers
app.use(helmet());

// CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(','),
  credentials: true,
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use(limiter);

// Body size limit
app.use(express.json({ limit: '10kb' }));

// Hide Express version
app.disable('x-powered-by');

// Secure cookies
app.use(require('cookie-parser')());
app.set('view engine', 'html');
```

---

## 10. Using Components with Known Vulnerabilities

### ❌ VULNERABLE CODE
```json
{
  "dependencies": {
    "express": "4.16.0",
    "lodash": "4.17.4",
    "mongoose": "5.0.0"
  }
}
```

### ✅ SECURE CODE
```bash
# Regular security audits
npm audit
npm audit fix

# Update dependencies
npm update

# Use tools
npm install -g snyk
snyk test
snyk monitor

# In CI/CD
npm ci --production
npm audit --audit-level=moderate
```

---

## 11. Password Storage

### ❌ VULNERABLE CODE
```javascript
// Never do this!
const password = req.body.password;
user.password = password; // Plain text!
db.save(user);

// Or weak hashing
user.password = md5(password); // MD5 is broken!
```

### ✅ SECURE CODE
```javascript
const bcrypt = require('bcrypt');

app.post('/register',
  body('password').isLength({ min: 12 }).strong(),
  async (req, res) => {
    const { email, password } = req.body;

    // Hash with salt
    const salt = await bcrypt.genSalt(10);
    const hashedPassword = await bcrypt.hash(password, salt);

    const user = { email, password: hashedPassword };
    await db.collection('users').insertOne(user);

    res.json({ success: true });
  }
);

// Verification
app.post('/login', async (req, res) => {
  const { email, password } = req.body;
  const user = await db.collection('users').findOne({ email });

  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const isValid = await bcrypt.compare(password, user.password);
  if (!isValid) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  res.json({ token: generateToken(user) });
});
```

---

## 12. Command Injection

### ❌ VULNERABLE CODE
```javascript
const exec = require('child_process').exec;

app.post('/compress', (req, res) => {
  const filename = req.body.filename;
  // Dangerous! User input passed to shell
  exec(`gzip ${filename}`, (error) => {
    res.json({ compressed: true });
  });
});

// Attack: filename = "file.txt; rm -rf /"
```

### ✅ SECURE CODE
```javascript
const { execFile } = require('child_process');
const path = require('path');

app.post('/compress', (req, res) => {
  const filename = req.body.filename;

  // Validate filename
  if (!filename.match(/^[a-zA-Z0-9._-]+$/)) {
    return res.status(400).json({ error: 'Invalid filename' });
  }

  // Use execFile instead of exec (no shell)
  const filepath = path.join('/uploads', filename);

  execFile('gzip', [filepath], (error) => {
    if (error) {
      return res.status(500).json({ error: 'Compression failed' });
    }
    res.json({ compressed: true });
  });
});
```

