### STEP 4: Implement Authorization (CRITICAL)

**File: app_secure.js - Lines 98-115**

```javascript
const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    if (!allowedRoles.includes(req.user.role)) {
      logSecurityEvent(req.user.id, 'unauthorized_access', 'insufficient_permissions', {
        path: req.path,
        userRole: req.user.role,
        requiredRoles: allowedRoles
      });
      return res.status(403).json({
        error: 'Forbidden',
        message: 'Insufficient permissions'
      });
    }
    next();
  };
};

// Use it like this:
