## Secure Implementation: app_secure_v2.js

Let me create an improved version with proper secrets management:

/**
 * SECURE APPLICATION v2 - With Secrets Management
 * Improved secrets handling with validation and isolation
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const fs = require('fs');
const path = require('path');

// ============================================================================
// SECRETS CONFIGURATION - VALIDATED & ISOLATED
// ============================================================================

/**
 * Load and validate secrets from environment
 * Fails fast if required secrets are missing
 */
const loadSecrets = () => {
  const requiredSecrets = [
    'JWT_SECRET',
    'NODE_ENV'
  ];

  const optionalSecrets = [
    'ALLOWED_ORIGINS',
    'DB_HOST',
    'DB_PORT',
    'DB_USER',
    'DB_PASSWORD'
  ];

  // Validate all required secrets exist
  const missingSecrets = requiredSecrets.filter(secret => !process.env[secret]);
  if (missingSecrets.length > 0) {
    const errorMsg = `❌ CRITICAL: Missing required secrets: ${missingSecrets.join(', ')}\n` +
      `Please configure these in .env or environment variables.`;
    console.error(errorMsg);
    throw new Error(errorMsg);
  }

  // Validate JWT_SECRET strength
  if (process.env.JWT_SECRET.length < 32) {
    throw new Error(
      '❌ JWT_SECRET must be at least 32 characters long. ' +
      'Generate one with: node -e "console.log(require(\'crypto\').randomBytes(32).toString(\'hex\'))"'
    );
  }

  // Build secrets object (isolate access)
  const secrets = {
    // JWT Configuration
    jwt: {
      secret: process.env.JWT_SECRET,
      algorithm: 'HS256',
      expiresIn: process.env.JWT_EXPIRES || '1h',
      refreshExpiresIn: process.env.JWT_REFRESH_EXPIRES || '7d'
    },

    // Environment
    env: process.env.NODE_ENV || 'development',
    isDevelopment: (process.env.NODE_ENV || 'development') === 'development',
    isProduction: (process.env.NODE_ENV || 'development') === 'production',

    // CORS
    cors: {
      origins: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',')
    },

    // Database (optional)
    database: process.env.DB_HOST ? {
      host: process.env.DB_HOST,
      port: parseInt(process.env.DB_PORT) || 5432,
      user: process.env.DB_USER,
      password: process.env.DB_PASSWORD,
      database: process.env.DB_NAME || 'app_db'
    } : null,

    // Server
    port: parseInt(process.env.PORT) || 3000,

    // Security
    requireHttps: process.env.REQUIRE_HTTPS === 'true',
    cookieSecure: process.env.COOKIE_SECURE === 'true'
  };

  // Log configuration status (without exposing secrets)
  console.log(`✅ Secrets loaded successfully`);
  console.log(`   Environment: ${secrets.env}`);
  console.log(`   JWT Algorithm: ${secrets.jwt.algorithm}`);
  console.log(`   JWT Expires: ${secrets.jwt.expiresIn}`);
  console.log(`   CORS Origins: ${secrets.cors.origins.join(', ')}`);

  return secrets;
};

// Load secrets at startup (fail fast if missing)
let secrets;
try {
  secrets = loadSecrets();
} catch (error) {
  console.error(error.message);
  process.exit(1);
}

// Prevent accidental global exposure of secrets
Object.freeze(secrets);

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Apply Security Headers
app.use(helmet());

// 2. Enforce HTTPS in production
if (secrets.isProduction && secrets.requireHttps) {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      return res.status(403).json({ error: 'HTTPS required' });
    }
    next();
  });
}

// 3. Configure CORS
app.use(cors({
  origin: secrets.cors.origins,
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 4. Request Size Limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 5. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => secrets.isDevelopment
});
app.use(limiter);

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true
});

// ============================================================================
// LOGGING SETUP (WITHOUT EXPOSING SECRETS)
// ============================================================================

const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir, { recursive: true });
}

/**
 * Log security events (without logging secrets)
 * @param {string} user - User identifier
 * @param {string} action - Action performed
 * @param {string} status - Success/failure status
 * @param {object} details - Event details (NO SECRETS!)
 */
const logSecurityEvent = (user, action, status, details) => {
  const timestamp = new Date().toISOString();

  // Sanitize details to prevent secret logging
  const sanitized = {
    ...details,
    // Never log these fields
    password: undefined,
    secret: undefined,
    token: undefined,
    JWT_SECRET: undefined,
    DB_PASSWORD: undefined
  };

  const logEntry = `[${timestamp}] User: ${user || 'anonymous'}, Action: ${action}, Status: ${status}, Details: ${JSON.stringify(sanitized)}\n`;

  try {
    fs.appendFileSync(path.join(logsDir, 'security.log'), logEntry);
  } catch (err) {
    console.error('Failed to write security log:', err.message);
  }
};

// ============================================================================
// AUTHENTICATION MIDDLEWARE (SECURE)
// ============================================================================

/**
 * Verify JWT token with proper secret management
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logSecurityEvent('unknown', 'access_denied', 'no_token', { path: req.path });
    return res.status(401).json({
      error: 'Access Denied',
      message: 'Authentication token required'
    });
  }

  // Use isolated secret from secrets object
  jwt.verify(token, secrets.jwt.secret, (err, user) => {
    if (err) {
      logSecurityEvent('unknown', 'access_denied', 'invalid_token', {
        path: req.path,
        error: err.message
      });
      return res.status(403).json({
        error: 'Invalid or Expired Token',
        message: 'Please authenticate again'
      });
    }
    req.user = user;
    next();
  });
};

// ============================================================================
// AUTHORIZATION MIDDLEWARE
// ============================================================================

const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    if (!allowedRoles.includes(req.user.role)) {
      logSecurityEvent(req.user.id, 'unauthorized_access', 'insufficient_permissions', {
        path: req.path,
        userRole: req.user.role,
        requiredRoles: allowedRoles
      });
      return res.status(403).json({
        error: 'Forbidden',
        message: 'Insufficient permissions'
      });
    }
    next();
  };
};

// ============================================================================
// ROUTES
// ============================================================================

// Health check (public)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: secrets.env,
    // Don't expose secrets in health check!
    secrets: undefined
  });
});

// Get users (protected)
app.get('/users',
  authenticateToken,
  authorize('admin', 'user'),
  query('id').optional().isInt().toInt(),
  query('search').optional().trim().escape(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation Error',
        details: errors.array()
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    let response = users;
    if (req.user.role !== 'admin') {
      response = users.map(u => ({ id: u.id, name: u.name }));
    }

    logSecurityEvent(req.user.id, 'fetch_users', 'success', {
      userCount: response.length,
      userRole: req.user.role
    });

    res.json(response);
  }
);

// Authentication endpoint (with rate limiting)
app.post('/auth/login', authLimiter, express.json(), (req, res) => {
  const { username, password } = req.body;

  if (!username || !password) {
    logSecurityEvent(username, 'login_attempt', 'failure', {
      reason: 'missing_credentials'
    });
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Username and password required'
    });
  }

  // Mock user database (use hashed passwords in production!)
  const users = {
    'admin': { id: 1, role: 'admin' },
    'user': { id: 2, role: 'user' }
  };

  const user = users[username];
  if (!user || password !== 'password123') {
    logSecurityEvent(username, 'login_attempt', 'failure', {
      reason: 'invalid_credentials'
    });
    return res.status(401).json({
      error: 'Authentication Failed',
      message: 'Invalid username or password'
    });
  }

  // Use isolated secret for token generation
  const token = jwt.sign(
    {
      id: user.id,
      username,
      role: user.role,
      iat: Math.floor(Date.now() / 1000)
    },
    secrets.jwt.secret,  // ✅ From secrets object
    {
      algorithm: secrets.jwt.algorithm,
      expiresIn: secrets.jwt.expiresIn
    }
  );

  logSecurityEvent(user.id, 'login_attempt', 'success', {
    username,
    role: user.role,
    // Never log the token!
    token: undefined
  });

  res.json({
    token,
    expiresIn: secrets.jwt.expiresIn,
    tokenType: 'Bearer'
  });
});

// ============================================================================
// ERROR HANDLING (WITHOUT EXPOSING SECRETS)
// ============================================================================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist'
  });
});

// Global Error Handler
app.use((err, req, res, next) => {
  console.error('Error:', err);

  logSecurityEvent('system', 'error', 'exception', {
    message: err.message,
    path: req.path,
    // Never log stack traces!
    stack: undefined
  });

  // Don't expose stack traces or secrets in responses
  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: secrets.isDevelopment ? err.message : 'An error occurred',
    ...(secrets.isDevelopment && { stack: err.stack })
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const port = secrets.port;
const nodeEnv = secrets.env;

app.listen(port, () => {
  console.log(`✅ Server running on port ${port} in ${nodeEnv} mode`);
  console.log(`🔒 Secrets validation: PASSED`);
  console.log(`🔐 Security: ENABLED`);

  logSecurityEvent('system', 'server_start', 'success', {
    port,
    environment: nodeEnv,
    requireHttps: secrets.requireHttps
  });
});

// ============================================================================
// CLEANUP - Clear sensitive data on shutdown
// ============================================================================

process.on('SIGINT', () => {
  console.log('\n🛑 Shutting down gracefully...');

  // Zero out secrets memory
  Object.keys(secrets).forEach(key => {
    if (typeof secrets[key] === 'string') {
      secrets[key] = '';
    }
  });

  logSecurityEvent('system', 'server_shutdown', 'success', {
    reason: 'SIGINT received'
  });

  process.exit(0);
});

module.exports = app;

