  const token = authHeader && authHeader.split(' ')[1]; // Extract bearer token

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users can access
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

## 3. **🟠 HIGH: No Input Validation**

**Vulnerability:** No query parameter or request body validation

**Risk:** Parameter injection, DoS attacks via malformed requests

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  // No validation of query parameters
  // Vulnerable to: ?id=<script>, ?limit=999999999, etc.
});
```

**Recommendations:**

```javascript
const { query, validationResult } = require('express-validator');

app.get('/users', 
  // Validate query parameters
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    res.json({
      data: [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ],
      limit,
      offset,
    });
  }
);
```

---

## 4. **🟠 HIGH: Missing Security Headers**

**Vulnerability:** No HTTP security headers configured

**Risk:** XSS, clickjacking, MIME type sniffing attacks

**Recommendations:**

```javascript
const helmet = require('helmet');

// Add security headers
app.use(helmet());

// Additional headers for strictness
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  next();
});
```

---

## 5. **🟠 HIGH: No Rate Limiting**

**Vulnerability:** No protection against brute force or DoS attacks

**Risk:** Attackers can spam endpoints, causing resource exhaustion

**Recommendations:**

```javascript
const rateLimit = require('express-rate-limit');

// Rate limiter middleware
