  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use('/api/', limiter);

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

---

## 6. **🟠 HIGH: No CORS Configuration**

**Vulnerability:** Missing or default CORS could expose data to unauthorized origins

**Risk:** Cross-origin attacks, data leakage to malicious websites

**Recommendations:**

```javascript
const cors = require('cors');

// Restricted CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};

app.use(cors(corsOptions));

// WRONG - Never use this:
// app.use(cors()); // Allow all origins
```

---

## 7. **🟡 MEDIUM: No Logging and Monitoring**

**Vulnerability:** No audit trail for security incidents

**Risk:** Cannot detect or investigate attacks; no incident response capability

**Recommendations:**

```javascript
const winston = require('winston');

// Configure structured logging
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'access.log' }),
  ],
});

// Middleware to log requests
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });
  next();
});

// Log authentication failures
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    timestamp: new Date().toISOString(),
  });
  res.status(500).json({ error: 'Internal server error' });
});
```

---

## 8. **🟡 MEDIUM: No Error Handling**

**Vulnerability:** Unhandled errors could expose stack traces and system information

**Risk:** Information disclosure, attackers can fingerprint the application

**Recommendations:**

```javascript
// Global error handler
app.use((err, req, res, next) => {
  // Log error internally
  console.error('Unhandled error:', err);

  // Don't expose sensitive error details to clients
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    error: message,
    timestamp: new Date().toISOString(),
  });
});

// Handle 404
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});
```

---

## 9. **🟡 MEDIUM: Sensitive Data Exposure (Email)**

**Vulnerability:** Email addresses are exposed publicly

**Risk:** Privacy violation, phishing target list for attackers

**Recommendations:**

```javascript
// Only return user data to authenticated users
const authenticateToken = (req, res, next) => {
  // ... authentication logic ...
};

app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users see emails
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Optionally mask email for public view
  if (!req.user.isAdmin) {
    users.forEach(user => {
      user.email = user.email.replace(/(.{2})(.*)(@.*)/, '$1***$3');
    });
  }

  res.json(users);
});
```

---

## 10. **🟡 MEDIUM: Missing Content-Type Validation**

**Vulnerability:** No validation of request content type

**Risk:** MIME type confusion attacks

**Recommendations:**

```javascript
app.use(express.json({ limit: '10kb' })); // Also set size limit to prevent large payloads
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// Middleware to validate content-type
app.use((req, res, next) => {
  if (['POST', 'PUT', 'PATCH'].includes(req.method)) {
    if (!req.is('application/json')) {
      return res.status(415).json({ error: 'Content-Type must be application/json' });
    }
  }
  next();
});
```

---

## 11. **🟡 MEDIUM: No HTTPS Enforcement**

**Vulnerability:** Application can run on unencrypted HTTP

**Risk:** Man-in-the-middle attacks, credential interception

**Recommendations:**

```javascript
// Force HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// Or use HSTS header (via helmet)
app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true,
}));
```

---

## 12. **🟡 MEDIUM: No Request Size Limit**

**Vulnerability:** Unbounded request size

**Risk:** Buffer overflow, DoS via large payloads

**Recommendations:**

```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));
```

---

