const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const winston = require('winston');
const { query, validationResult } = require('express-validator');
const dotenv = require('dotenv');

dotenv.config();

const app = express();
const SECRET_KEY = process.env.JWT_SECRET || 'change-me-in-production';
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================================================
// LOGGING SETUP
// ============================================================================

const logger = winston.createLogger({
  level: NODE_ENV === 'production' ? 'warn' : 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'secure-app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================================================
// SECURITY HEADERS
// ============================================================================

app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  },
}));

app.use(helmet.hsts({
  maxAge: 31536000,
  includeSubDomains: true,
  preload: true
}));

// ============================================================================
// HTTPS ENFORCEMENT
// ============================================================================

app.use((req, res, next) => {
  if (NODE_ENV === 'production' && req.header('x-forwarded-proto') !== 'https') {
    return res.redirect(301, `https://${req.header('host')}${req.url}`);
  }
  next();
});

// ============================================================================
// CORS CONFIGURATION
// ============================================================================

const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');

const corsOptions = {
  origin: function (origin, callback) {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn({ message: 'CORS rejection', origin });
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400
};

app.use(cors(corsOptions));

// ============================================================================
// BODY PARSING WITH LIMITS
// ============================================================================

app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================================================
// HTTP REQUEST LOGGING
// ============================================================================

app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim())
  }
}));

// Security event logging middleware
app.use((req, res, next) => {
  res.on('finish', () => {
    if (res.statusCode >= 400) {
      logger.warn({
        event: 'HTTP_ERROR',
        method: req.method,
        url: req.url,
        status: res.statusCode,
        ip: req.ip,
        userAgent: req.headers['user-agent']
      });
    }
  });
  next();
});

// ============================================================================
// RATE LIMITING
// ============================================================================

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn({ event: 'RATE_LIMIT_EXCEEDED', ip: req.ip });
    res.status(429).json({ error: 'Too many requests, please try again later' });
  }
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many failed authentication attempts',
  handler: (req, res) => {
    logger.warn({ event: 'AUTH_LIMIT_EXCEEDED', ip: req.ip });
    res.status(429).json({ error: 'Too many failed attempts, please try again later' });
  }
});

app.use(generalLimiter);

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({ event: 'MISSING_AUTH_TOKEN', ip: req.ip, url: req.url });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, SECRET_KEY, (err, user) => {
    if (err) {
      logger.warn({ event: 'INVALID_TOKEN', ip: req.ip, error: err.message });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// ============================================================================
// AUTHORIZATION MIDDLEWARE
// ============================================================================

function authorize(...allowedRoles) {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      logger.warn({ 
        event: 'UNAUTHORIZED_ACCESS', 
        userId: req.user?.id, 
        requiredRole: allowedRoles,
        userRole: req.user?.role,
        url: req.url 
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

// ============================================================================
// ROUTES
// ============================================================================

// Health check (public)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV 
  });
});

// Login endpoint
app.post('/login', authLimiter, (req, res) => {
  try {
    // In production, validate credentials against database
    const user = {
      id: 1,
      role: 'user'
    };

    const token = jwt.sign(user, SECRET_KEY, { expiresIn: '1h' });

    logger.info({ event: 'USER_LOGIN', userId: user.id });
    res.json({ token });
  } catch (error) {
    logger.error({ event: 'LOGIN_ERROR', error: error.message });
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Protected users endpoint
app.get('/users', 
  authenticateToken, 
  authorize('admin'),
  (req, res) => {
    try {
      // In production, fetch from database
      const users = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
      ];

      logger.info({ event: 'USERS_FETCHED', userId: req.user.id, count: users.length });
      res.json(users);
    } catch (error) {
      logger.error({ event: 'GET_USERS_ERROR', error: error.message });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Search endpoint with input validation
app.get('/search',
  query('q')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Search query must be 1-100 characters')
    .escape(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn({ event: 'INVALID_SEARCH_INPUT', errors: errors.array() });
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      const searchQuery = req.query.q;
      // In production, perform safe database query
      res.json({ results: [] });
    } catch (error) {
      logger.error({ event: 'SEARCH_ERROR', error: error.message });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// ============================================================================
// ERROR HANDLERS
// ============================================================================

// 404 handler
app.use((req, res) => {
  logger.warn({ event: 'NOT_FOUND', method: req.method, url: req.url });
  res.status(404).json({ error: 'Not found' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  logger.error({
    event: 'UNHANDLED_ERROR',
    message: err.message,
    stack: NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  const statusCode = err.statusCode || 500;
  const message = NODE_ENV === 'development' 
    ? err.message 
    : 'An error occurred';

  res.status(statusCode).json({ error: message });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

if (require.main === module) {
  app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT} in ${NODE_ENV} environment`);
  });
}

module.exports = app;

# Security Quick Reference - app.js Review

## 🔴 CRITICAL VULNERABILITIES

### 1. No Authentication
- **Risk**: Anyone can access sensitive endpoints
- **Impact**: Unauthorized data exposure
- **Fix**: Implement JWT-based authentication
```javascript
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  jwt.verify(token, SECRET_KEY, (err, user) => {
    if (err) return res.status(403).json({ error: 'Forbidden' });
    req.user = user;
    next();
  });
};
```

### 2. No HTTPS
- **Risk**: Man-in-the-middle attacks, data interception
- **Impact**: Complete compromise of data confidentiality
- **Fix**: Enforce HTTPS in production
```javascript
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && 
      req.header('x-forwarded-proto') !== 'https') {
    return res.redirect(301, `https://${req.header('host')}${req.url}`);
  }
  next();
});
```

### 3. No Input Validation
- **Risk**: Injection attacks, command execution
- **Impact**: Database compromise, data theft
- **Fix**: Validate and sanitize all inputs
```javascript
app.get('/search',
  query('q').trim().isLength({min:1,max:100}).escape(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use req.query.q
  }
);
```

---

## 🟠 HIGH PRIORITY

### 4. Missing Security Headers
- **Risk**: Clickjacking, XSS, MIME-sniffing attacks
- **Fix**: Use Helmet.js
```javascript
const helmet = require('helmet');
app.use(helmet());
```

### 5. No Rate Limiting
- **Risk**: Brute force attacks, DoS attacks
- **Fix**: Implement rate limiting
```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use(limiter);
```

---

## 🟡 MEDIUM PRIORITY

### 6. No Logging
- **Risk**: No audit trail, can't detect attacks
- **Fix**: Implement logging
```javascript
const winston = require('winston');
const logger = winston.createLogger({...});
app.use(morgan('combined'));
```

### 7. Hardcoded Sensitive Data
- **Risk**: Credentials exposed in source code
- **Fix**: Use environment variables
```javascript
require('dotenv').config();
const SECRET = process.env.JWT_SECRET;
```

### 8. Poor Error Handling
- **Risk**: Information disclosure through error messages
- **Fix**: Generic error messages in production
```javascript
app.use((err, req, res, next) => {
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal error' 
    : err.message;
  res.status(500).json({ error: message });
});
```

### 9. No CORS Configuration
- **Risk**: Unauthorized cross-origin requests
- **Fix**: Configure CORS properly
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS.split(','),
  credentials: true
}));
```

### 10. No Authorization
- **Risk**: Privilege escalation attacks
- **Fix**: Check user roles
```javascript
const authorize = (role) => (req, res, next) => {
  if (req.user.role !== role) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  next();
};
```

