## 1. MISSING AUTHENTICATION

### ❌ VULNERABLE CODE
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Problems:**
- Anyone can access sensitive user data
- No authentication required
- No access control
- Exposes email addresses

**Attack:**
```bash
curl http://localhost:3000/users
# Returns all user data without any credentials!
```

---

### ✅ SECURE CODE
```javascript
const jwt = require('jsonwebtoken');

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({ event: 'MISSING_AUTH_TOKEN', ip: req.ip });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn({ event: 'INVALID_TOKEN', ip: req.ip });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

function authorize(...roles) {
  return (req, res, next) => {
    if (!roles.includes(req.user.role)) {
      logger.warn({ event: 'UNAUTHORIZED', userId: req.user.id });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

app.get('/users', authenticateToken, authorize('admin'), (req, res) => {
  try {
    // Only admin users can access
    const users = database.getUsers();
    res.json(users);
  } catch (error) {
    logger.error({ event: 'GET_USERS_ERROR', error: error.message });
    res.status(500).json({ error: 'Internal error' });
  }
});
```

**Benefits:**
- Requires valid JWT token
- Checks user authorization (role-based)
- Logs security events
- Handles errors gracefully

**Usage:**
```bash
# Get token
TOKEN=$(curl -X POST http://localhost:3000/login -d '{}' | jq -r '.token')

# Use token
curl -H "Authorization: Bearer $TOKEN" http://localhost:3000/users
```

