    try {
      const query = req.query.q; // Now safe
      const results = database.query(query);
      res.json(results);
    } catch (error) {
      logger.error({ event: 'SEARCH_ERROR', error: error.message });
      res.status(500).json({ error: 'Internal error' });
    }
  }
);
```

