const AWS = require('aws-sdk');
const cache = require('node-cache');

// Cache secrets for 1 hour (adjust based on needs)
const secretsCache = new cache({ stdTTL: 3600 });

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1',
});

async function getSecret(secretName) {
  // Check cache first
  const cached = secretsCache.get(secretName);
  if (cached) {
    console.log(`Retrieved ${secretName} from cache`);
    return cached;
  }

  try {
    const data = await secretsManager.getSecretValue({ 
      SecretId: secretName 
    }).promise();

    let secret;
    if ('SecretString' in data) {
      secret = JSON.parse(data.SecretString);
    } else {
      secret = Buffer.from(data.SecretBinary, 'base64').toString('utf-8');
    }

    // Cache the secret
    secretsCache.set(secretName, secret);
    console.log(`Retrieved ${secretName} from AWS Secrets Manager`);

    return secret;
  } catch (error) {
    console.error(`Error retrieving secret ${secretName}:`, error);
    throw error;
  }
}

// Usage
async function initializeApp() {
  try {
    const secrets = await getSecret('app/production/secrets');
    const { JWT_SECRET, DB_PASSWORD, API_KEY } = secrets;

    // Use secrets...
    return {
      JWT_SECRET,
      DB_PASSWORD,
      API_KEY,
    };
  } catch (error) {
    console.error('Failed to load secrets');
    process.exit(1);
  }
}
```

