const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const NodeCache = require('node-cache');

const secretCache = new NodeCache({ stdTTL: 3600 });
const client = new SecretManagerServiceClient();

async function getGoogleSecret(projectId, secretId, version = 'latest') {
  const cacheKey = `${projectId}/${secretId}/${version}`;

  // Check cache
  if (secretCache.has(cacheKey)) {
    return secretCache.get(cacheKey);
  }

  try {
    const name = client.secretVersionPath(projectId, secretId, version);
    const [version_data] = await client.accessSecretVersion({ name });
    const secret = version_data.payload.data.toString('utf8');

    secretCache.set(cacheKey, secret);
    return secret;
  } catch (error) {
    console.error(`Failed to retrieve secret: ${error.message}`);
    throw error;
  }
}

