## 🛡️ SECURE CONFIGURATION EXAMPLE

Here's a production-ready configuration strategy:

```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const NodeCache = require('node-cache');

class SecretsManager {
  constructor() {
    this.cache = new NodeCache({ stdTTL: 3600 });
    this.secretsManagerClient = new AWS.SecretsManager({
      region: process.env.AWS_REGION,
    });
  }

  async loadSecrets() {
    const env = process.env.NODE_ENV || 'development';

    // Development: Use .env (via dotenv package)
    if (env === 'development') {
      require('dotenv').config();
      return this._validateSecrets({
        JWT_SECRET: process.env.JWT_SECRET,
        DB_PASSWORD: process.env.DB_PASSWORD,
        API_KEY: process.env.API_KEY,
      });
    }

    // Production: Use AWS Secrets Manager
    if (env === 'production') {
      return await this._fetchFromAWS('prod/app-secrets');
    }

    // Staging: Use AWS Secrets Manager
    if (env === 'staging') {
      return await this._fetchFromAWS('staging/app-secrets');
    }

    throw new Error(`Unknown environment: ${env}`);
  }

  async _fetchFromAWS(secretName) {
    const cached = this.cache.get(secretName);
    if (cached) return cached;

    try {
      const data = await this.secretsManagerClient
        .getSecretValue({ SecretId: secretName })
        .promise();

      const secret = JSON.parse(data.SecretString);
      this.cache.set(secretName, secret);
      return this._validateSecrets(secret);
    } catch (error) {
      console.error(`Failed to load secrets from AWS: ${error.message}`);
      throw new Error('Failed to load application secrets');
    }
  }

  _validateSecrets(secrets) {
    const required = ['JWT_SECRET', 'DB_PASSWORD', 'API_KEY'];
    const missing = required.filter(key => !secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    if (secrets.JWT_SECRET.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters');
    }

    return secrets;
  }
}

module.exports = new SecretsManager();
```

**Usage in app.js**:
```javascript
const express = require('express');
const secretsManager = require('./config/secrets');

async function startApp() {
  try {
    const secrets = await secretsManager.loadSecrets();

    const app = express();

    // Now secrets are safely loaded
    app.use((req, res, next) => {
      req.app.locals.JWT_SECRET = secrets.JWT_SECRET;
      next();
    });

    app.listen(3000);
  } catch (error) {
    console.error('Failed to start application:', error);
    process.exit(1);
  }
}

startApp();
```

