// Secure version of app.js with security best practices applied

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const winston = require('winston');
const Joi = require('joi');

const app = express();

// ============================================
// LOGGER CONFIGURATION
// ============================================
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'secure-app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Security Headers (Helmet.js)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
}));

// 2. CORS Configuration
const allowedOrigins = process.env.ALLOWED_ORIGINS 
  ? process.env.ALLOWED_ORIGINS.split(',')
  : ['http://localhost:3000'];

const corsOptions = {
  origin: function(origin, callback) {
    // Allow requests with no origin (like curl requests)
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn({ event: 'cors_rejected', origin });
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};

app.use(cors(corsOptions));

// 3. Body Parser with size limits
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// 4. Request Logging Middleware
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      event: 'request',
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
    });
  });

  next();
});

// 5. Rate Limiting
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per 15 minutes
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => {
    // Skip rate limiting for health checks
    return req.path === '/health';
  },
});

app.use(globalLimiter);

// Stricter rate limit for public endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

// ============================================
// AUTHENTICATION MIDDLEWARE
// ============================================
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({
      event: 'auth_failed',
      reason: 'missing_token',
      ip: req.ip,
      path: req.path,
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'dev-secret', (err, user) => {
    if (err) {
      logger.warn({
        event: 'auth_failed',
        reason: 'invalid_token',
        ip: req.ip,
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }

    req.user = user;
    next();
  });
};

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================
const validateRequest = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate({
      body: req.body,
      query: req.query,
      params: req.params,
    });

    if (error) {
      logger.warn({
        event: 'validation_error',
        details: error.details.map(d => d.message),
        ip: req.ip,
      });
      return res.status(400).json({
        error: 'Invalid input',
        details: error.details.map(d => ({
          path: d.path.join('.'),
          message: d.message,
        })),
      });
    }

    req.validated = value;
    next();
  };
};

// ============================================
// VALIDATION SCHEMAS
// ============================================
const healthQuerySchema = Joi.object({
  query: Joi.object({}).unknown(true),
});

const usersQuerySchema = Joi.object({
  query: Joi.object({
    limit: Joi.number().integer().min(1).max(100).default(10),
    offset: Joi.number().integer().min(0).default(0),
  }).unknown(true),
});

// ============================================
// ROUTES
// ============================================

/**
 * Health Check Endpoint
 * Public endpoint for monitoring application status
 */
app.get('/health', validateRequest(healthQuerySchema), (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    logger.error({ event: 'health_check_error', error: error.message });
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get Users Endpoint
 * Protected endpoint - requires valid JWT token
 */
app.get('/users', authenticateToken, validateRequest(usersQuerySchema), (req, res, next) => {
  try {
    const { limit, offset } = req.validated.query;

    // Mock users data - in production, fetch from database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const users = allUsers.slice(offset, offset + limit);

    logger.info({
      event: 'users_accessed',
      userId: req.user.id,
      count: users.length,
    });

    res.json({
      data: users,
      pagination: {
        total: allUsers.length,
        limit,
        offset,
      },
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================
app.use((err, req, res, next) => {
  logger.error({
    event: 'unhandled_error',
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Don't expose internal error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  const statusCode = err.status || err.statusCode || 500;

  res.status(statusCode).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// 404 Handler
app.use((req, res) => {
  logger.warn({
    event: 'not_found',
    path: req.path,
    method: req.method,
  });
  res.status(404).json({ error: 'Not found' });
});

// ============================================
// SERVER START
// ============================================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  logger.info({
    event: 'server_started',
    port: PORT,
    env: NODE_ENV,
    timestamp: new Date().toISOString(),
  });
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;

