# Security Before & After Comparison

## Authentication

### ❌ BEFORE (Insecure)
```javascript
app.get('/users', (req, res) => {
  res.json(users); // Anyone can access
});
```

### ✅ AFTER (Secure)
```javascript
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users reach here
  res.json(users);
});
```

**Impact:** Only authenticated users can access sensitive data.

---

## Security Headers

### ❌ BEFORE (Insecure)
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
// No security headers sent
```

### ✅ AFTER (Secure)
```javascript
const helmet = require('helmet');
app.use(helmet()); // Adds security headers automatically

// Or manually:
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  next();
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
```

**Impact:** Protects against XSS, clickjacking, and MIME type sniffing attacks.

---

## Input Validation

### ❌ BEFORE (Insecure)
```javascript
app.get('/users', (req, res) => {
  // No validation - could receive anything
  const limit = req.query.limit; // Could be "999999" or "'DROP TABLE;'"
  res.json(users);
});
```

### ✅ AFTER (Secure)
```javascript
const Joi = require('joi');

const validateRequest = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate({
      query: req.query,
    });

    if (error) {
      return res.status(400).json({ 
        error: 'Invalid input',
        details: error.details
      });
    }

    req.validated = value;
    next();
  };
};

const usersQuerySchema = Joi.object({
  query: Joi.object({
    limit: Joi.number().integer().min(1).max(100).default(10),
    offset: Joi.number().integer().min(0).default(0),
  }),
});

app.get('/users', authenticateToken, validateRequest(usersQuerySchema), (req, res) => {
  const { limit, offset } = req.validated.query; // Guaranteed valid values
  res.json(users);
});
```

**Impact:** Prevents injection attacks and enforces data constraints.

---

## Data Storage

### ❌ BEFORE (Insecure)
```javascript
// Data hardcoded in source code
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```
**Problems:**
- Visible in source control history
- Can't be updated without code changes
- No security for real PII
- Easy for attackers to find

### ✅ AFTER (Secure)
```javascript
const mongoose = require('mongoose');

const userSchema = new mongoose.Schema({
  name: String,
  email: {
    type: String,
    lowercase: true,
    trim: true,
