    // Apply pagination
    const users = allUsers.slice(offset, offset + limit);

    logger.info({
      event: 'users_accessed',
      userId: req.user.id,
      count: users.length,
    });

    res.json({
      data: users,
      pagination: {
        total: allUsers.length,
        limit,
        offset,
      },
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================
app.use((err, req, res, next) => {
  logger.error({
    event: 'unhandled_error',
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
