      const response = await client.getSecretValue({
        SecretId: process.env.AWS_SECRET_ID || 'production/app-secrets'
      }).promise();

      // Parse and cache
      this.cache = JSON.parse(response.SecretString);
      this.cacheTime = Date.now();

      return this.cache;
    } catch (error) {
      console.error('AWS Secrets Manager error:', error);
      throw error;
    }
