### STEP 8: Pre-commit Hook to Prevent Secret Commits

```bash
cat > .git/hooks/pre-commit << 'EOF'
#!/bin/bash

# Patterns that indicate secrets
PATTERNS=(
  "AKIA[0-9A-Z]{16}"
  "sk_live_[0-9a-zA-Z]"
  "sk-ant-"
  "password\s*[:=]\s*[^\s]"
  "DATABASE_URL=.*@"
  "secret\s*[:=]"
)

for pattern in "${PATTERNS[@]}"; do
  if git diff --cached | grep -Ei "$pattern" > /dev/null 2>&1; then
    echo "❌ COMMIT BLOCKED: Potential secret detected!"
    echo "Pattern: $pattern"
    echo ""
    echo "✅ Solution: Add to .env.local and reference via process.env"
    exit 1
  fi
done

exit 0
EOF

chmod +x .git/hooks/pre-commit
```

