/**
 * Secure Secrets Manager Module
 * Handles loading secrets from appropriate source based on environment
 * 
 * Production: AWS Secrets Manager / HashiCorp Vault
 * Development: .env.local file (via dotenv)
 */

const AWS = require('aws-sdk');
require('dotenv').config({ path: '.env.local' });

class SecretsManager {
  constructor() {
    this.cache = null;
    this.cacheTime = null;
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  /**
   * Get secrets from appropriate source with caching
   */
  async getSecrets() {
    // Return cached secrets if not expired
    if (this.cache && Date.now() - this.cacheTime < this.cacheTTL) {
      return this.cache;
    }

    try {
      if (process.env.NODE_ENV === 'production') {
        return await this._getFromAWSSecretsManager();
      } else {
        return this._getFromEnv();
      }
    } catch (error) {
      console.error('❌ Failed to load secrets:', error.message);
      throw new Error('Unable to load application secrets');
    }
  }

  /**
   * Load from AWS Secrets Manager (Production)
   */
  async _getFromAWSSecretsManager() {
    const client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    try {
      const response = await client.getSecretValue({
        SecretId: process.env.AWS_SECRET_ID || 'production/app-secrets'
      }).promise();

      // Parse and cache
      this.cache = JSON.parse(response.SecretString);
      this.cacheTime = Date.now();

      console.log('✓ Secrets loaded from AWS Secrets Manager');
      return this.cache;
    } catch (error) {
      console.error('AWS Secrets Manager error:', error.message);
      throw error;
    }
  }

  /**
   * Load from environment variables (Development)
   */
  _getFromEnv() {
    const required = [
      'DATABASE_URL',
      'JWT_SECRET',
      'API_KEY'
    ];

    const missing = required.filter(key => !process.env[key]);
    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    const secrets = {};
    for (const key of required) {
      secrets[key] = process.env[key];
    }

    // Also include optional secrets
    const optional = [
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN'
    ];

    for (const key of optional) {
      if (process.env[key]) {
        secrets[key] = process.env[key];
      }
    }

    this.cache = secrets;
    this.cacheTime = Date.now();

    console.log('✓ Secrets loaded from environment');
    return secrets;
  }

  /**
   * SECURITY: Never expose raw secrets via JSON serialization
   */
  toString() {
    return '[SecretsManager]';
  }

  toJSON() {
    return '[SecretsManager]';
  }
}

// Export singleton instance
module.exports = new SecretsManager();

