/**
 * Audit Logger for Secrets Management
 * Logs all access to secrets for compliance and security monitoring
 */

const fs = require('fs');
const path = require('path');

class AuditLogger {
  constructor() {
    this.logDir = path.join(process.cwd(), 'logs');
    this.ensureLogDir();
  }

  ensureLogDir() {
    if (!fs.existsSync(this.logDir)) {
      fs.mkdirSync(this.logDir, { recursive: true });
    }
  }

  /**
   * Log secret access event
   */
  logSecretAccess(secretName, action, metadata = {}) {
    const entry = {
      timestamp: new Date().toISOString(),
      secretName,
      action,
      user: process.env.USER || process.env.USERNAME || 'system',
      environment: process.env.NODE_ENV,
      hostname: require('os').hostname(),
      ...metadata
    };

    const logFile = path.join(this.logDir, 'secrets-audit.log');

    try {
      fs.appendFileSync(logFile, JSON.stringify(entry) + '\n');
      console.log(`[AUDIT] ${secretName}: ${action}`);
    } catch (error) {
      console.error(`Failed to write audit log: ${error.message}`);
    }
  }

  /**
   * Log secret rotation event
   */
  logSecretRotation(secretName, reason) {
    this.logSecretAccess(secretName, 'ROTATED', { reason });
  }

  /**
   * Log failed access attempt
   */
  logFailedAccess(secretName, error) {
    this.logSecretAccess(secretName, 'FAILED', { error: error.message });
  }

  /**
   * Get audit logs (for monitoring/debugging)
   */
  getAuditLogs(lines = 50) {
    const logFile = path.join(this.logDir, 'secrets-audit.log');

    if (!fs.existsSync(logFile)) {
      return [];
    }

    const content = fs.readFileSync(logFile, 'utf8');
    return content
      .split('\n')
      .filter(line => line.trim())
      .slice(-lines)
      .map(line => {
        try {
          return JSON.parse(line);
        } catch {
          return { raw: line };
        }
      });
  }
}

module.exports = new AuditLogger();

