  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
// Now requires valid JWT token in Authorization header
```

---

## 2. INPUT VALIDATION - Preventing Injection Attacks

### ❌ BEFORE (Vulnerable)
```javascript
app.get('/users', (req, res) => {
  const filter = req.query.filter; // No validation!
  // Could be exploited: ?filter='; DROP TABLE users;--

  res.json([...]);
});
```

### ✅ AFTER (Secure)
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users',
  query('filter').optional().isString().trim().escape(),
  query('limit').optional().isInt({ min: 1, max: 100 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const filter = req.query.filter; // Safe & validated
    res.json([...]);
  }
);
```

---

## 3. SECURITY HEADERS - Preventing Clickjacking & XSS

### ❌ BEFORE (Vulnerable)
```javascript
const express = require('express');
const app = express();
// No security headers at all!
// Vulnerable to: XSS, clickjacking, MIME sniffing, SSL stripping
```

### ✅ AFTER (Secure)
```javascript
const express = require('express');
const helmet = require('helmet');
const app = express();

app.use(helmet()); // Sets 15+ security headers

// Output headers:
// Strict-Transport-Security: max-age=31536000; includeSubDomains; preload
// X-Content-Type-Options: nosniff
// X-Frame-Options: DENY
// X-XSS-Protection: 1; mode=block
// Content-Security-Policy: ...
// And 10+ more!
```

---

## 4. RATE LIMITING - Preventing Brute Force & DDoS

### ❌ BEFORE (Vulnerable)
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
});
// Anyone can hammer the endpoint 1000x per second
// Perfect for brute force or DDoS attacks
```

### ✅ AFTER (Secure)
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 minutes
  max: 100,                  // 100 requests per window
  message: 'Too many requests, please try again later.',
  keyGenerator: (req) => req.user?.id || req.ip // Use user ID if available
});

app.use(limiter); // Apply to all routes

// Stricter limit for auth endpoints
