  windowMs: 15 * 60 * 1000,
  max: 5,  // Only 5 attempts per 15 minutes
});

app.post('/login', authLimiter, (req, res) => { ... });
```

---

## 5. CORS - Preventing Cross-Origin Attacks

### ❌ BEFORE (Vulnerable)
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
});
// Default CORS behavior may allow any origin
// Vulnerable to CSRF and unauthorized requests
```

