/**
 * Secure Express Application with Proper Secrets Management
 * 
 * This version implements best practices for handling sensitive credentials:
 * 1. No hardcoded secrets
 * 2. Proper environment variable validation
 * 3. Secrets manager support for production
 * 4. Secure error handling
 */

// Load environment variables ONLY from .env.local (dev) or process env (prod)
// IMPORTANT: .env.local should NOT be committed to git
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config({ path: '.env.local' });
}

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ======================
// Configuration Validation
// ======================

/**
 * Validate required environment variables exist
 * Fails fast if critical configuration is missing
 */
function validateConfiguration() {
  const requiredVars = [
    'NODE_ENV',
    'PORT',
    'DATABASE_URL'
  ];

  const isProd = process.env.NODE_ENV === 'production';

  // Additional requirements for production
  if (isProd) {
    requiredVars.push('JWT_SECRET');
    requiredVars.push('ANTHROPIC_API_KEY');
  }

  const missing = [];
  for (const envVar of requiredVars) {
    if (!process.env[envVar]) {
      missing.push(envVar);
    }
  }

  if (missing.length > 0) {
    console.error('❌ Missing required environment variables:');
    missing.forEach(v => console.error(`   - ${v}`));
    console.error('\nPlease set these variables before starting the application.');
    process.exit(1);
  }

  console.log('✅ Configuration validation passed');
}

// ======================
// Secrets Manager Integration
// ======================

/**
 * Retrieve secrets from appropriate store based on environment
 * In production: AWS Secrets Manager
 * In development: environment variables (.env.local)
 */
async function loadSecrets() {
  const isProd = process.env.NODE_ENV === 'production';
  const secrets = {};

  if (isProd && process.env.USE_AWS_SECRETS_MANAGER === 'true') {
    try {
      const AWS = require('aws-sdk');
      const client = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      console.log('🔐 Loading secrets from AWS Secrets Manager...');

      try {
        const response = await client.getSecretValue({
          SecretId: 'prod/myapp-secrets'
        }).promise();

        Object.assign(secrets, JSON.parse(response.SecretString));
        console.log('✅ Secrets loaded from AWS');
      } catch (error) {
        console.error('❌ Failed to load secrets from AWS:', error.message);
        throw error;
      }
    } catch (error) {
      console.error('⚠️  AWS SDK not available, falling back to environment variables');
      // Fall back to environment variables
      secrets.database_url = process.env.DATABASE_URL;
      secrets.jwt_secret = process.env.JWT_SECRET;
      secrets.anthropic_api_key = process.env.ANTHROPIC_API_KEY;
    }
  } else {
    // Development: use environment variables
    console.log('🔧 Using environment variables for secrets (development mode)');
    secrets.database_url = process.env.DATABASE_URL;
    secrets.jwt_secret = process.env.JWT_SECRET;
    secrets.anthropic_api_key = process.env.ANTHROPIC_API_KEY;
    secrets.stripe_secret = process.env.STRIPE_SECRET_KEY;
  }

  // Validate critical secrets
  if (!secrets.database_url) {
    throw new Error('DATABASE_URL secret is required');
  }

  return secrets;
}

// ======================
// Security Middleware
// ======================

// Remove X-Powered-By header
app.disable('x-powered-by');

// Security headers
app.use(helmet());

// CORS configuration
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

const cors = require('cors');
app.use(cors(corsOptions));

// Request size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: false }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// Request timeout
app.use((req, res, next) => {
  req.setTimeout(10000); // 10 second timeout
  next();
});

// ======================
// Routes
// ======================

/**
 * Health check endpoint
 * Safe to expose - minimal information disclosure
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    environment: process.env.NODE_ENV
  });
});

/**
 * Protected users endpoint
 * Requires authentication in production
 */
app.get('/users', (req, res) => {
  // In production, this would require authentication
  if (process.env.NODE_ENV === 'production') {
    return res.status(401).json({ error: 'Authentication required' });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ======================
// Error Handling
// ======================

/**
 * Global error handler
 * Logs detailed errors server-side, returns safe responses to client
 */
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV !== 'production';

  // Log error server-side
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Send safe response to client
  const statusCode = err.statusCode || 500;
  const response = {
    error: isDev ? err.message : 'Internal server error'
  };

  if (isDev) {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

/**
 * 404 handler
 */
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// ======================
// Server Initialization
// ======================

/**
 * Initialize and start the server
 * Validates configuration and loads secrets before starting
 */
async function startServer() {
  try {
    // Validate configuration
    validateConfiguration();

    // Load secrets
    const secrets = await loadSecrets();

    // Store secrets in app context (not global variables)
    app.locals.secrets = secrets;

    // Start server
    const PORT = process.env.PORT || 3000;
    const server = app.listen(PORT, () => {
      console.log(`\n✅ Server running on port ${PORT}`);
      console.log(`📍 Environment: ${process.env.NODE_ENV}`);
      console.log(`🔐 Secrets loaded successfully\n`);
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      console.log('📴 SIGTERM received, shutting down gracefully...');
      server.close(() => {
        console.log('🛑 Server closed');
        process.exit(0);
      });
    });

    // Handle unhandled rejections
    process.on('unhandledRejection', (reason, promise) => {
      console.error('❌ Unhandled Rejection at:', promise, 'reason:', reason);
      process.exit(1);
    });

  } catch (error) {
    console.error('❌ Failed to start server:', error.message);
    process.exit(1);
  }
}

// Start the server
startServer();

module.exports = app;

