### 1. **Missing Input Validation & Output Encoding** ⚠️ MEDIUM
**Risk:** If query parameters, path parameters, or request body are added, they need validation.

**Issue:** Currently, no routes accept user input, but `app.get('/users')` could be extended to filter/search.

**Vulnerable Code Example (if extended):**
```javascript
app.get('/users', (req, res) => {
  const name = req.query.name;
  // Directly returning user data based on unvalidated input
  res.json(users.filter(u => u.name === name)); // Could leak data
});
```

**✅ Secure Implementation:**
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users', 
  query('name')
    .optional()
    .isString()
    .trim()
    .isLength({ max: 50 })
    .matches(/^[a-zA-Z\s'-]+$/) // Only allow letters, spaces, hyphens, apostrophes
    .escape(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const name = req.query.name;
    const filtered = name 
      ? users.filter(u => u.name.toLowerCase() === name.toLowerCase())
      : users;

    res.json(filtered);
  }
);
```

---

### 2. **Missing Authentication & Authorization** ⚠️ HIGH
**Risk:** `/users` endpoint exposes sensitive data without any authentication.

**Issue:** Email addresses and user IDs are publicly accessible to anyone.

**✅ Secure Implementation:**
```javascript
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users can access
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### 3. **Missing Security Headers** ⚠️ MEDIUM
**Risk:** Application lacks protection against common web attacks (XSS, Clickjacking, etc.)

**✅ Implementation using `helmet`:**
```javascript
const helmet = require('helmet');

const express = require('express');
const app = express();

// Add security headers
app.use(helmet());

// Additional security configurations
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", "data:", "https:"],
  },
}));

app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true
}));
```

---

### 4. **No Rate Limiting** ⚠️ MEDIUM
**Risk:** Application is vulnerable to brute force, DoS, and enumeration attacks.

**✅ Implementation:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

const strictLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 5, // Stricter limit for auth endpoints
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter limit for login/sensitive endpoints (if added)
// app.post('/login', strictLimiter, loginHandler);
```

---

### 5. **Missing CORS Configuration** ⚠️ MEDIUM
**Risk:** Uncontrolled CORS could allow unauthorized cross-origin access.

**✅ Implementation:**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: function (origin, callback) {
    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];

    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};

app.use(cors(corsOptions));
```

---

### 6. **No Logging/Monitoring** ⚠️ MEDIUM
**Risk:** Cannot detect or investigate security incidents.

**✅ Implementation:**
```javascript
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

// Create logs directory if it doesn't exist
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir);
}

const accessLogStream = fs.createWriteStream(
  path.join(logsDir, 'access.log'),
  { flags: 'a' }
);

// Log all requests (exclude sensitive data)
app.use(morgan(':remote-addr - [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length]', 
  { stream: accessLogStream }
));
```

---

### 7. **No Environment Configuration** ⚠️ HIGH
**Risk:** Hardcoded values and secrets can be exposed.

**✅ Implementation:**
```javascript
require('dotenv').config();

const express = require('express');
const app = express();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

if (NODE_ENV === 'production') {
  app.set('trust proxy', 1); // Trust proxy headers
}

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);
});
```

**.env file:**
```
PORT=3000
NODE_ENV=development
JWT_SECRET=your-secret-key-generate-this-safely
ALLOWED_ORIGINS=http://localhost:3000,https://yourdomain.com
```

---

### 8. **No Input Size Limits** ⚠️ MEDIUM
**Risk:** Large payloads can cause DoS or memory exhaustion.

**✅ Implementation:**
```javascript
// Limit request body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));
```

---

### 9. **Sensitive Data in Responses** ⚠️ MEDIUM
**Risk:** Error messages might leak internal system information.

**✅ Implementation:**
```javascript
// Global error handler - never expose stack traces in production
app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV === 'development';

  console.error(err); // Log the full error internally

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});
```

---

## Secure app.js Template

Here's a hardened version incorporating all recommendations:

```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { query, validationResult } = require('express-validator');
const fs = require('fs');
const path = require('path');

const app = express();

// ============= SECURITY MIDDLEWARE =============

// Security headers
app.use(helmet());

// CORS
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
};
app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Logging
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) fs.mkdirSync(logsDir);
const accessLogStream = fs.createWriteStream(
  path.join(logsDir, 'access.log'),
  { flags: 'a' }
);
app.use(morgan('combined', { stream: accessLogStream }));

// ============= ROUTES =============

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ============= ERROR HANDLING =============

app.use((err, req, res, next) => {
  console.error(err);
  const isDev = process.env.NODE_ENV === 'development';
  res.status(err.status || 500).json({
    error: isDev ? err.message : 'Internal server error',
  });
});

// ============= SERVER START =============

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

