/**
 * SECURE APPLICATION USING AWS SECRETS MANAGER
 * This demonstrates best practices for secrets management
 */

require('dotenv').config(); // Only for development
const express = require('express');
const AWS = require('aws-sdk');
const helmet = require('helmet');

/**
 * SECRETS MANAGER CLASS
 * Handles all secret retrieval with caching and rotation
 */
class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour cache
    this.cacheTimestamps = new Map();
  }

  /**
   * Get secret value with caching
   * @param {string} secretName - Name of secret in AWS Secrets Manager
   * @returns {Promise<Object>} Secret object
   */
  async getSecret(secretName) {
    // Check cache first
    if (this.isCacheFresh(secretName)) {
      console.log(`[CACHE HIT] Retrieved ${secretName} from cache`);
      return this.cache.get(secretName);
    }

    try {
      console.log(`[FETCHING] Retrieving secret: ${secretName}`);
      const data = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, secret);
      this.cacheTimestamps.set(secretName, Date.now());

      console.log(`[SUCCESS] Secret loaded: ${secretName}`);
      return secret;
    } catch (error) {
      console.error(`[ERROR] Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error(`Secret retrieval failed for ${secretName}`);
    }
  }

  /**
   * Check if cached value is still fresh
   */
  isCacheFresh(secretName) {
    if (!this.cache.has(secretName)) return false;
    const timestamp = this.cacheTimestamps.get(secretName);
    return Date.now() - timestamp < this.cacheTTL;
  }

  /**
   * Clear cache (useful for testing/rotation)
   */
  clearCache() {
    this.cache.clear();
    this.cacheTimestamps.clear();
    console.log('[CACHE] Cache cleared');
  }
}

/**
 * APPLICATION INITIALIZATION
 */
const secretsManager = new SecretsManager();
let app;

async function initializeApplication() {
  try {
    // Load secrets based on environment
    const environment = process.env.NODE_ENV || 'development';
    console.log(`\n🚀 Initializing application (${environment})\n`);

    let secrets = {};

    if (environment === 'production') {
      // Production: Use AWS Secrets Manager ONLY
      secrets = await Promise.all([
        secretsManager.getSecret('prod/database'),
        secretsManager.getSecret('prod/stripe'),
        secretsManager.getSecret('prod/aws-credentials'),
        secretsManager.getSecret('prod/anthropic'),
        secretsManager.getSecret('prod/logfire')
      ]).then(([db, stripe, aws, anthropic, logfire]) => ({
        database: db,
        stripe: stripe,
        aws: aws,
        anthropic: anthropic,
        logfire: logfire
      }));

      console.log('✅ Loaded all secrets from AWS Secrets Manager');
    } else {
      // Development: Use .env file (which should be gitignored)
      secrets = {
        database: {
          url: process.env.DATABASE_URL
        },
        stripe: {
          key: process.env.STRIPE_SECRET_KEY
        },
        aws: {
          accessKeyId: process.env.AWS_ACCESS_KEY_ID,
          secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
        },
        anthropic: {
          apiKey: process.env.ANTHROPIC_API_KEY
        },
        logfire: {
          token: process.env.LOGFIRE_TOKEN
        }
      };

      console.log('⚠️  Using .env file (development mode)');
      console.log('🔒 Ensure .env is in .gitignore and never commit secrets\n');
    }

    // Validate required secrets
    validateSecrets(secrets);

    // Create Express app with security middleware
    app = createSecureApp(secrets);

    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`✅ Server running on port ${PORT}\n`);
    });

  } catch (error) {
    console.error('❌ Failed to initialize application:', error);
    process.exit(1);
  }
}

/**
 * VALIDATE THAT REQUIRED SECRETS ARE PRESENT
 */
function validateSecrets(secrets) {
  const required = ['database', 'stripe', 'aws', 'anthropic'];

  for (const key of required) {
    if (!secrets[key]) {
      throw new Error(`Missing required secret: ${key}`);
    }
  }

  console.log('✅ All required secrets validated\n');
}

/**
 * CREATE SECURE EXPRESS APP
 */
function createSecureApp(secrets) {
  const app = express();

  // Security middleware
  app.use(helmet());
  app.use(express.json({ limit: '10kb' }));

  // Hide sensitive headers
  app.disable('x-powered-by');

  // Health check endpoint (no sensitive data)
  app.get('/health', (req, res) => {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development'
    });
  });

  // Protected endpoint that uses secrets
  app.get('/api/protected', authenticateRequest, (req, res) => {
    // Secrets are available here, but never exposed in response
    res.json({
      message: 'This endpoint uses secrets securely',
      timestamp: new Date().toISOString()
    });
  });

  // Error handling middleware
  app.use((err, req, res, next) => {
    const isDev = process.env.NODE_ENV === 'development';
    console.error('[ERROR]', err.message);

    res.status(err.status || 500).json({
      error: isDev ? err.message : 'Internal server error',
      requestId: req.id || 'unknown'
    });
  });

  return app;
}

/**
 * AUTHENTICATION MIDDLEWARE
 */
function authenticateRequest(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Verify token (implementation depends on your auth system)
  next();
}

/**
 * GRACEFUL SHUTDOWN
 */
process.on('SIGTERM', () => {
  console.log('📴 SIGTERM received, shutting down gracefully...');
  secretsManager.clearCache();
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('📴 SIGINT received, shutting down gracefully...');
  secretsManager.clearCache();
  process.exit(0);
});

// Start the application
initializeApplication().catch(error => {
  console.error('Fatal error:', error);
  process.exit(1);
});

module.exports = { app, secretsManager };
