});
```

**Recommended Fix**:
```javascript
const helmet = require('helmet');
const express = require('express');
const app = express();

// Add security headers
app.use(helmet());

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

---

### 2. **Sensitive Data Exposure (OWASP A02:2021 – Cryptographic Failures)**
**Severity**: HIGH

**Issue**: The `/users` endpoint exposes sensitive user information without authentication or rate limiting:
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Problems**:
- Anyone can access user data
- No authentication required
- Email addresses are exposed
- No authorization checks

**Recommended Fix**:
```javascript
const authenticate = require('./middleware/auth'); // Your auth middleware

app.get('/users', authenticate, (req, res) => {
  // Check if user has permission to view users list
  if (!req.user.isAdmin && req.user.role !== 'manager') {
    return res.status(403).json({ 
      error: 'Forbidden: Insufficient permissions' 
    });
  }

  // Only return non-sensitive user data
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];

  res.json(users);
});
```

---

### 3. **No Input Validation (OWASP A03:2021 – Injection)**
**Severity**: MEDIUM-HIGH

**Issue**: The application doesn't validate or sanitize any input parameters.

**Current Code**: No query parameters are being validated in either endpoint.

**Recommended Fix** - Add input validation:
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users', 
  authenticate,
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    res.json({
      users: users.slice(offset, offset + limit),
      total: users.length
    });
  }
);
```

---

### 4. **Missing CORS Configuration (OWASP A01:2021 – Broken Access Control)**
**Severity**: MEDIUM

**Issue**: CORS is not configured, potentially allowing cross-origin attacks or restricting legitimate clients.

**Current Code**: No CORS middleware present.

**Recommended Fix**:
```javascript
const cors = require('cors');

// Restrict CORS to trusted origins only
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};

app.use(cors(corsOptions));
```

