## OPTION 1: AWS Secrets Manager (Recommended for AWS Users)

### Setup

```bash
# Install AWS SDK
npm install @aws-sdk/client-secrets-manager
```

### Implementation

**config/secrets.js**:
```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

let secretsCache = null;
let cacheExpiry = null;

async function getSecrets() {
  const now = Date.now();

  // Cache secrets for 1 hour
  if (secretsCache && cacheExpiry && now < cacheExpiry) {
    console.log('[SECRETS] Using cached secrets');
    return secretsCache;
  }

  try {
    const secretName = process.env.SECRET_NAME || 'myapp/production/secrets';

    const command = new GetSecretValueCommand({
      SecretId: secretName,
    });

    const response = await client.send(command);

    // Parse the secret
    let secret;
    if ('SecretString' in response) {
      secret = JSON.parse(response.SecretString);
    } else {
      // Binary secret
      const buff = Buffer.from(response.SecretBinary, 'base64');
      secret = JSON.parse(buff.toString('ascii'));
    }

    // Cache the secrets
    secretsCache = secret;
    cacheExpiry = now + (60 * 60 * 1000); // 1 hour

    console.log('[SECRETS] Loaded secrets from AWS Secrets Manager');
    return secret;

  } catch (error) {
    console.error('[SECRETS] Failed to retrieve secrets:', error.message);

    // Fallback to environment variables in development
    if (process.env.NODE_ENV === 'development') {
      console.warn('[SECRETS] Falling back to environment variables');
      return {
        DATABASE_URL: process.env.DATABASE_URL,
        AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
        AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
        ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
        STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
        LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
      };
    }

    throw new Error('Failed to load secrets and no fallback available');
  }
}

module.exports = { getSecrets };
```

**Updated app.js**:
