## OPTION 2: HashiCorp Vault (Enterprise-Grade)

### Setup

```bash
# Install Vault client
npm install node-vault
```

### Implementation

**config/vault.js**:
```javascript
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
  token: process.env.VAULT_TOKEN,
});

async function getSecretsFromVault() {
  try {
    const path = process.env.VAULT_PATH || 'secret/data/myapp/production';

    const response = await vault.read(path);

    // Vault returns secrets in response.data.data
    return response.data.data;

  } catch (error) {
    console.error('[VAULT] Failed to retrieve secrets:', error.message);

    if (process.env.NODE_ENV === 'development') {
      console.warn('[VAULT] Falling back to environment variables');
      return process.env;
    }

    throw error;
  }
}

// Refresh secrets periodically
async function startVaultRefresh(intervalMs = 3600000) {
  setInterval(async () => {
    try {
      await getSecretsFromVault();
      console.log('[VAULT] Secrets refreshed');
    } catch (error) {
      console.error('[VAULT] Failed to refresh secrets:', error.message);
    }
  }, intervalMs);
}

module.exports = { getSecretsFromVault, startVaultRefresh };
```

