**app.js with Docker Secrets**:
```javascript
const fs = require('fs');
const path = require('path');

function loadDockerSecret(secretName) {
  try {
    const secretPath = path.join('/run/secrets', secretName);
    const secretContent = fs.readFileSync(secretPath, 'utf8');
    return secretContent.trim();
  } catch (error) {
    console.warn(`[SECRETS] Docker secret '${secretName}' not found, using env var`);
    return process.env[secretName.toUpperCase()];
  }
}

const secrets = {
  DATABASE_URL: loadDockerSecret('database_url'),
  STRIPE_SECRET_KEY: loadDockerSecret('stripe_key'),
  AWS_ACCESS_KEY_ID: loadDockerSecret('aws_key'),
  AWS_SECRET_ACCESS_KEY: loadDockerSecret('aws_secret'),
};

module.exports = secrets;
```

